packages/database/prisma/schema.prisma.content:
generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

enum FulfillmentMethod {
  FBA
  FBM
}

enum CampaignType {
  SP // Sponsored Products
  SB // Sponsored Brands
  SD // Sponsored Display
  DSP // AX3.3 — Amazon DSP (Performance+ / Brand+)
}

enum CampaignStatus {
  ENABLED
  PAUSED
  ARCHIVED
  DRAFT // AD.1: pre-sync locally-authored campaigns
}

// AD.1 — Amazon Advertising bidding strategy (SP campaigns only;
// SB / SD use different shapes Amazon-side).
enum BiddingStrategy {
  LEGACY_FOR_SALES // up-to-100% downward, no upward
  AUTO_FOR_SALES // dynamic, up + down
  MANUAL // operator-set
}

// AD.1 — sync-lifecycle status for advertising entities (campaign,
// ad-group, target). Mirrors OutboundSyncStatus shape but kept
// distinct so a future schema change to OutboundSyncStatus doesn't
// bleed into operator-visible advertising state.
enum AdSyncStatus {
  PENDING
  IN_PROGRESS
  SUCCESS
  FAILED
  SKIPPED
}

enum ShipmentStatus {
  WORKING
  SHIPPED
  IN_TRANSIT
  RECEIVING
  CLOSED
}

enum SyncChannel {
  AMAZON
  EBAY
  SHOPIFY
  WOOCOMMERCE
  // UM.9/11/12/13 — external marketing-channel mutation routing targets.
  GOOGLE
  META
  TIKTOK
}

enum OutboundSyncStatus {
  PENDING
  IN_PROGRESS
  SUCCESS
  FAILED
  SKIPPED
  CANCELLED
}

enum PricingRuleType {
  FIXED
  MATCH_AMAZON
  PERCENT_OF_MASTER
}

model Product {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                String  @id @default(cuid())
  sku               String
  name              String
  basePrice         Decimal @db.Decimal(10, 2)
  totalStock        Int     @default(0)
  lowStockThreshold Int     @default(10) // Phase 23.2: Alert threshold for low-stock situations

  // Marketplace mapping (parent-level: non-buyable parent ASIN, shared eBay listing ID)
  amazonAsin           String?
  ebayItemId           String?
  ebayTitle            String?
  shopifyProductId     String?
  woocommerceProductId Int?

  // Identifiers (used for standalone products with no variations)
  upc          String?
  ean          String?
  brand        String?
  manufacturer String?

  // Physical attributes (defaults — variants can override)
  weightValue Decimal? @db.Decimal(10, 3)
  weightUnit  String? // e.g., 'lb', 'kg', 'oz'
  dimLength   Decimal? @db.Decimal(10, 2)
  dimWidth    Decimal? @db.Decimal(10, 2)
  dimHeight   Decimal? @db.Decimal(10, 2)
  dimUnit     String? // e.g., 'in', 'cm'

  // Content (shared/inherited by all variants)
  description  String? // D.5: HTML body shown on listings (master-level)
  bulletPoints String[] // Amazon-style bullet points
  aPlusContent Json? // Rich text / A+ Content as JSON
  keywords     String[] // Search keywords

  // Fulfillment (default — variants can override)
  fulfillmentMethod FulfillmentMethod? // FBA or FBM

  // ── NEW: Variation theme (Rithum pattern) ────────────────────────────
  // Defines which attributes create the variation matrix.
  // null = standalone product (parent is the purchasable SKU).
  // Examples: "Size", "Color", "SizeColor", "SizeColorMaterial"
  variationTheme String?

  // ── NEW: Product status ──────────────────────────────────────────────
  status String @default("ACTIVE") // DRAFT, ACTIVE, INACTIVE

  // ── NEW: Dynamic PIM Fields (Phase 7) ─────────────────────────────
  // Amazon product type (e.g., "LUGGAGE", "OUTERWEAR", "ELECTRONICS")
  productType String?

  // Flexible JSON storage for category-specific attributes
  // Structure: { "voltage": "110V", "apparel_size": "M", "material": "Cotton" }
  categoryAttributes Json?

  // ── PIM A.1 — Localized content layer ────────────────────────────
  // Per-locale overrides for content fields (title, description,
  // bulletPoints, keywords, etc.). Structure:
  //   { "en": { "title": "...", "description": "..." },
  //     "it": { "title": "...", "description": "..." } }
  // Empty locale objects fall back through attribute-resolver merge
  // (locale → en → master columns). Variant child Products override
  // their parent via the existing parent/child hierarchy.
  // LX: legacy JSON; reader/writer boundaries migrate in Steps 3/4.
  // No database guard: deployed writers must remain operational until then.
  // No backfill: new translations are authored in ProductTranslation.
  localizedContent Json @default("{\"en\":{},\"it\":{}}")

  // ── W2.1 — ProductFamily (Akeneo cornerstone) ────────────────────
  // Optional FK to a Family template that declares which attribute
  // groups + per-channel rules apply to this product. Wave 2 builds
  // on this with FamilyAttribute (W2.2) + AttributeSet (W2.3+).
  // SetNull on family delete so detaching a family doesn't cascade-
  // wipe products; they revert to the loose categoryAttributes JSON.
  familyId String?
  family   ProductFamily? @relation("ProductFamily", fields: [familyId], references: [id], onDelete: SetNull)

  // ── W3.1 — ProductWorkflow stage tracking (Salesforce parity) ────
  // Current stage in the content-quality pipeline (DRAFT → REVIEW →
  // APPROVED → PUBLISHED). Distinct from `status` (which is the
  // operational ACTIVE/INACTIVE/DRAFT lifecycle that cascades to
  // marketplaces): workflowStage is the *internal* gate before the
  // operator flips status to ACTIVE.
  //
  // SetNull on stage delete so removing a stage from a workflow
  // doesn't cascade-wipe products (they fall off the workflow but
  // keep their data — re-attaching via family is the recovery path).
  workflowStageId     String?
  workflowStage       WorkflowStage?       @relation("ProductCurrentStage", fields: [workflowStageId], references: [id], onDelete: SetNull)
  workflowTransitions WorkflowTransition[] @relation("ProductWorkflowTransitions")
  workflowComments    WorkflowComment[]    @relation("ProductWorkflowComments")

  // ── W4.1 — Tier pricing (Magento parity) ──────────────────────
  // Volume-discount + customer-group pricing. tierPrices[] holds
  // per-(minQty, optional customerGroup) discount rows; the
  // resolver (W4.2) picks the highest-minQty row whose threshold is
  // met. Independent of Product.basePrice — base remains the
  // anonymous-customer / qty=1 fallback.
  tierPrices ProductTierPrice[]

  // ── W4.4 — DAM (Plytix DigitalAsset library) ──────────────────
  // Back-relation to AssetUsage rows that reference this product.
  // ProductImage stays as the legacy image storage; AssetUsage layer
  // sits on top + supports asset reuse across products without a
  // duplicate upload. Migration plan in a follow-up Wave 4 commit.
  assetUsages AssetUsage[]

  // MC.8.1 — A+ Content asin attachments (Amazon Brand Registry).
  // One Product can be attached to many APlusContent rows (one per
  // marketplace × locale combination); deleting the product unsets
  // the link without dropping the A+ content itself.
  aPlusContentAttachments APlusContentAsin[]

  // ── W4.6 — Repricing rules (Rithum cornerstone) ───────────────
  // Per-(product, channel, marketplace) repricing config: min/max
  // price + strategy + schedule. The repricing engine (W4.7+) reads
  // these to decide what price to push. Decisions are logged in
  // RepricingDecision rows for the audit trail.
  repricingRules    RepricingRule[]
  // PH.1 — unified price-change timeline (one row per live price change).
  priceChangeEvents PriceChangeEvent[]

  // ── PIM Category taxonomy (net-new) ───────────────────────────
  // M:N membership in the internal infinite-depth category tree
  // (Category + CategoryClosure). Distinct from marketplace
  // CategorySchema (Amazon/eBay product-type attribute schemas).
  // One row per (product, category); one flagged isPrimary for the
  // breadcrumb/face category. Cascade on product delete.
  categories ProductCategory[]

  // Pricing intelligence
  costPrice       Decimal? @db.Decimal(10, 2) // Cost of goods for margin calc
  minMargin       Decimal? @db.Decimal(5, 2) // Minimum acceptable margin percentage (e.g., 15 for 15%)
  minPrice        Decimal? @db.Decimal(10, 2) // Pricing floor
  maxPrice        Decimal? @db.Decimal(10, 2) // Pricing ceiling
  buyBoxPrice     Decimal? @db.Decimal(10, 2) // Current Buy Box price
  competitorPrice Decimal? @db.Decimal(10, 2) // Lowest competitor price

  // Inventory intelligence
  firstInventoryDate DateTime? // For aging calculations

  // S.16 — ABC classification (materialized weekly via abc-classification.job).
  // 'A' = top 80% cumulative metric (revenue by default), 'B' = next 15%,
  // 'C' = remaining sales-active, 'D' = zero sales in window, NULL =
  // never classified yet. TEXT (not enum) so per-channel splits can land
  // without a migration.
  abcClass          String? // 'A' | 'B' | 'C' | 'D' | null
  abcClassUpdatedAt DateTime?

  // S.20 — Costing methodology. Default WAC (weighted average cost):
  // simplest and statistically-fair for mixed catalogs. Operators
  // can switch per-product to FIFO (perishable / fashion / falling-
  // price) or LIFO (rising-price tax shelter). TEXT not enum so we
  // can add 'STANDARD' / 'SPECIFIC' methods later without a migration.
  costingMethod        String           @default("WAC")
  // Rolling weighted-average cost in cents. Recomputed at every
  // receive when costingMethod = 'WAC'. NULL until first receive
  // (or until backfill runs).
  weightedAvgCostCents Int?
  // Per-receive cost layers (FIFO/LIFO consume from these).
  costLayers           StockCostLayer[]

  // B2B pricing
  b2bPrice  Decimal? @db.Decimal(10, 2) // Business pricing
  b2bMinQty Int? // Minimum B2B quantity

  // ── Parent/Child Hierarchy (Amazon Catalog Sync) ─────────────────
  isParent Boolean   @default(false) // TRUE if this is a master parent
  isBundle Boolean   @default(false) // BD.1: bundle-product flag — components in BundleComponent
  parentId String? // Self-relation: parent product ID
  parent   Product?  @relation("ProductHierarchy", fields: [parentId], references: [id], onDelete: Cascade)
  children Product[] @relation("ProductHierarchy") // Child variations

  // ── Amazon Parent ASIN (non-buyable) ────────────────────────────
  parentAsin String? // Parent ASIN from Amazon (non-buyable)

  // ── Fulfillment Channel ─────────────────────────────────────────
  fulfillmentChannel FulfillmentMethod? // FBA or FBM (default for all variations)

  // ── Shipping Template (FBM only) ────────────────────────────────
  shippingTemplate String? // e.g., "Xavia FBM Shipping Template"

  // ── Sync Metadata ───────────────────────────────────────────────
  lastAmazonSync   DateTime?
  amazonSyncStatus String? // SUCCESS, FAILED, PENDING
  amazonSyncError  String?

  // ── PHASE 9: Master Catalog Metadata ──────────────────────────────
  // Indicates this is a master product (not a variation)
  isMasterProduct Boolean @default(true)

  // Master product reference (for variations)
  masterProductId  String?
  masterProduct    Product?  @relation("MasterVariations", fields: [masterProductId], references: [id], onDelete: Cascade)
  masterVariations Product[] @relation("MasterVariations")

  // ── PHASE D.3: Bulk-ops cascade + master-level GTIN ──────────────
  // Tracks which fields on this row were inherited from a parent
  // cascade. Updated by PATCH /api/products/bulk when cascade=true.
  cascadedFields String[] @default([])
  // Master-level GTIN for products without variations (Amazon accepts
  // GTIN at master OR variant level). Per-variant GTIN lives on
  // ProductVariation.gtin.
  gtin           String?
  fnsku          String? // Amazon Fulfillment Network SKU — cached from SP-API for child variants

  // ── PHASE 31: PIM Master Catalog Fields ──────────────────────────
  // True master entity flag (vs. isMasterProduct which is legacy)
  isMaster          Boolean   @default(false)
  // Internal master SKU (separate from channel SKUs)
  masterSku         String?
  // Variation axes for master products: ["Color", "Size", "BodyType"]
  variationAxes     String[]  @default([])
  // Channels this master is currently linked to (resolved listings)
  linkedToChannels  String[]  @default([])
  // Where this product came from
  importSource      String? // "AMAZON_AUTO_IMPORT" | "MANUAL" | "CSV_UPLOAD"
  importedAt        DateTime?
  // Review workflow state
  reviewStatus      String? // "PENDING_REVIEW" | "APPROVED" | "MERGED"
  // For child products: per-variant attribute values
  // Example: {"Color": "Black", "Size": "M", "BodyType": "Men"}
  variantAttributes Json?

  // IM.1 — Image axis preference for the images tab matrix view.
  // Persisted per product so the operator doesn't re-select each visit.
  // Defaults to "Color" when present; first available axis otherwise.
  imageAxisPreference String?

  // ── PHASE 20: SSOT Indicators ────────────────────────────────────
  // Track which channels this product is synced to
  syncChannels String[] @default([]) // ["AMAZON", "EBAY", "SHOPIFY"]

  // Overall validation state for this product
  validationStatus String   @default("VALID") // VALID, WARNING, ERROR
  validationErrors String[]

  // Track if this product has any channel-specific overrides
  hasChannelOverrides Boolean @default(false)

  // Last time any channel override was modified
  lastChannelOverrideAt DateTime?

  // Relations
  variations                ProductVariation[]
  images                    ProductImage[]
  listingImages             ListingImage[] // Phase A: per-listing image set (multi-scope)
  listingWizards            ListingWizard[] // Phase A: multi-channel wizards for this product
  channelListings           ChannelListing[]
  listingAliases            ProductListingAlias[] // PES.5 — extra listings of this product per coordinate
  channelListingImages      ChannelListingImage[]
  listings                  Listing[]
  draftListings             DraftListing[] // Phase 5: AI Listing Generator
  stockLogs                 StockLog[]
  marketplaceSyncs          MarketplaceSync[]
  fbaShipmentItems          FBAShipmentItem[]
  pricingRuleProducts       PricingRuleProduct[]
  syncHealthLogs            SyncHealthLog[]
  syncLogs                  SyncLog[]
  orderItems                OrderItem[] // Phase 2: Orders & Financials
  outboundSyncQueue         OutboundSyncQueue[] // Phase 8: Outbound Sync Engine
  stockLevels               StockLevel[] // H.1: per-location stock ledger
  fbaInventoryDetails       FbaInventoryDetail[] // S.25: per-FC FBA snapshot
  lots                      Lot[] // L.1: lot tracking for recall traceability
  serials                   SerialNumber[] // SR.1: per-unit serial tracking
  channelStockEvents        ChannelStockEvent[] // CS.1: channel→us stock reconciliation
  channelLiveImages         ChannelLiveImage[] // IE.4: read-replica of channel-served images
  scheduledImagePublishes   ScheduledImagePublish[] // PB.10: future-dated publish intents
  translations              ProductTranslation[] // H.10: per-language master content
  relationsFrom             ProductRelation[]             @relation("ProductRelationFrom") // H.11
  relationsTo               ProductRelation[]             @relation("ProductRelationTo") // H.11
  seoEntries                ProductSeo[] // W12: per-locale SEO metadata
  workflowAssignments       WorkflowAssignment[] // W9.x: per-product assignees
  recommendations           ReplenishmentRecommendation[] // R.3
  stockoutEvents            StockoutEvent[] // R.12
  substitutionsAsPrimary    ProductSubstitution[]         @relation("SubstitutionPrimary") // R.17
  substitutionsAsSubstitute ProductSubstitution[]         @relation("SubstitutionSubstitute") // R.17
  wizardStepEvents          WizardStepEvent[] // C.0: per-step wizard telemetry
  channelPublishAttempts    ChannelPublishAttempt[] // C.6: every publish attempt audit
  amazonImageFeedJobs       AmazonImageFeedJob[] // IM.1: Amazon image feed submissions
  channelImagePublishJobs   ChannelImagePublishJob[] // IR.9: eBay + Shopify image publish log
  listingRecoveryEvents     ListingRecoveryEvent[] // W5.49: delete+relist audit
  buyBoxHistory             BuyBoxHistory[] // Pricing F.1: Buy Box observation log
  scheduledChanges          ScheduledProductChange[] // F.3: deferred mutations
  adProductAds              AdProductAd[] // AD.1: Amazon Ads product-ad joins
  fbaStorageAges            FbaStorageAge[] // AD.1: aged-stock snapshots per poll
  productProfitDailies      ProductProfitDaily[] // AD.1: per-day True Profit roll-up
  reviews                   Review[] // SR.1: ingested customer reviews
  reviewSpikes              ReviewSpike[] // SR.1: detected category spikes
  amazonReviewInsights      AmazonReviewInsight[] // D.2: official Customer Feedback API insights
  qualitySnapshots          ListingQualitySnapshot[] // PA.2: listing quality history
  fieldLinkGroups           FieldLinkGroup[] // FL.1: cross-channel/market field-sharing groups
  skuAliases                SkuAlias[] // IM.1: alternate names / codes that resolve to this product

  // H.16 — Compliance master data. HS code = customs classification,
  // mostly 6-digit (HS) or 8-10 digit (CN/HTS); stored as text since
  // formats vary by destination. Country of origin is ISO-2.
  hsCode          String?
  countryOfOrigin String?

  // W7.1 — EU compliance fields (CE/PPE/Hazmat) for Italian operator
  // selling motorcycle gear across EU Amazon + eBay marketplaces.
  // PPE Directive 2016/425: Cat I (min risk), Cat II (intermediate),
  // Cat III (mortal risk — motorcycle helmets, body armour).
  ppeCategory                String? // 'CAT_I' | 'CAT_II' | 'CAT_III'
  // ADR/IATA hazardous materials flags (uncommon for apparel, but
  // needed for aerosols, chain lube, etc. in Xavia's accessories range).
  hazmatClass                String? // UN hazard class e.g. "3", "8", "9"
  hazmatUnNumber             String? // UN number e.g. "UN1950"
  // C4 — structured CE/PPE protective-gear data (motorcycle apparel). All
  // nullable; captured in the ComplianceTab + fed to the compliance resolver →
  // all 3 channels (eBay productSafety, Shopify metafields, Amazon attrs).
  garmentClass               String? // EN 17092 class: 'AAA' | 'AA' | 'A' | 'B' | 'C'
  notifiedBodyNumber         String? // 4-digit Notified Body id, e.g. '0494'
  notifiedBodyName           String? // e.g. 'Ricotest'
  declarationOfConformityUrl String? // Declaration of Conformity (DoC) link
  impactProtectors           Json? // [{ zone, standard, level }] — EN 1621-1/-2/-4
  // Back-relation to per-product certificate rows (CE, EN-13595, REACH…)
  certificates               ProductCertificate[]

  // R.4 — Replenishment economics. Per-product overrides for the
  // global defaults (95% service / 25% carrying cost / €15 ordering
  // cost). All nullable; code applies defaults when null.
  serviceLevelPercent Decimal? @db.Decimal(5, 2)
  orderingCostCents   Int?
  carryingCostPctYear Decimal? @db.Decimal(5, 2)

  // NN.1 — optimistic concurrency. Bumped on every PATCH/PUT.
  // Clients send the version they read; server rejects with 409 if
  // it advanced (someone else edited concurrently).
  version Int @default(1)

  // F.1 — soft delete. Set when the operator removes a product via
  // the bulk-soft-delete action; restorable until a separate cron /
  // admin task hard-purges old rows. NULL means active. All default
  // list / fetch endpoints filter `deletedAt IS NULL` unless the
  // caller explicitly opts in via ?deleted=true.
  deletedAt DateTime?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt


  /// PES.6 wave-4 — operator-authored per-cell formulas.
  cellFormulas CellFormula[]
  @@index([gtin])
  @@index([abcClass])
  @@index([deletedAt])
  // W1.10 — 10k SKU headroom indexes. Hot paths in /products grid:
  //   - (status, deletedAt): "list active non-deleted" — almost every
  //     list query. Composite so a single B-tree lookup covers both.
  //   - brand: facet filter (FilterBar)
  //   - productType: facet filter (FilterBar)
  //   - parentId: hierarchy lookup (children of parent — not auto-
  //     indexed by Prisma despite the relation declaration)
  //   - isParent: cheap boolean filter for hierarchy lens
  //   - fulfillmentMethod: facet filter
  // At 280 rows none of these matter; at 10k+ they prevent seq-scans.
  @@index([status, deletedAt])
  @@index([brand])
  @@index([productType])
  @@index([parentId])
  @@index([isParent])
  @@index([fulfillmentMethod])
  @@index([familyId])
  @@index([workflowStageId])
  // W5.43 — bench-products-grid.mjs at 10k catalog showed default
  // /products page-1 list (sort updatedAt DESC) at p95 131ms. The
  // status_deletedAt composite above doesn't help when status isn't
  // filtered. This composite covers the operator's most-common query
  // shape: parentId IS NULL + deletedAt IS NULL + updatedAt DESC.
  @@index([parentId, deletedAt, updatedAt(sort: Desc)])
  // W5.43 — multi-sort brand ASC, basePrice DESC, sku ASC was at p95
  // 164ms with the existing single-column indexes (Postgres can't
  // merge them for ordering, only filtering). Composite supports the
  // exact column order operators chain via the U.x sort UI.
  @@index([brand, basePrice(sort: Desc), sku])
  @@unique([workspaceId, sku], name: "workspace_sku", map: "Product_workspace_sku_key")
  @@index([workspaceId])
}

// ── SkuAlias: maps arbitrary strings → Product ──────────────────────────────
// Enables "Gale Jacket Black" or "GAL-BLK" to resolve to the canonical SKU
// during bulk imports. Sources: MANUAL (operator), IMPORT (confirmed from an
// import session), AUTO (seeded from product.name at first import).
model SkuAlias {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id        String   @id @default(cuid())
  productId String
  product   Product  @relation(fields: [productId], references: [id], onDelete: Cascade)
  alias     String // normalized: lowercase + trimmed
  raw       String // original as the operator typed it
  source    String   @default("MANUAL") // MANUAL | IMPORT | AUTO
  createdAt DateTime @default(now())

  @@index([productId])
  @@unique([workspaceId, alias], name: "workspace_alias", map: "SkuAlias_workspace_alias_key")
  @@index([workspaceId])
}

// ── StockImportJob: audit log of every bulk import applied ──────────────────
// Each committed import writes one row here so operators can review history,
// download error reports, and understand cumulative stock movements.
model StockImportJob {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id              String    @id @default(cuid())
  filename        String?
  fileKind        String? // csv | xlsx | json
  locationCode    String
  mode            String // ADJUST | SET
  target          String // WAREHOUSE | CHANNEL | BOTH
  totalRows       Int       @default(0)
  succeeded       Int       @default(0)
  failed          Int       @default(0)
  skipped         Int       @default(0)
  status          String    @default("PENDING") // DRAFT | PENDING | APPLYING | APPLIED | PARTIAL | FAILED | CANCELLED
  appliedAt       DateTime?
  createdAt       DateTime  @default(now())
  errorSummary    String?
  results         Json? // per-row outcome snapshot for history drill-down
  // IM.3.2 — async apply live progress (updated per chunk while APPLYING)
  startedAt       DateTime?
  progressAt      DateTime?
  processedRows   Int       @default(0)
  // IM.3.3 — who applied the import (session email; null = pre-IM.3.3 or script)
  createdBy       String?
  // IM.3.4 — batch revert: id of the revert job that undid this import
  revertedByJobId String?

  @@index([status, createdAt(sort: Desc)])
  @@index([locationCode])
  @@index([workspaceId])
}

/// W2.1 — Product family (Akeneo cornerstone PIM template).
///
/// A Family is the template for a product type — e.g., "Motorcycle
/// Jacket" — that declares which attribute groups + attributes
/// apply, which are required vs optional, and (in W2.2) per-channel
/// syndication rules. Each Product *optionally* belongs to one
/// Family. Until a Product has a Family, the loose categoryAttributes
/// JSON path is used (legacy / catch-all).
///
/// Hierarchy: a Family can have a parent (e.g., "Motorcycle Apparel"
/// → "Motorcycle Jacket") with attribute inheritance — a child
/// family inherits all parent required + optional attributes plus
/// any it adds itself. SetNull on parent delete so the child
/// becomes a top-level family instead of disappearing.
///
/// Wave 2 follow-up (each its own commit per H.1):
///   W2.2: FamilyAttribute join + required/optional + per-channel
///   W2.3: AttributeSet / AttributeGroup / CustomAttribute
///   W2.4+: services, family-attach UI, completeness recompute
model ProductFamily {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String  @id @default(cuid())
  // Human-readable identifier. Lower-case-snake convention to match
  // Akeneo: 'motorcycle_jacket', 'motorcycle_helmet'.
  code        String
  // Display label for UI. Locale-resolved at read time once W2.2
  // adds FamilyTranslation; for now the operator-facing label only.
  label       String
  description String?

  // Hierarchy — children inherit attributes from parent.
  parentFamilyId String?
  parentFamily   ProductFamily?  @relation("FamilyHierarchy", fields: [parentFamilyId], references: [id], onDelete: SetNull)
  childFamilies  ProductFamily[] @relation("FamilyHierarchy")

  // Products that belong to this family (back-relation for the
  // Product.family FK declared above).
  products Product[] @relation("ProductFamily")

  // Attributes attached to this family (W2.3).
  familyAttributes FamilyAttribute[]

  // ── W3.1 — Optional default workflow ──────────────────────────
  // When a product joins this family (W2.13 bulk-attach), it lands
  // on the workflow's initial stage. SetNull on workflow delete so
  // detaching the workflow from a family is non-destructive —
  // products keep their current workflowStageId until manually
  // moved. Multiple families can share the same workflow.
  workflowId String?
  workflow   ProductWorkflow? @relation(fields: [workflowId], references: [id], onDelete: SetNull)

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([parentFamilyId])
  @@index([workflowId])
  @@unique([workspaceId, code], name: "workspace_code", map: "ProductFamily_workspace_code_key")
  @@index([workspaceId])
}

/// W2.2 — AttributeGroup (Akeneo + Magento parity).
///
/// A group is a logical bucket of related attributes that show up
/// together in the editor — e.g., "Sizing & Fit" (size, fit, length)
/// or "Safety" (CE, armor, EN-13595). Pure organisational layer; no
/// validation or inheritance happens at this level.
///
/// Wave 2 follow-up:
///   W2.3: FamilyAttribute (declares which group attributes are
///         required vs optional per family + per channel)
///   W2.x: per-attribute reference entities (color swatches, etc.)
model AttributeGroup {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String  @id @default(cuid())
  code        String // 'sizing', 'materials', 'safety'
  label       String
  description String?
  sortOrder   Int     @default(0)

  attributes CustomAttribute[]

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt
  @@unique([workspaceId, code], name: "workspace_code", map: "AttributeGroup_workspace_code_key")
  @@index([workspaceId])
}

/// W2.2 — CustomAttribute (Magento EAV + Akeneo type system).
///
/// Each attribute is a typed field that can be attached to a
/// ProductFamily via FamilyAttribute (W2.3). The `type` field
/// drives editor + validation:
///
///   text        : single-line string
///   textarea    : multi-line string
///   number      : decimal/integer (validation.{min,max,step,unit})
///   boolean     : yes/no toggle
///   select      : single-choice from AttributeOption[]
///   multiselect : multi-choice from AttributeOption[]
///   date        : ISO date
///   reference   : reference-entity FK (color swatch, material — W2.x)
///   asset       : DAM image/file (W4.x)
///
/// `validation` is a JSON blob so we don't need type-specific columns.
/// Resolved at write time per the type's expected shape.
///
/// `localizable` switches the storage path: when true, the value
/// lives in ProductTranslation (per-locale); when false, on the
/// Product row directly.
///
/// `scope` is 'global' (one value per Product) or 'per_variant' (one
/// value per child Product). Mirrors Akeneo's variant-axis model.
model CustomAttribute {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String  @id @default(cuid())
  code        String // 'ce_certification', 'armor_level'
  label       String
  description String?

  groupId String
  group   AttributeGroup @relation(fields: [groupId], references: [id], onDelete: Restrict)

  type         String // text | textarea | number | boolean | select | multiselect | date | reference | asset
  validation   Json? // { minLength?, maxLength?, min?, max?, step?, unit?, pattern? }
  defaultValue Json?
  localizable  Boolean @default(false)
  scope        String  @default("global") // 'global' | 'per_variant'
  sortOrder    Int     @default(0)

  options          AttributeOption[]
  familyAttributes FamilyAttribute[]

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([groupId])
  @@unique([workspaceId, code], name: "workspace_code", map: "CustomAttribute_workspace_code_key")
  @@index([workspaceId])
}

/// W2.2 — AttributeOption for select / multiselect attributes.
///
/// Stable `code` (e.g., 'red') for storage; `label` ('Red') for
/// display — separate so renaming the label doesn't break stored
/// values. `metadata` carries swatch data (color hex, texture URL)
/// until full reference-entity tables land in a later W2.x commit.
model AttributeOption {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String          @id @default(cuid())
  attributeId String
  attribute   CustomAttribute @relation(fields: [attributeId], references: [id], onDelete: Cascade)

  code     String // 'red', 'leather'
  label    String // 'Red', 'Leather'
  metadata Json? // { color: '#ff0000' } | { texturePath: '/...' }

  sortOrder Int @default(0)

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@unique([workspaceId, attributeId, code], name: "attributeId_code", map: "AttributeOption_attributeId_code_key")
  @@index([attributeId])
  @@index([workspaceId])
}

/// W2.3 — FamilyAttribute (Akeneo-flat join, user-confirmed shape).
///
/// Declares which CustomAttribute belongs to a ProductFamily, plus
/// required-vs-optional + per-channel scoping.
///
/// Semantics:
///   required = false              → optional on every channel
///                                   (`channels` is informational —
///                                   typically empty)
///   required = true,  channels=[] → required on every channel
///   required = true,  channels=['AMAZON','EBAY']
///                                 → required only on listed channels;
///                                   optional elsewhere. Channel codes
///                                   match ChannelListing.channel
///                                   (AMAZON | EBAY | SHOPIFY | ...).
///
/// Inheritance is Akeneo-strict additive (user-confirmed): a child
/// family inherits ALL parent FamilyAttribute rows; it can ADD more
/// but cannot remove or downgrade parent's. Resolution is computed
/// at read time by the FamilyHierarchy resolver service (W2.4).
///
/// Per-channel validation rules beyond required/optional (e.g., a
/// minLength that differs by marketplace) are deferred — the user
/// chose flat now, EAV later. If/when a real product flow needs
/// that, a follow-up commit adds FamilyAttributeChannelRule.
model FamilyAttribute {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String          @id @default(cuid())
  familyId    String
  family      ProductFamily   @relation(fields: [familyId], references: [id], onDelete: Cascade)
  attributeId String
  attribute   CustomAttribute @relation(fields: [attributeId], references: [id], onDelete: Cascade)

  required  Boolean  @default(false)
  // Channel codes where this attribute is required (when required=true).
  // Empty array = required on every channel. Codes match
  // ChannelListing.channel: 'AMAZON' | 'EBAY' | 'SHOPIFY' | ...
  channels  String[]
  sortOrder Int      @default(0)

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  // Each (family, attribute) pair is unique — can't declare the
  // same attribute twice on the same family. Differing per-channel
  // requirements live in the channels[] field, not as separate rows.
  @@unique([workspaceId, familyId, attributeId], name: "familyId_attributeId", map: "FamilyAttribute_familyId_attributeId_key")
  @@index([familyId])
  @@index([attributeId])
  @@index([workspaceId])
}

/// W3.1 — ProductWorkflow (Salesforce-parity content-quality
/// pipeline, simplified for single-operator MVP).
///
/// A Workflow is a configurable named pipeline of stages — e.g.
/// 'standard_pim': DRAFT_CONTENT → IN_REVIEW → APPROVED →
/// PUBLISHED. Each ProductFamily can OPTIONALLY reference one
/// workflow (Family.workflowId); products that join such a family
/// land on the workflow's initial stage and progress through
/// transitions (W3.x).
///
/// Distinct from Product.status (the ACTIVE/INACTIVE/DRAFT
/// operational lifecycle that cascades to marketplaces). status
/// is what the marketplace sees; workflowStage is the internal
/// content-quality gate before the operator flips status to ACTIVE.
///
/// Wave 3 follow-up (each its own commit per H.1):
///   W3.2: WorkflowService — moveStage / canTransition / SLA
///   W3.3: Workflow CRUD API
///   W3.4: Stage transition + comment API
///   W3.5+: Workflow lens + drawer tab on /products
model ProductWorkflow {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String  @id @default(cuid())
  // Lower-snake_case identifier ('standard_pim', 'b2b_approval').
  code        String
  label       String
  description String?

  stages   WorkflowStage[]
  families ProductFamily[]

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt
  @@unique([workspaceId, code], name: "workspace_code", map: "ProductWorkflow_workspace_code_key")
  @@index([workspaceId])
}

/// W3.1 — WorkflowStage. Per-workflow stage definition. Stages are
/// ordered by sortOrder; the stage with isInitial=true is where new
/// products land when joining the workflow. isTerminal=true marks
/// a successful-completion stage. isPublishable=true is a UI hint
/// for "this stage means the product is ready to go live"; the
/// workflow does NOT directly mutate Product.status — that stays
/// a manual operator action so cascade-to-marketplace stays
/// explicit.
model WorkflowStage {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id         String          @id @default(cuid())
  workflowId String
  workflow   ProductWorkflow @relation(fields: [workflowId], references: [id], onDelete: Cascade)

  // Stable code within this workflow ('draft', 'in_review',
  // 'approved', 'published'). Unique per (workflow, code).
  code        String
  label       String
  description String?
  sortOrder   Int     @default(0)

  // Optional SLA: hours from entry to expected next transition.
  // Surfaces as overdue badges in the workflow lens.
  slaHours      Int?
  // Operator hint: this stage represents "ready to publish".
  isPublishable Boolean @default(false)
  // Stage products land on when joining this workflow. Exactly one
  // per workflow — write-time service enforces this invariant.
  isInitial     Boolean @default(false)
  // Stage that represents successful completion. Zero or one per
  // workflow.
  isTerminal    Boolean @default(false)

  productsHere    Product[]            @relation("ProductCurrentStage")
  transitionsFrom WorkflowTransition[] @relation("TransitionFromStage")
  transitionsTo   WorkflowTransition[] @relation("TransitionToStage")
  comments        WorkflowComment[]
  assignments     WorkflowAssignment[] // W9.x: per-stage assignees

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@unique([workspaceId, workflowId, code], name: "workflowId_code", map: "WorkflowStage_workflowId_code_key")
  @@index([workflowId])
  @@index([workspaceId])
}

/// W3.1 — WorkflowTransition log. Append-only record of every
/// stage move per product. Drives the audit trail + the per-product
/// activity timeline. fromStage is nullable (initial entry into a
/// workflow has no `from`).
///
/// Cascade rules:
///   product → CASCADE (transitions are owned by the product)
///   fromStage → SET NULL (preserve history when a stage is renamed
///                          / removed; the transition record stays)
///   toStage → RESTRICT (refuse to delete a stage with transitions
///                        landing on it; the operator must rewire
///                        first)
model WorkflowTransition {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String         @id @default(cuid())
  productId   String
  product     Product        @relation("ProductWorkflowTransitions", fields: [productId], references: [id], onDelete: Cascade)
  fromStageId String?
  fromStage   WorkflowStage? @relation("TransitionFromStage", fields: [fromStageId], references: [id], onDelete: SetNull)
  toStageId   String
  toStage     WorkflowStage  @relation("TransitionToStage", fields: [toStageId], references: [id], onDelete: Restrict)

  userId  String?
  comment String?

  createdAt DateTime @default(now())

  @@index([productId, createdAt])
  @@index([toStageId])
  @@index([workspaceId])
}

/// W3.1 — WorkflowComment. Per-product-per-stage discussion thread.
/// Survives stage transitions (the comment stays attached to the
/// stage where it was made, even after the product moves on) so the
/// audit trail reads chronologically per stage.
model WorkflowComment {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id        String        @id @default(cuid())
  productId String
  product   Product       @relation("ProductWorkflowComments", fields: [productId], references: [id], onDelete: Cascade)
  stageId   String
  stage     WorkflowStage @relation(fields: [stageId], references: [id], onDelete: Cascade)

  userId String?
  body   String

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([productId, createdAt])
  @@index([stageId])
  @@index([workspaceId])
}

/// W9.x — WorkflowAssignment: per-product reviewer/approver tracking.
///
/// Operator (Awa) can delegate review of a product's content quality
/// to a named team member. Assignments are per-product (not per-stage)
/// so they survive stage transitions; stageId is optional context for
/// "assigned to review at this stage". Role distinguishes REVIEWER
/// (can comment), APPROVER (can advance stage), OWNER (primary DRI).
model WorkflowAssignment {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id           String         @id @default(cuid())
  productId    String
  product      Product        @relation(fields: [productId], references: [id], onDelete: Cascade)
  stageId      String?
  stage        WorkflowStage? @relation(fields: [stageId], references: [id], onDelete: SetNull)
  assigneeId   String
  assignee     UserProfile    @relation(fields: [assigneeId], references: [id], onDelete: Cascade)
  /// 'REVIEWER' | 'APPROVER' | 'OWNER'
  role         String         @default("REVIEWER")
  /// ID of user who created the assignment
  assignedById String?
  dueAt        DateTime?
  note         String?
  createdAt    DateTime       @default(now())
  updatedAt    DateTime       @updatedAt

  @@unique([workspaceId, productId, assigneeId, role], name: "productId_assigneeId_role", map: "WorkflowAssignment_productId_assigneeId_role_key")
  @@index([productId])
  @@index([stageId])
  @@index([assigneeId])
  @@index([workspaceId])
}

/// W4.1 — CustomerGroup (Magento + Salesforce B2B parity).
///
/// Top-level customer segmentation entity. Each group is a named
/// bucket of buyers — 'guest', 'retail_b2b', 'wholesale_b2b' — that
/// can have segment-specific tier pricing. ProductTierPrice rows
/// reference a group optionally; null group = applies to every
/// customer regardless of segment.
///
/// CustomerGroup is intentionally minimal at this stage — code +
/// label + description. Discount rules, payment terms, credit
/// limits all live downstream (Wave 4 follow-ups or Wave 8 B2B
/// catalog). This model is the join key; everything else builds on
/// top.
model CustomerGroup {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String  @id @default(cuid())
  // Lower-snake_case: 'guest', 'retail_b2b', 'wholesale_b2b'.
  code        String
  label       String
  description String?

  tierPrices ProductTierPrice[]

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt
  @@unique([workspaceId, code], name: "workspace_code", map: "CustomerGroup_workspace_code_key")
  @@index([workspaceId])
}

/// W4.1 — ProductTierPrice (Magento parity).
///
/// Per-product volume-discount + customer-group pricing. The
/// resolver (W4.2) picks the row with the highest `minQty` ≤
/// requested quantity that matches the customer's group (or has
/// customerGroupId=null for everyone). When no matching tier
/// applies, falls back to Product.basePrice.
///
/// Cascade rules:
///   product → CASCADE (tier prices owned by the product)
///   customerGroup → CASCADE (deleting a group drops its
///                            specific tier rows; "applies to
///                            everyone" rows survive because
///                            customerGroupId stays null)
///
/// Naming: prefixed `Product` to disambiguate from any future
/// channel-level or category-level tier pricing models. The
/// product-scope is explicit so call sites read clearly.
model ProductTierPrice {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id        String  @id @default(cuid())
  productId String
  product   Product @relation(fields: [productId], references: [id], onDelete: Cascade)

  // Quantity threshold. Discount applies when buying this many or
  // more. minQty=1 represents "the base tier" but is not required
  // (a product can have only minQty=10+ tiers and fall back to
  // basePrice for qty < 10).
  minQty Int

  // Discount price for the tier. Stored as absolute amount; the UI
  // can offer "fixed" vs "percent off" entry but at storage level
  // we resolve to the absolute value so the runtime resolver is
  // pure arithmetic.
  price Decimal @db.Decimal(10, 2)

  // Optional customer group. Null = applies to every customer; set
  // = applies only to that segment. The resolver picks
  // group-specific tiers over generic ones at the same minQty.
  customerGroupId String?
  customerGroup   CustomerGroup? @relation(fields: [customerGroupId], references: [id], onDelete: Cascade)

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  // No two tier rows for the same (product, minQty, group) — the
  // resolver assumes a deterministic answer per tuple.
  @@unique([workspaceId, productId, minQty, customerGroupId], name: "productId_minQty_customerGroupId", map: "ProductTierPrice_productId_minQty_customerGroupId_key")
  @@index([productId])
  @@index([customerGroupId])
  @@index([workspaceId])
}

/// W4.4 — DigitalAsset (Plytix-parity DAM library).
///
/// Top-level uploaded file (image / video / document / 3d-model).
/// Distinct from ProductImage (the legacy product-bound image store)
/// in two key ways:
///
///   1. Reusable. One DigitalAsset can be used by N products via
///      AssetUsage join rows — no duplicate uploads when the same
///      hero photo applies to a parent + every variant.
///   2. Metadata-rich. Photographer credit, color tags, alt text,
///      captions live in metadata JSON; per-asset versioning + asset
///      groups (e.g., 'spring-2026 catalog') come in follow-up
///      commits.
///
/// Storage is provider-pluggable (`storageProvider` enum stored as
/// string: 'cloudinary' / 's3' / 'r2' / 'local'). The resolver
/// returns `url` for clients; `storageId` is the provider-specific
/// reference for delete + variant generation.
///
/// Migration plan: ProductImage rows can be backfilled into
/// DigitalAsset + AssetUsage by a one-shot script (Wave 4 follow-up
/// commit). Until then, both paths coexist.
model DigitalAsset {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id              String  @id @default(cuid())
  // Operator-facing slug ('xavia-jacket-hero-front'). Optional —
  // useful when the operator wants to refer to the asset by name,
  // but not required (most uploads have no operator-set code).
  code            String?
  // Operator-facing label (filename or curator-set name).
  label           String
  // 'image' | 'video' | 'document' | 'model3d'. Stored as string
  // (not enum) so future asset types don't need a migration.
  type            String  @default("image")
  mimeType        String // 'image/jpeg', 'video/mp4', etc.
  sizeBytes       Int
  // Provider-specific. 'cloudinary' is canonical for the Xavia
  // catalog; 's3'/'r2' planned for video + document storage.
  storageProvider String  @default("cloudinary")
  // Provider-specific identifier (Cloudinary public_id, S3 key).
  storageId       String
  // Public URL — what the client renders. Source of truth is
  // storageProvider + storageId; url is denormalised for quick reads.
  url             String

  // Original filename at upload time (for download / "is this still
  // the right photo?" diffing).
  originalFilename String?

  // MC.3.3 — SHA-256 of the uploaded bytes (lowercase hex). Lets us
  // skip the Cloudinary roundtrip when the operator re-uploads a
  // file already in the catalogue. Indexed unique so a duplicate
  // hash collides at the DB layer instead of racing two requests
  // into separate Cloudinary calls.
  contentHash String?

  // Free-form metadata: alt text, photographer credit, color tags,
  // dominant colors, captions, etc. JSON keeps the schema flexible
  // until we identify access patterns that warrant a dedicated
  // column.
  metadata Json?

  // Back-relation to usages.
  usages AssetUsage[]
  // MC.2.1 — back-relation for AssetTag join (reuses the existing
  // Tag model rather than introducing an asset-only taxonomy).
  tags   AssetTag[]

  // MC.2.2 — optional AssetFolder. NULL means "unfiled" (the
  // default — operators can drag assets into a folder later).
  folderId String?
  folder   AssetFolder? @relation(fields: [folderId], references: [id], onDelete: SetNull)

  // MC.6.3 — per-locale text/badge overlays applied at variant build
  // time via Cloudinary `l_text:` overlays. Empty for assets that
  // don't need localized badges.
  localeOverlays AssetLocaleOverlay[]

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([type])
  @@index([folderId])
  @@unique([workspaceId, code], name: "workspace_code", map: "DigitalAsset_workspace_code_key")
  @@unique([workspaceId, contentHash], name: "workspace_contentHash", map: "DigitalAsset_workspace_contentHash_key")
  @@index([workspaceId])
}

/// MC.2.2 — AssetFolder (DAM hierarchy).
///
/// Self-referential parentId for unbounded depth. A NULL parentId
/// is a root folder. SetNull on parent delete promotes orphaned
/// children to roots — the alternative (cascade) would silently
/// drop assets with the parent and that's an awful UX. Operators
/// who genuinely want to delete a tree should clear children
/// explicitly first.
///
/// `order` is per-parent display order (siblings sorted ascending).
/// Drag-reorder writes a fresh sequence on commit, same pattern as
/// ProductImage.sortOrder (W8.1).
model AssetFolder {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id        String         @id @default(cuid())
  name      String
  parentId  String?
  parent    AssetFolder?   @relation("AssetFolderTree", fields: [parentId], references: [id], onDelete: SetNull)
  children  AssetFolder[]  @relation("AssetFolderTree")
  assets    DigitalAsset[]
  order     Int            @default(0)
  createdAt DateTime       @default(now())
  updatedAt DateTime       @updatedAt

  @@index([parentId, order])
  @@index([workspaceId])
}

/// W4.4 — AssetUsage (DAM join layer).
///
/// "This asset is used by Product X as the MAIN image" — one row
/// per (asset, scope-entity, role). Scopes are intentionally loose
/// strings instead of an enum so the model can accept future
/// scopes (channel-listing-specific assets, translation-specific
/// assets, marketing-collateral-only assets) without migrations.
///
/// Cascade rules:
///   asset → CASCADE (usages reference an asset; deleting the asset
///                    drops them)
///   product → CASCADE (when scope='product', product delete drops
///                      its usages too — explicit FK so the
///                      cascade is type-safe)
///
/// `role` is operator-meaningful — 'main' / 'alt' / 'lifestyle' /
/// 'hero' / 'detail' / 'packaging'. Stored as string so the per-
/// channel listing flow can introduce its own role names without
/// touching the schema.
///
/// `sortOrder` controls display order within a (scope, scopeId,
/// role) group.
model AssetUsage {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id      String       @id @default(cuid())
  assetId String
  asset   DigitalAsset @relation(fields: [assetId], references: [id], onDelete: Cascade)

  // Scope = which entity uses the asset. 'product' is the only
  // scope today; productId is the FK target. Future scopes
  // ('channel_listing', 'translation', 'marketing_campaign') will
  // gain their own optional FK columns.
  scope     String // 'product' for now
  productId String?
  product   Product? @relation(fields: [productId], references: [id], onDelete: Cascade)

  role      String // 'main' | 'alt' | 'lifestyle' | 'hero' | 'detail' | 'packaging'
  sortOrder Int    @default(0)

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@unique([workspaceId, assetId, scope, productId, role, sortOrder], name: "assetId_scope_productId_role_sortOrder", map: "AssetUsage_assetId_scope_productId_role_sortOrder_key")
  @@index([assetId])
  @@index([scope, productId])
  @@index([productId])
  @@index([workspaceId])
}

/// W4.6 — RepricingRule (Rithum cornerstone).
///
/// Per-(product, channel, marketplace) repricing config. The
/// repricing engine (W4.7+) reads these rows on each tick + decides
/// what price to push. Decisions are logged to RepricingDecision
/// for the audit trail — operator can answer "why did my price
/// drop yesterday at 14:00?" by reading the decision history.
///
/// Strategies (stored as string, not enum, for forward compat):
///   match_buy_box           — track the marketplace buy-box winner
///   beat_lowest_by_pct      — undercut the lowest competitor by %
///   beat_lowest_by_amount   — undercut by absolute amount
///   fixed_to_buy_box_minus  — buy-box winner minus fixed amount
///   manual                  — disabled; operator sets the price
///                              themselves (rule survives so the
///                              min/max floor/ceiling still applies
///                              if the engine is re-enabled)
///
/// Floor/ceiling are HARD constraints — every strategy clamps its
/// computed price to [minPrice, maxPrice]. A clamp is logged as
/// `capped: 'floor' | 'ceiling'` on the decision so the operator
/// can see "we wanted to undercut at $79.99 but the floor held
/// us at $85.00".
///
/// Marketplace is optional — null means "this rule applies to
/// every marketplace under the channel" (e.g., one Amazon rule
/// for IT/DE/FR/ES/UK). When operator wants per-marketplace
/// divergence (Amazon IT pricing different from Amazon DE), they
/// create separate rows.
///
/// Schedule: activeFromHour/activeToHour are inclusive UTC hours.
/// activeDays is 0-6 (Sunday=0). When all three are null/empty the
/// rule is always-on. Operator-set "only reprice during business
/// hours" is the canonical use case.
model RepricingRule {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id        String  @id @default(cuid())
  productId String
  product   Product @relation(fields: [productId], references: [id], onDelete: Cascade)

  channel     String // 'AMAZON' | 'EBAY' | 'SHOPIFY'
  marketplace String? // 'IT' | 'DE' | etc. (null = all marketplaces under the channel)

