model ProductImage {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id        String  @id @default(cuid())
  product   Product @relation(fields: [productId], references: [id])
  productId String
  url       String
  alt       String?
  /// 'MAIN' | 'ALT' | 'LIFESTYLE' | 'SWATCH' | 'DIAGRAM'
  type      String // 'MAIN', 'ALT', 'LIFESTYLE'
  /// W8.1 — display sort order; lower = earlier. MAIN is always 0.
  /// Populated on creation; the PATCH /api/products/:id/images/reorder
  /// endpoint writes a fresh contiguous sequence on drag-drop commit.
  sortOrder Int     @default(0)
  /// W8.1 — Cloudinary public_id so the delete endpoint can clean up
  /// the asset from Cloudinary as well as the DB row. NULL for images
  /// imported from external URLs (Amazon sync, URL paste).
  publicId  String?

  /// IR.2 — Asset metadata captured at upload (from Cloudinary) or
  /// backfilled. Mirrors the same columns on ListingImage so QualityChecklist
  /// + per-channel dim warnings can rely on them uniformly. NULL for legacy
  /// rows until scripts/backfill-product-image-metadata.mjs runs.
  width    Int?
  height   Int?
  mimeType String?
  fileSize Int?

  /// IE.1 — Upload-dedup gate. contentHash is SHA-256 hex of the raw
  /// file buffer, computed BEFORE the Cloudinary call so an exact
  /// re-upload returns the existing row with zero Cloudinary cost.
  /// perceptualHash is Cloudinary's 64-bit pHash (16 hex chars) used
  /// for near-duplicate detection: two images with Hamming distance
  /// ≤ 6 are treated as the same shot at different quality/crop.
  /// Both NULL on legacy rows until the IE.2 backfill runs.
  /// Non-unique index — collapse-to-canonical happens in IE.2 after
  /// human review.
  contentHash    String?
  perceptualHash String?
  /// IE.13 — 256-bit difference hash (17×16 grayscale, horizontal
  /// gradient sign), 64 hex chars. Second opinion for the near-dup
  /// gate: the 8×8 aHash collapses same-silhouette catalog shots (and
  /// same-template artwork like per-market size charts) to identical
  /// hashes, so a 409 requires BOTH aHash ≤ 6 AND dhash256 ≤ 26.
  /// NULL until upload (new rows) or the dhash256 backfill (legacy).
  dhash256       String?

  /// IR.4 — Self-FK for the in-app image editor. When the operator crops /
  /// rotates / flips an existing master image, the result is saved as a NEW
  /// ProductImage row (URL = Cloudinary transformation of the source) and
  /// derivedFromImageId points at the source. Lets the lightbox drawer show
  /// "Derived from MAIN (v1)" + "N derivatives" without scanning every row.
  derivedFromImageId String?
  derivedFrom        ProductImage?  @relation("ProductImageDerivation", fields: [derivedFromImageId], references: [id], onDelete: SetNull)
  derivatives        ProductImage[] @relation("ProductImageDerivation")

  /// IR.6 — Gemini Vision analysis results. Populated by
  /// POST /api/products/:id/images/:imageId/analyze. NULL until run.
  ///
  /// aiHasWhiteBackground: binary "is the background a clean white"?
  ///   Drives Amazon MAIN-image validation (Amazon requires white-bg).
  /// aiFrameFillPct: 0-100, how much of the frame the subject occupies.
  ///   Amazon wants ≥ 85 %.
  /// aiHasTextOverlay: binary, is there text printed on top of the
  ///   product? Disqualifies for marketplace MAIN images.
  /// aiOffCenterScore: 0-1, distance of subject centroid from frame
  ///   center as fraction of half-diagonal. 0 = perfectly centered.
  /// aiNotes: model's raw JSON for debugging + future model upgrades.
  aiAnalyzedAt         DateTime?
  aiHasWhiteBackground Boolean?
  aiFrameFillPct       Int?
  aiHasTextOverlay     Boolean?
  aiOffCenterScore     Float?
  aiNotes              Json?

  /// PG.4 — Operator-curated "hero image" flag. When true, this row
  /// wins the /products catalog thumbnail picker over MAIN type +
  /// sortOrder. Exactly zero or one row per product should be true at
  /// any time; the PATCH /api/products/:id/images/:imageId/primary
  /// endpoint enforces single-selection inside a transaction. The
  /// partial unique index below makes the contract a DB-level
  /// invariant — concurrent operator sessions can't both win.
  isPrimary Boolean @default(false)

  /// MM.1 — Media type discriminator. The product media hub holds images
  /// AND videos (+ future 3D/docs). Existing rows default to IMAGE so the
  /// whole image pipeline (matrix, mirror, bulk, cascade) is unaffected.
  /// 'IMAGE' | 'VIDEO' | 'MODEL3D' | 'DOC'
  mediaType     String  @default("IMAGE")
  /// MM.1 — Video poster / 3D thumbnail (Cloudinary so_0 frame for video).
  posterUrl     String?
  /// MM.1 — Video length in seconds (Cloudinary durationSeconds).
  durationSec   Float?
  /// MM.1 — Bidirectional link to the DAM DigitalAsset this media came from.
  sourceAssetId String?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  /// IE.2 — Enforces the IE.1 dedup contract at the DB level once
  /// the backfill + collapse pass has removed pre-existing duplicates.
  /// Postgres treats NULL contentHash values as distinct, so legacy
  /// rows that never got backfilled don't trip the constraint.
  @@unique([workspaceId, productId, contentHash], name: "productId_contentHash", map: "ProductImage_productId_contentHash_key")
  @@index([productId, sortOrder])
  @@index([derivedFromImageId])
  @@index([productId, perceptualHash])
  /// PG.4 — Partial unique index implemented as raw SQL in the
  /// 20260523_pg4_product_image_is_primary migration (Prisma's
  /// @@unique doesn't take a WHERE clause). Indexed via @@index for
  /// the FE's "find current primary" lookup. The DB-level partial
  /// unique is what actually enforces at-most-one per product.
  @@index([productId, isPrimary])
  @@index([productId, mediaType, sortOrder])
  @@index([workspaceId])
}

