model Campaign {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String         @id @default(cuid())
  name        String
  type        CampaignType
  status      CampaignStatus @default(ENABLED)
  dailyBudget Decimal        @db.Decimal(10, 2)
  startDate   DateTime
  endDate     DateTime?
  // Aggregated metrics (updated by sync)
  impressions Int            @default(0)
  clicks      Int            @default(0)
  spend       Decimal        @default(0) @db.Decimal(10, 2)
  sales       Decimal        @default(0) @db.Decimal(10, 2)
  createdAt   DateTime       @default(now())
  updatedAt   DateTime       @updatedAt

  // AD.1 — Trading Desk fields. marketplace + externalCampaignId are
  // additive: null = legacy Phase-1 stub row; non-null = synced from
  // Amazon Ads API (or sandbox fixture). Existing rows keep working.
  marketplace              String? // 'IT' | 'DE' | 'FR' | 'ES' | 'UK'
  externalCampaignId       String? // Amazon-issued ID (campaignId in Ads API)
  portfolioId              String? // Amazon Ads Portfolio grouping
  // AD.2 — currency for dailyBudget. Defaults EUR; non-EUR marketplaces
  // (e.g. UK GBP) override at sync time from the Ads API profile.
  dailyBudgetCurrency      String          @default("EUR")
  biddingStrategy          BiddingStrategy @default(LEGACY_FOR_SALES)
  // True Profit aggregates (computed by true-profit-rollup.service).
  // acos = spend / sales (Amazon's metric). roas = sales / spend.
  // trueProfit nets COGS + referral + FBA + storage + refunds.
  /// ACR.0.5 — nullable, and today ALWAYS null: measured 2026-08-05, no code path writes
  /// these two columns, so all 216 campaigns carried a hardcoded 0 that the console
  /// rendered as "True profit €0.00" — a claim, not a default. See ProductProfitDaily.
  acos                     Decimal?        @db.Decimal(8, 4)
  roas                     Decimal?        @db.Decimal(8, 4)
  trueProfitCents          Int?            @db.Integer
  trueProfitMarginPct      Decimal?        @db.Decimal(8, 4)
  // NP — set while the campaign is bid-suppressed (no-pause: bids at the floor
  // instead of status=PAUSED). Fast "is suppressed" flag + when it started.
  bidsSuppressedAt         DateTime?
  // MB.1 — WHICH floor the campaign is currently suppressed at. Before this, the floor
  // was one module constant (2¢) so "already suppressed" implied "suppressed at the right
  // value" and re-flooring was a no-op. With a per-target floor, two Min-bid windows can
  // want different floors back-to-back, and this is how the engine notices. null on rows
  // suppressed before MB.1 → read as the legacy 2¢.
  bidsSuppressedFloorCents Int?
  // ADX A3 — WHICH engine suppressed this campaign, as the actor string that did it.
  // Several engines share `bidsSuppressedAt` (rank Min-bid windows, dayparting, the retail
  // guard, budget stop-over-spend) and none could tell its own suppressions from another's.
  // Budget enforcement restores any suppressed campaign once spend is back under cap, so
  // without this it lifts the rank engine's Min-bid dayparting suppressions — 33 campaigns
  // were in exactly that state when this was found. null means "suppressed before this
  // column existed, owner unknown", which every engine must read as NOT MINE.
  bidsSuppressedBy         String?
  /// AX2.2 — WRITE truth: when we last pushed to Amazon and how it went.
  /// Stamped by ads-sync.worker. Never stamped by a read, so a successful
  /// settings read can't mask a failed bid write.
  lastSyncedAt             DateTime?
  lastSyncStatus           AdSyncStatus?
  lastSyncError            String?
  /// AX2.2 — READ freshness: when the 20-minute settings sync last actually
  /// observed this campaign on Amazon. Distinct from lastSyncedAt, which the
  /// console previously displayed as "last synced" while it really meant
  /// "last written" (observed spread: ES 5m, DE/FR ~2h, one IT campaign 34d).
  settingsSyncedAt         DateTime?

  // ── Phase 2: v1 unified API additions ─────────────────────────────────
  // adProduct is the v1 discriminator. The legacy `type` enum stays for
  // back-compat reads; sync code populates BOTH columns until M3 cutover.
  // Values: 'SPONSORED_PRODUCTS' | 'SPONSORED_BRANDS' | 'SPONSORED_DISPLAY' | 'SPONSORED_TELEVISION'
  adProduct          String?
  /// AX-IE.0 (E4) — Amazon's REAL campaign targeting type ('AUTO' | 'MANUAL'),
  /// read from v3 POST /sp/campaigns/list by ads-campaign-settings-sync.
  /// Null = Amazon hasn't reported it yet; the bulksheet exporter emits a blank
  /// cell rather than guessing. This replaced a regex over the campaign NAME
  /// (/\bauto|close match|.../) which mislabelled 26 of 196 campaigns — e.g. a
  /// manual campaign called "Autumn Boots" exported as auto, and a bulksheet that
  /// states the wrong targeting type corrupts on re-upload.
  /// NOTE: AdGroup.targetingType is NOT a substitute — it is only ever written by
  /// our own campaign builders, so every synced ad group sits at its default.
  targetingType      String?
  // v1 budget shape: { amount, type: 'DAILY'|'LIFETIME', recurrenceTimePeriod? }
  budgetJson         Json?
  // Full v1 bidding strategy (per-adProduct varies). For SP: { strategy, adjustments[] }.
  bidStrategyJson    Json?
  // SP placement bid adjustments + adjustmentByPlacement table.
  dynamicBidding     Json?
  // SD-only: tactic discriminator (T00020 = product targeting, T00030 = audience).
  tactic             String?
  // SD-only: pacing profile (e.g. 'as_soon_as_possible').
  deliveryProfile    String?
  // SD-only: cost model (cpc | vcpm).
  costType           String?
  // SB-only: creative assets — headline, brand logo, landing URL, video etc.
  creativeAssetJson  Json?
  // SB-only: brand registry binding (links to a Brand Profile).
  brandEntityId      String?
  // v1 MULTI_MARKETPLACE support: a single campaign serving multiple
  // marketplaces with a shared budget. SINGLE_MARKETPLACE matches today's
  // behavior; MULTI_MARKETPLACE populates linkedMarketplaces.
  budgetScope        String   @default("SINGLE_MARKETPLACE")
  linkedMarketplaces String[] @default([])

  // ── H.2: v1 unified Ads API delivery signals ───────────────────────
  // v1 exports include deliveryStatus + deliveryReasons[] that explain
  // why a campaign isn't currently serving (paused, out of budget,
  // suspended, etc). Operationally critical — answers "why isn't this
  // running" without a separate getCampaignDeliveryDetails call.
  deliveryStatus  String? // DELIVERING | NOT_DELIVERING
  deliveryReasons String[] @default([])

  // ── Apex A.2a: per-campaign live-write allowlist + safety counters ──
  // liveBidWritesEnabled is a DEFAULT-DENY containment key: even when the
  // deploy-wide NEXUS_AMAZON_ADS_MODE=live flag and the per-connection
  // writesEnabledAt are both set, the write-gate still refuses any live
  // bid/state mutation to this campaign's entities unless this is true.
  // Lets a cautious cutover canary exactly one campaign. Bid-change-% and
  // writes-per-day caps live in dynamicBidding JSON (alongside cpcCeiling).
  liveBidWritesEnabled Boolean @default(false)
  // Rolling daily counter for the maxWritesPerDay guardrail. liveBidWritesDay
  // is the UTC 'YYYY-MM-DD' the counter belongs to; a date mismatch means the
  // count is stale and treated as 0.
  liveBidWritesToday   Int     @default(0)
  liveBidWritesDay     String?

  // ADX A1 — automation bounds ON THE ENTITY, not in a rule.
  //
  // A rule saying "never bid above €2" can be edited, bypassed, or simply fail to
  // apply to entities created later. These columns apply to EVERY engine, every
  // rule and every future feature automatically, because ads-write-gate.ts consults
  // them on the way to Amazon and there is no other way out. Safety by construction
  // rather than by rule correctness.
  //
  // Reached independently by Scale Insights (caps + whitelists around 200+
  // parameters), M19 (ACoS target + budget cap + force-visibility around opaque ML),
  // Teikametrics (ACOS Limit + Bid Modifier around a proprietary model) and the
  // COMMERCE-PLATFORM-RESEARCH study (Rithum's per-SKU Min/Max Price, Quartile's
  // per-portfolio TargetACOS/Min Bid/Max Bid). Neither pole of the market ships an
  // unbounded optimiser.
  //
  // NULL = unbounded, which is today's behaviour for every existing row.
  minBidCents   Int?
  maxBidCents   Int?
  targetAcosPct Int?

  // BUD.2 — the same idea, applied to the DAILY BUDGET, which is where the ratchet lived.
  //
  // `budgetBaselineCents` is the anchor every RELATIVE budget rule computes from: −20% of a
  // €100 baseline is €80 today, tomorrow and on the 39th tick — the compounding that walked
  // GALE EXACT DE €100 → €1 in one day is arithmetic on the CURRENT value, and a baseline
  // makes the same rule idempotent without touching the rule. NULL = no anchor captured; the
  // handlers fall back to current-value behaviour, so every existing row is unchanged until
  // an operator captures a baseline.
  //
  // `minBudgetCents`/`maxBudgetCents` are gate-enforced bounds beside the bid bounds, on the
  // same read: a cut below the floor or a raise above the ceiling is DENIED (never clamped),
  // by every engine and rule automatically, because the gate is the only way to Amazon.
  // Amazon's own hard floor is €1; a floor here must be ≥ that. NULL = unbounded.
  budgetBaselineCents Int?
  minBudgetCents      Int?
  maxBudgetCents      Int?

  // ACR.1.2b — PER-DIMENSION AUTHORITY PINS ("hands off placement / bids / budget").
  //
  // The bounds above say how FAR automation may move a number. These say whether it may
  // touch that number at all, per dimension, per campaign. Quartile's pattern: an operator
  // who can hand back one dimension is far more willing to let automation keep the rest,
  // and today the only available answer is the allowlist — all of it or none of it.
  //
  // Enforced in ads-write-gate.ts beside minBidCents/maxBidCents, on the same read, for
  // the same reason those live on the entity: a pin that is only honoured by the engines
  // that remember to look is decorative, and decorative controls are the defect class this
  // whole programme exists to remove. A column cannot be forgotten by an engine written
  // next year.
  //
  // FALSE = automation may write this dimension, which is every existing row's behaviour.
  //
  // NOTE the deliberate asymmetry, following ADX G1 and ACR.0.7 exactly: a bid SUPPRESSION
  // (retail guard, budget stop-over-spend, Min-bid windows — the no-pause rule's way of
  // stopping delivery) is exempt from pinBids. A pin that blocked suppression would mean
  // "I will manage bids myself" silently also meant "stop protecting me from overspend",
  // and would freeze bids HIGH at the moment we most want them low. pinBudget has no such
  // exemption: budget pacing writes dailyBudget, which is not a safety action.
  pinPlacement Boolean   @default(false)
  pinBids      Boolean   @default(false)
  pinBudget    Boolean   @default(false)
  /// Accountability for the pin itself — who pinned it, when, and why. A pin an operator
  /// finds later with no author is indistinguishable from a bug.
  pinnedAt     DateTime?
  pinnedBy     String?
  pinNote      String?

  adGroups        AdGroup[]
  bidHistory      CampaignBidHistory[]
  /// D1 (2026-08-20) — the rules assigned to this campaign. See `CampaignRuleAssignment`.
  ruleAssignments CampaignRuleAssignment[]

  @@unique([workspaceId, externalCampaignId, marketplace], name: "externalCampaignId_marketplace", map: "Campaign_externalCampaignId_marketplace_key")
  @@index([marketplace, status])
  @@index([lastSyncStatus])
  @@index([settingsSyncedAt])
  @@index([adProduct, marketplace, status])
  @@index([workspaceId])
}

// AD.1 — Sponsored Products/Brands/Display ad group. Owns the default
// bid + targeting mode; child targets carry per-keyword overrides.
model AdGroup {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                     String         @id @default(cuid())
  campaignId             String
  campaign               Campaign       @relation(fields: [campaignId], references: [id], onDelete: Cascade)
  externalAdGroupId      String?
  name                   String
  defaultBidCents        Int            @default(50)
  suppressedFromBidCents Int? // NP — default bid before no-pause suppression; restored on resume
  baseBidFromCents       Int? // BL — default bid before a base-bid deltaPct mod; the STABLE baseline (no compounding); reverted when the directive clears
  status                 CampaignStatus @default(ENABLED)
  targetingType          String         @default("MANUAL") // AUTO | MANUAL
  impressions            Int            @default(0)
  clicks                 Int            @default(0)
  spendCents             Int            @default(0)
  salesCents             Int            @default(0)
  lastSyncedAt           DateTime?
  lastSyncStatus         AdSyncStatus?
  lastSyncError          String?
  createdAt              DateTime       @default(now())
  updatedAt              DateTime       @updatedAt

  // ── Phase 2: v1 unified API additions ─────────────────────────────────
  bidStrategyJson Json?
  // SD-only: creativeType (e.g. 'IMAGE' | 'VIDEO' | 'CAROUSEL').
  creativeType    String?

  // ── H.2: v1 unified Ads API delivery signals ───────────────────────
  deliveryStatus  String?
  deliveryReasons String[] @default([])

  /// AX2.0 — Amazon answered a write with entityNotFoundError: this entity no
  /// longer exists there. Set once, cleared on the next successful sync, and
  /// checked before enqueueing so a dead entity is never re-pushed daily.
  orphanedAt   DateTime?
  orphanReason String?

  targets    AdTarget[]
  productAds AdProductAd[]

  @@unique([workspaceId, externalAdGroupId, campaignId], name: "externalAdGroupId_campaignId", map: "AdGroup_externalAdGroupId_campaignId_key")
  @@index([campaignId, status])
  @@index([orphanedAt])
  @@index([workspaceId])
}

// AD.1 — Unified target row (keyword | product | category | audience).
// Amazon reports performance at this grain.
model AdTarget {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                     String         @id @default(cuid())
  adGroupId              String
  adGroup                AdGroup        @relation(fields: [adGroupId], references: [id], onDelete: Cascade)
  externalTargetId       String?
  kind                   String // KEYWORD | PRODUCT | CATEGORY | AUDIENCE
  expressionType         String // EXACT | PHRASE | BROAD | ASIN | CATEGORY_REFINEMENT
  expressionValue        String
  bidCents               Int            @default(50)
  // NP — the bid this target held BEFORE no-pause suppression dropped it to the
  // floor (~2¢). null = not suppressed. Restored verbatim when the campaign resumes.
  suppressedFromBidCents Int?
  baseBidFromCents       Int? // BL — the bid before a base-bid deltaPct mod; STABLE baseline so re-applying the delta never compounds; reverted when the directive clears
  status                 CampaignStatus @default(ENABLED)
  impressions            Int            @default(0)
  clicks                 Int            @default(0)
  spendCents             Int            @default(0)
  salesCents             Int            @default(0)
  ordersCount            Int            @default(0)
  lastSyncedAt           DateTime?
  lastSyncStatus         AdSyncStatus?
  lastSyncError          String?
  createdAt              DateTime       @default(now())
  updatedAt              DateTime       @updatedAt

  // ── Phase 2: v1 unified API additions ─────────────────────────────────
  // Distinguishes positive (default) from negative targets/keywords. v1
  // returns both via a single endpoint with a state-level flag.
  isNegative    Boolean @default(false)
  // Scope at which the negative applies: CAMPAIGN | AD_GROUP. Null for
  // positive targets.
  negativeLevel String?

  // ── H.2: v1 unified Ads API delivery signals ───────────────────────
  deliveryStatus  String?
  deliveryReasons String[] @default([])

  /// AX2.0 — Amazon answered a write with entityNotFoundError: this keyword /
  /// target no longer exists there. Set once, cleared on the next successful
  /// sync, and checked before enqueueing. Without it the rank engine
  /// regenerated the same dead write every day (662 dead rows from 23 targets).
  orphanedAt   DateTime?
  orphanReason String?

  /// NEG.3 — when WE retired this negative, and why.
  ///
  /// Never written by the sync. `updatedAt` is the last INGEST tick — measured 2026-08-12, all 62
  /// already-archived negatives share one `updatedAt` day because the v1 export re-stamps every
  /// matched row — so it can never answer "when was this retired". These two columns can, from the
  /// moment they exist forward; they stay null for every pre-existing row rather than inventing a
  /// date for the 62 that were archived on Amazon and mirrored in.
  retiredAt    DateTime?
  retireReason String?

  @@index([adGroupId, status])
  @@index([externalTargetId])
  @@index([adGroupId, isNegative])
  @@index([orphanedAt])
  @@index([workspaceId])
}

// AD.1 — Links ad-groups to local Product rows (via ASIN/SKU). The
// join the "bid down on this helmet" automation rule uses to resolve
// Product → its advertised ad-groups.
model AdProductAd {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id           String         @id @default(cuid())
  adGroupId    String
  adGroup      AdGroup        @relation(fields: [adGroupId], references: [id], onDelete: Cascade)
  productId    String?
  product      Product?       @relation(fields: [productId], references: [id], onDelete: SetNull)
  asin         String?
  sku          String?
  externalAdId String?
  status       CampaignStatus @default(ENABLED)
  impressions  Int            @default(0)
  clicks       Int            @default(0)
  spendCents   Int            @default(0)
  salesCents   Int            @default(0)
  lastSyncedAt DateTime?
  createdAt    DateTime       @default(now())
  updatedAt    DateTime       @updatedAt

  // ── H.2: v1 unified Ads API ────────────────────────────────────────
  // v1 returns ads with a creative.products[] array — a single ad can
  // target multiple ASINs/SKUs. Store the full creative envelope here
  // (includes adType, creative.products, headline, brand logo URL for
  // SB creatives, etc.). The flat asin/sku columns above hold the
  // FIRST product for back-compat with downstream queries.
  creativeJson    Json?
  adType          String? // PRODUCT_AD | BRAND_AD | VIDEO_AD ...
  deliveryStatus  String?
  deliveryReasons String[] @default([])

  @@unique([workspaceId, adGroupId, asin], name: "adGroupId_asin", map: "AdProductAd_adGroupId_asin_key")
  @@index([productId])
  @@index([asin])
  @@index([workspaceId])
}

// APS.5b — a named, reusable product selection for the campaign builders.
//
// Distinct from SavedView, which stores FILTERS (a query re-evaluated on read).
// This stores a SELECTION (an explicit list the operator curated), so the two
// cannot share a table without one of them lying about what it holds.
//
// Scoped to channel + marketplace because a set curated for Italy is not valid
// for Germany — the advertisable catalogue differs, which is the whole premise
// of APS. Loading a set re-resolves the ids against the CURRENT scope and
// reports anything that has since fallen out, rather than silently staging
// products that can no longer be advertised.
//
// Account-wide rather than per-user (unlike SavedView): a small ops team wants
// "GALE launch set" to mean the same thing for everyone. createdBy is recorded
// for attribution, not for isolation.
model AdProductSet {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String   @id @default(cuid())
  name        String
  channel     String   @default("AMAZON")
  marketplace String
  // Product ids only. Resolving on read keeps names/ASINs current and makes
  // drift visible; a denormalized snapshot would quietly go stale.
  productIds  String[] @default([])
  createdBy   String?
  createdAt   DateTime @default(now())
  updatedAt   DateTime @updatedAt

  @@unique([workspaceId, channel, marketplace, name], name: "channel_marketplace_name", map: "AdProductSet_channel_marketplace_name_key")
  @@index([channel, marketplace])
  @@index([workspaceId])
}

// AD.1 — Amazon Advertising API connection envelope. Distinct from
// ChannelConnection because Ads API uses a separate LWA-for-
// Advertising scope. One row per Amazon Ads profileId.
//
// Two-key live-write gating (AD.4 lands the operator UI):
//   1. NEXUS_AMAZON_ADS_MODE=live (deploy-wide env flag)
//   2. mode='production' AND writesEnabledAt != null
model AmazonAdsConnection {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                   String    @id @default(cuid())
  profileId            String
  marketplace          String
  region               String    @default("EU") // EU | NA | FE
  accountLabel         String?
  // AES-256-GCM via apps/api/src/lib/crypto.ts; payload shape:
  // { clientId, clientSecret, refreshToken }
  credentialsEncrypted String?
  mode                 String    @default("sandbox") // 'sandbox' | 'production'
  writesEnabledAt      DateTime? // AD.4 — operator opt-in for live writes
  lastWriteAt          DateTime?
  isActive             Boolean   @default(false)
  lastVerifiedAt       DateTime?
  lastErrorAt          DateTime?
  lastError            String?

  // ── AX-IE.0 — refresh-token lifetime tracking ────────────────────────
  // From 2026-07-30 Amazon refresh tokens expire 365 days from CONSENT. Nothing
  // used to track token age, so every connection would simply stop working a year
  // after authorisation with no warning and no way to see it coming.
  //
  // tokenIssuedAt is stamped at consent (amazon-ads-auth callback) and again on
  // every refresh-token rotation. tokenExpiresAt is derived, stored rather than
  // computed so the window can be corrected per-connection if Amazon's rule turns
  // out to differ.
  //
  // tokenIssuedAtIsEstimate marks a value we INFERRED rather than observed. The 10
  // existing connections were all seeded in one batch (createdAt 2026-05-17
  // 02:45:45, sub-second apart), so their true consent dates are unrecoverable —
  // the backfill uses createdAt as a conservative floor and flags it, so the UI can
  // never present a guess as a fact. Cleared the first time a real consent or
  // rotation stamps it.
  tokenIssuedAt           DateTime?
  tokenExpiresAt          DateTime?
  tokenIssuedAtIsEstimate Boolean   @default(false)

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([marketplace, isActive])
  @@index([tokenExpiresAt])
  @@unique([workspaceId, profileId], name: "workspace_profileId", map: "AmazonAdsConnection_workspace_profileId_key")
  @@index([workspaceId])
}

// ── Phase 2: v1 unified Amazon Ads API substrate ─────────────────────────
// Seven new tables that the v1 sync + reports layer reads/writes. All are
// additive — existing Campaign/AdGroup/AdTarget/AdProductAd unchanged
// except for the v1 columns added above. None of these tables are read
// by current code; they sit dormant until Phase 3 services land.

// First-class profile metadata. Today's AmazonAdsConnection only carries
// credentials + state; this table holds per-profile currency, timezone,
// account-type info needed for currency conversion + TZ-aware report
// ingestion. Populated by Phase 3 sync from GET /v2/profiles.
model AmazonAdsProfile {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                 String    @id @default(cuid())
  profileId          String
  marketplace        String
  region             String    @default("EU") // EU | NA | FE
  countryCode        String? // IT | DE | FR | ES | UK | NL | BE | PL | SE | US ...
  currencyCode       String    @default("EUR")
  timezone           String? // Europe/Rome | Europe/London | ...
  accountType        String    @default("seller") // seller | vendor | author | agency
  accountEntityId    String?
  accountName        String?
  validPaymentMethod Boolean   @default(true)
  lastSyncedAt       DateTime?
  lastProfileFetchAt DateTime?
  createdAt          DateTime  @default(now())
  updatedAt          DateTime  @updatedAt

  @@index([countryCode])
  @@index([currencyCode])
  @@index([marketplace])
  @@unique([workspaceId, profileId], name: "workspace_profileId", map: "AmazonAdsProfile_workspace_profileId_key")
  @@index([workspaceId])
}

/// KT.2 — the Keyword Tracker's watchlist: the terms an operator chose to WATCH, per market.
///
/// 🔴 This exists because `KeywordCoverageSet` (right below) is not a list, it is an ARMING
/// SWITCH. Measured on prod 2026-08-12: `ads-coverage-engine.service.ts` selects
/// `{ enabled: true }` sets and, at `NEXUS_COVERAGE_ENGINE_MODE=auto`, steps their keyword bids
/// through `updateAdTargetWithSync` — a real write to Amazon. That engine is scheduled daily at
/// 07:10 and has run six nights (mode=observe, sets=0, so nothing has been written yet), the
/// single existing set has `leadAsin` on all 97 of its terms, and `PATCH
/// /advertising/coverage-sets/:id { enabled }` is wired to a button on the Family Cockpit. Two
/// switches, both outside the Keyword Tracker, stand between that table and live bid changes.
///
/// So the tracker reads coverage sets as an IMPORT SOURCE ONLY — terms are copied out, never
/// referenced — and this table carries no `enabled` flag, because nothing here should ever be
/// one field away from arming a bid ladder.
///
/// Deliberately NOT on this model: `leadAsin`, `targetSharePct`, `isControl`,
/// `dailySpendCapCents`, `acosCapPct`. Those are coverage-engine intent. Half-populating them
/// here is exactly how two surfaces come to disagree about what automation is trying to do.
model KeywordWatchlist {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String  @id @default(cuid())
  /// IT | DE | ES | FR. One market per list — volume, rank and share are per-marketplace
  /// quantities, and serving one market's list to another is the defect KT.2 exists to fix
  /// (measured: only 8 of the 97 Italian terms have EVER had a DE row; 3 in ES; 3 in FR).
  marketplace String
  name        String
  /// The list this market opens on. There is no cross-market fallback, by design.
  isDefault   Boolean @default(false)
  /// Provenance of the terms, for the honesty line on the page:
  /// coverage-set-import | bid-keywords | sqp | manual | import
  source      String  @default("manual")
  createdBy   String?

  createdAt DateTime               @default(now())
  updatedAt DateTime               @updatedAt
  terms     KeywordWatchlistTerm[]

  @@unique([workspaceId, marketplace, name], name: "marketplace_name", map: "KeywordWatchlist_marketplace_name_key")
  @@index([marketplace, isDefault])
  @@index([workspaceId])
}

/// KT.2 — one watched term. See `KeywordWatchlist`.
model KeywordWatchlistTerm {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String           @id @default(cuid())
  watchlistId String
  watchlist   KeywordWatchlist @relation(fields: [watchlistId], references: [id], onDelete: Cascade)
  /// Lowercased, whitespace-collapsed — the same normalisation `AdKeywordProtection` stores and
  /// the same the tracker joins SQP on. Stored normalised so the join can never disagree.
  term        String
  /// STORED, not derived. KT.1 recomputed "is this our brand" on every read with a blanket
  /// substring sweep; `AdKeywordProtection` carries `matchType` (EXACT | PREFIX | CONTAINS) and a
  /// nullable `marketplace`, and the sweep honoured neither. It is seeded from the honoured
  /// classifier and then owned by the operator, who can flip one term without editing a
  /// protection rule that also gates negative-keyword harvesting.
  isBranded   Boolean          @default(false)
  /// Where this specific term came from, when it differs from the list's own source.
  addedFrom   String?
  notes       String?
  createdAt   DateTime         @default(now())

  @@unique([workspaceId, watchlistId, term], name: "watchlistId_term", map: "KeywordWatchlistTerm_watchlistId_term_key")
  @@index([watchlistId, isBranded])
  @@index([workspaceId])
}

// Amazon-native portfolio (campaign grouping). Linked to Campaign via
// Campaign.portfolioId (already exists as a string column).
/// ACR.3 (Stage 2.1/3) — the curated keyword set a family DELIBERATELY covers.
///
/// The Coverage board derives from whatever SQP happens to return; the pilot needs intent:
/// which terms this family is trying to own, which ASIN leads each term, and what the family
/// is willing to pay. One set per portfolio; terms are rows so per-term state (lead, caps,
/// status) has a home. The engine reads THIS, never raw SQP, so "what is automation trying to
/// do" is always answerable from one table.
