  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                 String                @id @default(cuid())
  /// External portfolio id — matches Campaign.portfolioId and the cockpit URLs.
  portfolioId        String
  marketplace        String
  name               String
  enabled            Boolean               @default(false)
  /// Family-level guardrails the engine must respect (pilot: hard caps, per plan §4.4).
  dailySpendCapCents Int?
  acosCapPct         Decimal?              @db.Decimal(6, 2)
  createdAt          DateTime              @default(now())
  updatedAt          DateTime              @updatedAt
  createdBy          String?
