// Universal daily time-series for every advertising entity. One row per
// (profile, adProduct, entityType, entityId, date). Replaces today's
// pattern of mutating Campaign.spend/sales/impressions counters in-place
// with a true time-series the rollup + charts can query.
//
// Monetary fields use BigInt micros (1 EUR = 1_000_000) to handle
// cross-currency conversion (GBP/PLN/SEK) without precision loss. Every
// row carries currencyCode explicitly so the rollup knows what to
// convert from.
// AX3 — `AmazonAdsDailyPerformanceArchive` exists in the database and DELIBERATELY has no model
// here. It is created by `20260826b_ax3_ams_daily_archive` with `LIKE "AmazonAdsDailyPerformance"
// INCLUDING DEFAULTS`, so its columns track this model's exactly rather than through a hand-
// written mirror that one typo makes unrestorable. It holds rows removed from the table below,
// with `archivedAt` / `archivedReason`. Read it with raw SQL — having no model is what stops it
// being accidentally joined into a live aggregate, which is the mistake that put rows in it.
//
model AmazonAdsDailyPerformance {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id            String   @id @default(cuid())
  profileId     String
  marketplace   String
  adProduct     String // SPONSORED_PRODUCTS | SPONSORED_BRANDS | SPONSORED_DISPLAY | SPONSORED_TELEVISION
  date          DateTime @db.Date
  // CAMPAIGN | AD_GROUP | AD_TARGET | PRODUCT_AD | SEARCH_TERM | PLACEMENT
  entityType    String
  entityId      String // external Amazon ID
  // FK to Campaign.id / AdGroup.id / AdTarget.id / AdProductAd.id — null
  // when the entity isn't tracked locally (search terms / placements).
  localEntityId String?

  // Universal metrics
  impressions  Int    @default(0)
  clicks       Int    @default(0)
  costMicros   BigInt @default(0)
  currencyCode String

  // Attribution windows (available varies per adProduct)
  //
  // 🔴 SPC.1 — the four `sales*Cents` and the two 7d counters below carry
  // `@default(0)`, and that default is why 1d/14d/30d could never be read: nothing
  // ever requested them, so every row said 0, and 0 is ALSO the correct answer for
  // a campaign-day that sold nothing. Every column ADDED from here down is
  // deliberately nullable with NO default — NULL means "not requested for this
  // row", 0 means "Amazon said zero". The same conflation in `rowsIngested` cost
  // Italy seven days of data before anyone could see it.
  sales1dCents  Int? @default(0)
  sales7dCents  Int? @default(0)
  sales14dCents Int? @default(0)
  sales30dCents Int? @default(0)
  orders7d      Int? @default(0)
  units7d       Int? @default(0)

  // SPC.1 — the other three attribution windows, as counts. The sales side of
  // these already existed above; the orders and units did not.
  orders1d  Int?
  orders14d Int?
  orders30d Int?
  units1d   Int?
  units14d  Int?
  units30d  Int?

  // SPC.1 — same-SKU attribution: did the ad sell the product it advertised, or
  // something else of ours? `sales7dCents` counts both and cannot tell them apart,
  // so harvest and negation currently run on a blended number.
  //
  // Amazon offers no otherSku column at campaign grain — halo is derived as
  // (total − sameSku) at read time, which is a subtraction of two sums and stays
  // correct at every grouping.
  salesSameSku1dCents  Int?
  salesSameSku7dCents  Int?
  salesSameSku14dCents Int?
  salesSameSku30dCents Int?
  ordersSameSku1d      Int?
  ordersSameSku7d      Int?
  ordersSameSku14d     Int?
  ordersSameSku30d     Int?
  unitsSameSku1d       Int?
  unitsSameSku7d       Int?
  unitsSameSku14d      Int?
  unitsSameSku30d      Int?

  // SPC.1 — Amazon's own top-of-search impression share at THIS grain. We already
  // capture it per placement; per campaign it answers whether a flat campaign is
  // bid-limited or volume-limited. Same type as AmazonAdsPlacementReport's.
  topOfSearchIS Decimal? @db.Decimal(8, 4)

  // SPC.1 — the campaign's configuration AS IT WAS ON THAT DAY, which arrives free
  // on a row we already fetch. `campaignBudgetCents` beside that day's spend makes
  // budget utilisation and days-capped computable over history for the first time;
  // today we can only compare today's spend against today's budget. The two rule
  // fields record when one of Amazon's own native budget rules moved the number —
  // a writer our audit chain cannot otherwise see.
  campaignBudgetCents          Int?
  campaignBudgetType           String?
  campaignBiddingStrategy      String?
  campaignRuleBasedBudgetCents Int?
  campaignBudgetRuleId         String?
  campaignBudgetRuleName       String?

  // SPC.1 — the name and status Amazon sent, as at that day. Both were ALREADY
  // being requested and thrown away on arrival: the name on screen comes from a
  // join to our own Campaign table, which is why 659 of 4,822 campaign rows (13.7%)
  // render a raw Amazon id. Named for the entity rather than the campaign so the
  // later targeting and product-ad reports can fill the same two columns.
  entityName   String?
  entityStatus String?

  // New-to-brand (SB/SD only)
  //
  // 🔴 ADM-A3 — these two were `@default(0)` and 0 on all 6,045 rows, and the reason was NOT that
  // Amazon withholds them: `CAMPAIGN_COLUMNS` never requested a single `newToBrand*` column for
  // ANY ad product. Verified 2026-08-26 by asking Amazon directly (an invalid column name makes
  // the v3 report API return its allowed list): SPONSORED_BRANDS offers 14 newToBrand columns,
  // SPONSORED_DISPLAY 11, and SPONSORED_PRODUCTS **none** — so "n/a — SP" is true for SP and was
  // never true for SB/SD. `default(0)` is what let an unasked question read as a measured zero.
  ntbOrders14d     Int?   @default(0)
  ntbSalesCents14d Int?   @default(0)
  // ADM-A3 — the third base count. Amazon offers `newToBrandUnitsSold` on both SB and SD.
  // No `@default(0)`: null means "not reported for this ad product", which is the distinction the
  // two columns above lost.
  ntbUnits14d      Int?
  // Amazon's OWN new-to-brand order rate (`newToBrandPurchasesRate`). SPONSORED_BRANDS only — SD
  // does not offer it — so null on every SP and SD row by construction, not by omission. The three
  // NTB *percentages* the grid shows are derived (ntb ÷ total) rather than stored, because only SB
  // publishes them and one derivation used everywhere beats two rules that can disagree.
  ntbOrdersRate14d Float?

  // Engagement (SD/SB only)
  //
  // ⚠ `viewableImpressions` is NOT offered by ANY v3 campaign report — not SP, not SB, not SD
  // (SD publishes `viewabilityRate` and `viewClickThroughRate` instead, which are rates, not a
  // count). So the grid's "View Impr." column can never be sourced at campaign grain and its cell
  // says so. Kept because the field is still part of the ingest row shape.
  viewableImpressions Int? @default(0)
  // ⚠ Offered by SB and SD (`detailPageViews`) but by no SP report, and NOTHING renders it today.
  // Left unrequested deliberately: requesting a column no surface reads is how this table filled
  // up with measured-looking zeros in the first place.
  detailPageViews7d   Int? @default(0)

  // ADM-A3 — Kindle Edition Normalized Pages. The Ad Manager said "this account sells no books, so
  // Amazon has nothing to report" — an unverified BUSINESS claim standing in for an ingest gap.
  // Amazon offers `kindleEditionNormalizedPagesRead14d` and `…Royalties14d` on the SP campaigns
  // report; we simply never asked. Null means not reported; 0 will mean a real measured zero.
  kenpRead14d           Int?
  kenpRoyaltiesCents14d Int?

  // Derived — indexed for filtering "show me campaigns with ACOS > 50%"
  acos7d Decimal? @db.Decimal(8, 4)
  roas7d Decimal? @db.Decimal(8, 4)

  reportRunId String?
  reportedAt  DateTime
  createdAt   DateTime @default(now())

  @@unique([workspaceId, profileId, adProduct, entityType, entityId, date], name: "profileId_adProduct_entityType_entityId_date", map: "AmazonAdsDailyPerformance_profileId_adProduct_entityT_4f88ac473")
  @@index([profileId, adProduct, date])
  @@index([localEntityId, date])
  @@index([marketplace, date, adProduct])
  // PERF — campaign/ad-group detail aggregates by (entityType, entityId, date).
  // The unique key buries entityId behind profileId+adProduct, so the
  // entityId-only branch in computeCampaignDetailMetrics seq-scanned. This
  // index makes the detail-page aggregation an index range scan.
  @@index([entityType, entityId, date])
  @@index([workspaceId])
}

// CD.11 — hourly grain (Amazon Marketing Stream). Mirrors the daily table but
// keyed additionally by `hour` (0-23, UTC) so dayparting (which hour×weekday
// converts) and hourly share-of-voice become possible — the genuine edge over
// the once-daily Seller Central reports. Written by the AMS ingest alongside
// the daily roll-up. 90-day rolling retention via the weekly cleanup cron.
model AmazonAdsHourlyPerformance {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id            String   @id @default(cuid())
  profileId     String
  marketplace   String
  adProduct     String
  date          DateTime @db.Date
  hour          Int // 0-23, UTC
  entityType    String
  entityId      String // external Amazon ID
  localEntityId String?

  impressions  Int    @default(0)
  clicks       Int    @default(0)
  costMicros   BigInt @default(0)
  currencyCode String

  sales7dCents Int? @default(0)
  orders7d     Int? @default(0)
  units7d      Int? @default(0)

  reportRunId String?
  reportedAt  DateTime
  createdAt   DateTime @default(now())

  @@unique([workspaceId, profileId, adProduct, entityType, entityId, date, hour], map: "AmazonAdsHourlyPerformance_entity_date_hour_key", name: "profileId_adProduct_entityType_entityId_date_hour")
  @@index([localEntityId, date], map: "AmazonAdsHourlyPerformance_localEntityId_date_idx")
  @@index([marketplace, date, hour, adProduct], map: "AmazonAdsHourlyPerformance_mkt_date_hour_idx")
  @@index([workspaceId])
}

// ADM-P6 — Amazon's OWN per-campaign budget-usage reading, sampled.
//
// `POST /sp/campaigns/budget/usage` answers for every Sponsored Products campaign
// (measured 2026-08-22: 200 of 200; the 19 it refuses are all SD/SB, which the SP
// endpoint does not cover). It returns three things and each one matters:
//   percent        Amazon's own consumption figure, NOT derived by us
//   budgetCents    the budget THAT reading was a percentage of — it moves intraday
//   usageUpdatedAt Amazon's usageUpdatedTimestamp: the age of the READING itself
//
// 🔴 The timestamp is load-bearing, not decoration. Amazon does not zero the
// percentage at the daily reset; it simply stops updating it. Measured the same day:
// DE_Auto_Close read 27.2% stamped 19:59Z the PREVIOUS day, hours after the 00:00Z
// reset. A reading older than the current budget day describes yesterday, and
// rendering it as today's utilization would be a confident lie with a fresh look.
//
// One row per distinct reading, not per poll: `firstSeenAt`/`lastSeenAt` bracket the
// span over which that reading was continuously observed. That is what makes the
// hour columns possible at all — an hour is out-of-budget if a >=100% reading was
// observed across it, and an hour is observed only if some reading spans it. Storing
// one row per poll instead would be 57,600 rows a day to say the same thing.
model AdBudgetUsageSample {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                 String @id @default(cuid())
  campaignId         String // local Campaign.id
  externalCampaignId String
  profileId          String
  marketplace        String

  /// As Amazon sends it: 0-100+, a PERCENT and not a fraction. Above 100 is normal.
  percent     Float
  /// Amazon's own budget for this campaign at the moment of the reading. NULL when the source did
  /// not carry one — the pull API always does, the stream's shape is unverified (ADM-P6/B2), and a
  /// fabricated 0 would make the denominator a lie rather than an absence.
  budgetCents Int?

  /// Amazon's usageUpdatedTimestamp. Compare against the 00:00 UTC budget-day start.
  usageUpdatedAt DateTime
  /// When WE first saw this reading, and when we last saw it still current.
  firstSeenAt    DateTime @default(now())
  lastSeenAt     DateTime @default(now())

  /// 'pull' = the budget-usage API. 'stream' = AMS budget-usage (Track B), same table.
  source String @default("pull")

  createdAt DateTime @default(now())

  @@unique([workspaceId, campaignId, source, usageUpdatedAt], map: "AdBudgetUsageSample_reading_key", name: "campaignId_source_usageUpdatedAt")
  @@index([campaignId, usageUpdatedAt], map: "AdBudgetUsageSample_campaign_reading_idx")
  @@index([lastSeenAt], map: "AdBudgetUsageSample_lastSeenAt_idx")
  @@index([workspaceId])
}

