// Phase E — outbound webhook subscriptions. The operator points us
// at a URL; we sign payloads with HMAC-SHA256 and POST them when an
// event fires. Subscription rows are read by the eventual webhook-
// dispatch worker (out of scope for Phase E itself — schema +
// subscription CRUD + test-payload land here, real event-triggered
// delivery is wired when the emitters get touched).
model NotificationWebhook {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id               String       @id @default(cuid())
  userId           String?
  user             UserProfile? @relation(fields: [userId], references: [id], onDelete: Cascade)
  label            String // operator-supplied
  url              String
  // HMAC secret. Generated server-side at create time; we show the
  // plaintext exactly once and store the bcrypt hash for verification.
  secretHash       String
  secretPrefix     String // first 8 chars of the raw secret for UI display
  // Which event-types this subscription covers. Empty = ALL events.
  events           String[]     @default([])
  isActive         Boolean      @default(true)
  // Last-fire telemetry; populated by the dispatch worker. Surfaced
  // on the subscription row so operators can spot stale endpoints.
  lastFiredAt      DateTime?
  lastStatus       Int?
  lastError        String?
  consecutiveFails Int          @default(0)
  createdAt        DateTime     @default(now())
  updatedAt        DateTime     @updatedAt

  @@index([userId])
  @@index([isActive])
  @@index([workspaceId])
}

model ApiKey {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id        String    @id @default(cuid())
  label     String
  keyHash   String // SHA-256 hash of the key
  keyPrefix String // First 8 chars for display (e.g., "nxk_abc1...")
  lastUsed  DateTime?
  revokedAt DateTime?
  createdAt DateTime  @default(now())
  updatedAt DateTime  @updatedAt

  // Phase G — finer-grained authorization.
  //
  // scopes: canonical strings from CANONICAL_SCOPES in
  //   apps/api/src/lib/api-key-auth.ts. Empty array means "full access"
  //   for backwards-compat with the original keys; new keys default to
  //   a narrow scope set chosen at create time.
  scopes             String[]  @default([])
  // ipAllowlist: optional IPv4/IPv6 CIDR or plain-IP list. Empty array
  //   means "any IP". Non-empty restricts the key to those addresses
  //   (24/64-bit prefix; CIDR notation accepted).
  ipAllowlist        String[]  @default([])
  // Optional hard expiry. Null = never expires (legacy default).
  expiresAt          DateTime?
  // Rotation pair: when a key is rotated we issue a new ApiKey row
  // and stamp the old one with rotatedAt + rotatedToId. The old key
  // keeps validating until rotationGraceUntil, after which the
  // verifier rejects it with a clear "rotated; use new key" error.
  rotatedAt          DateTime?
  rotatedToId        String?
  rotationGraceUntil DateTime?
  @@index([workspaceId])
}

model UserProfile {
  workspaceMemberships WorkspaceMembership[]
  id                   String                   @id @default(cuid())
  displayName          String                   @default("")
  // S1 (auth core): email is the login identity → must be unique. Safe
  // for the single-operator row today; enforced in app logic too. The
  // legacy default("") is retained only so the pre-S1 singleton row (if
  // its email was never set) doesn't block the migration.
  email                String                   @unique @default("")
  avatarUrl            String                   @default("")
  // Password hash. Phase C migrates from sha256 (legacy) to bcrypt;
  // the verifier auto-detects format and re-hashes on next successful
  // login. Empty string = no password set yet.
  passwordHash         String                   @default("")
  // Phase C — locale / scheduling fields surfaced on /settings/profile.
  // All nullable so the existing seeded row keeps working without a
  // backfill; defaults applied at the UI layer.
  phone                String?
  timezone             String? // IANA, e.g. "Europe/Rome"
  language             String? // BCP-47, e.g. "it-IT"
  dateFormat           String? // "DD/MM/YYYY" | "MM/DD/YYYY" | "YYYY-MM-DD"
  weekStart            Int? // 0 = Sunday, 1 = Monday
  workingHoursStart    String? // "09:00"
  workingHoursEnd      String? // "18:00"
  // Phase E — quiet hours. Distinct from working hours: a notification
  // suppressed during quiet hours is held (and rolled into the next
  // digest, if applicable) rather than dropped. Null = no quiet hours.
  // Stored as "HH:MM" strings; the user's timezone above resolves them.
  // If start > end (e.g. "22:00" → "07:00"), the window wraps midnight.
  quietHoursStart      String?
  quietHoursEnd        String?
  // Phase C — 2FA (TOTP). Secret is base32; null when 2FA is off.
  // enabledAt is set when the user verifies the first 6-digit code;
  // a pending-but-not-confirmed enrollment leaves enabledAt null.
  twoFactorSecret      String?
  twoFactorEnabledAt   DateTime?
  createdAt            DateTime                 @default(now())
  updatedAt            DateTime                 @updatedAt
  // W9.x — workflow assignments this user appears in
  workflowAssignments  WorkflowAssignment[]
  // Phase C — security tables.
  recoveryCodes        TwoFactorRecoveryCode[]
  sessions             UserSession[]
  loginEvents          LoginEvent[]
  // Phase E — per-user notification prefs + webhook subscriptions.
  notificationPrefs    NotificationPreference[]
  notificationWebhooks NotificationWebhook[]
  // Phase H — privacy + consent + export requests.
  consents             ConsentRecord[]
  exportRequests       DataExportRequest[]

  // ── Phase S1 (auth core) — account lifecycle + login hardening ──
  // Deactivation is the offboarding switch: status="deactivated"
  // blocks login and (via the session layer) revokes on next request.
  // A newly invited user starts "active" but holds zero roles → no
  // access until a role is assigned (least-privilege default).
  status             String               @default("active") // "active" | "deactivated"
  deactivatedAt      DateTime?
  // Progressive lockout counters. Persisted here (not in-memory) so
  // they survive restarts and hold across Railway replicas without
  // depending on Redis uptime.
  failedLoginCount   Int                  @default(0)
  lockedUntil        DateTime?
  lastLoginAt        DateTime?
  // Immediate propagation (§3.5): bumped on any role/permission/user
  // mutation affecting this user. Cached permission sets are keyed by
  // (userId, permissionsVersion); a bump invalidates them on next request.
  permissionsVersion Int                  @default(0)
  // Per-user MFA override. The assigned role's requireMfa also applies;
  // effective requirement is the OR of the two (enforced in S5).
  mfaRequired        Boolean              @default(false)
  // ── Phase S1 relations ──
  roleAssignments    UserRole[]
  resetTokens        PasswordResetToken[]
  invitationsSent    Invitation[]         @relation("invitedBy")
}

// Phase H — consent log (GDPR Art. 7). Append-only; each row pins a
// version (e.g. dpa-v2026-05) + a timestamp so we can prove what the
// operator accepted, when. Marketing-comms opt-in/out flips create
// new rows rather than mutating the previous one.
model ConsentRecord {
  id        String       @id @default(cuid())
  userId    String?
  user      UserProfile? @relation(fields: [userId], references: [id], onDelete: SetNull)
  // 'DPA' | 'COOKIE_ANALYTICS' | 'COOKIE_MARKETING' | 'TOS' |
  // 'PRIVACY_POLICY' | 'MARKETING_EMAIL' | 'MARKETING_SMS'
  kind      String
  version   String // semver-ish: 'v2026-05' or '1.4.0'
  accepted  Boolean // true on accept, false on opt-out
  // Free-form context: which page surfaced the consent, IP, UA.
  // GDPR requires we can prove the consent was given freely +
  // informed; this metadata helps.
  ip        String?
  userAgent String?
  metadata  Json?
  createdAt DateTime     @default(now())

  @@index([userId])
  @@index([userId, kind])
  @@index([createdAt])
}

// Phase H — data retention policy. Single row per workspace.
// `policies` is a JSON map keyed by data-type ("orders", "audit",
// "loginEvents", etc.) → number of days. The retention cron reads
// this row + sweeps rows older than the configured window. IT
// fiscal law mandates 7y minimum for invoiced orders, so the UI
// pins the orders slider at 2555+ days.
model DataRetentionPolicy {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id        String   @id @default(cuid())
  // Single-row pattern — no userId. Workspace-global.
  policies  Json     @default("{}")
  updatedAt DateTime @updatedAt
  createdAt DateTime @default(now())
  @@index([workspaceId])
}

// Phase H — async export jobs. The MVP runs synchronously (assembles
// JSON in the request) so downloadUrl is filled immediately and
// status jumps from QUEUED → COMPLETED in the same tick. Schema
// shape supports a real out-of-process worker later without UI
// changes.
model DataExportRequest {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String       @id @default(cuid())
  userId      String?
  user        UserProfile? @relation(fields: [userId], references: [id], onDelete: SetNull)
  // 'QUEUED' | 'RUNNING' | 'COMPLETED' | 'FAILED'
  status      String       @default("QUEUED")
  // Format the operator picked. 'json' for the MVP; 'zip' lands when
  // we add a worker that builds a real archive.
  format      String       @default("json")
  // What's in the export. Free-form array of data-type keys for
  // future-proofing ('all' covers everything).
  scope       String[]     @default([])
  // Where to fetch the result. For synchronous JSON dumps this is a
  // route handle the UI calls; for async ZIPs it'd be an S3/CDN URL.
  downloadUrl String?
  // Hard-expiry on the download for privacy reasons — past this
  // timestamp the route refuses to serve. Defaults to 7 days.
  expiresAt   DateTime?
  // Size of the rendered payload, set once COMPLETED. Used in the
  // history list so operators see what they're about to download.
  bytes       Int?
  // Free-form error context on FAILED.
  error       String?
  createdAt   DateTime     @default(now())
  completedAt DateTime?

  @@index([userId])
  @@index([userId, status])
  @@index([createdAt])
  @@index([workspaceId])
}

// ── Phase C — TOTP recovery codes ──────────────────────────────────
// Generated 10 at a time when 2FA is enrolled (and re-generated on
// demand from the security page). Stored as bcrypt hashes; the raw
// codes are shown to the operator exactly once at generation time.
// usedAt is set when a code is consumed for login; consumed codes
// are kept for audit (never re-usable) until the next regeneration
// clears them.
model TwoFactorRecoveryCode {
  id        String      @id @default(cuid())
  userId    String
  user      UserProfile @relation(fields: [userId], references: [id], onDelete: Cascade)
  codeHash  String // bcrypt of the raw code
  usedAt    DateTime?
  createdAt DateTime    @default(now())

  @@index([userId])
  @@index([userId, usedAt])
}

// ── Phase C — active sessions ──────────────────────────────────────
// One row per browser/device that has authenticated. Refresh-token
// rotation updates lastSeenAt; revoke sets revokedAt; an explicit
// "log out everywhere" sets revokedAt on every non-current row.
//
// Until full auth middleware lands (Phase I), this table is read-
// mostly — the UI renders rows so the schema is plumbed end-to-end,
// even if the only writer for now is the eventual auth handshake.
model UserSession {
  id          String      @id @default(cuid())
  userId      String
  user        UserProfile @relation(fields: [userId], references: [id], onDelete: Cascade)
  // Stable per-device identifier; safe to display in the UI.
  tokenPrefix String // first 8 chars of the hashed refresh token
  userAgent   String? // "Chrome 126 on macOS"
  ipAddress   String? // truncated IPv4 /24 or IPv6 /64 for privacy
  ipCity      String? // GeoIP lookup result, best-effort
  ipCountry   String? // ISO 3166-1 alpha-2
  createdAt   DateTime    @default(now())
  lastSeenAt  DateTime    @default(now())
  revokedAt   DateTime?

  // ── Phase S1 (auth core) — make this the live session store ──
  // sha256 of the opaque session token carried in the httpOnly cookie.
  // Nullable so pre-S1 rows (none in prod) don't break the migration;
  // unique so a token maps to exactly one session. The lookup is by
  // this hash; the raw token never touches the DB.
  sessionTokenHash String?   @unique
  // Sliding idle timeout: bumped on each authenticated request; a
  // session past idleExpiry is dead even if not explicitly revoked.
  idleExpiry       DateTime?
  // Absolute lifetime cap: a session cannot outlive this regardless of
  // activity, forcing periodic re-auth.
  absoluteExpiry   DateTime?
  // Step-up bookkeeping: set once this session has satisfied TOTP for
  // this login (S5). Sessions started before MFA enforcement read false.
  mfaSatisfied     Boolean   @default(false)

  @@index([userId])
  @@index([userId, revokedAt])
}

// ── Phase C — login history ────────────────────────────────────────
// Append-only login event log. One row per attempt (success or
// failure) so the user can review "did I really log in from Berlin?"
// or "someone tried to brute-force my account at 03:14 from this IP".
// Outcome is enum-like; we keep it as a string column to avoid Prisma
// enum migrations as new outcomes appear (e.g. "totp_failed",
// "recovery_code_used").
model LoginEvent {
  id         String       @id @default(cuid())
  userId     String?
  user       UserProfile? @relation(fields: [userId], references: [id], onDelete: SetNull)
  // Even on failed logins we capture the email tried so the user
  // can spot stuffing attempts against their address.
  emailTried String?
  outcome    String // "success" | "bad_password" | "totp_failed" | "recovery_code_used" | "locked"
  userAgent  String?
  ipAddress  String?
  ipCity     String?
  ipCountry  String?
  metadata   Json?
  createdAt  DateTime     @default(now())

  @@index([userId])
  @@index([createdAt])
}

// ══ Phase S1/S2 — RBAC (roles, assignments, invitations) ═══════════
//
// Seeded system roles are protected: they cannot be deleted, and OWNER
// is implicit-all (the permission resolver short-circuits before ever
// reading Role.permissions for an OWNER). Custom roles carry
// isSystem=false and any permission subset. See docs/security/.

enum SystemRole {
  OWNER
  ADMIN
  OPS_MANAGER
  FULFILLMENT
  FINANCE
  VIEWER
}

// A role is a named permission set. The six SystemRole rows are seeded
// (OWNER in S1; the rest + their permission arrays in S2). Owners may
// create unlimited custom roles.
model Role {
  // Null for immutable platform role templates; custom roles belong to one business.
  workspaceId String?
  version Int @default(1)
  workspaceAssignments WorkspaceMemberRole[]
  id          String   @id @default(cuid())
  // For seeded roles this equals a SystemRole value ("OWNER"); for
  // custom roles it is a slug. Unique so lookups + seeds are idempotent.
  key         String   @unique
  name        String
  description String   @default("")
  // OWNER is implicit-all: enforcement never reads this list for OWNER.
  // Everyone else is deny-by-default — a permission absent here is denied.
  // String[] (not a join table) mirrors the existing ApiKey.scopes model
  // and avoids a join on every permission resolve.
  permissions String[] @default([])
  isSystem    Boolean  @default(false)
  // S5 — force MFA for holders of this role (seeded true for
  // OWNER/ADMIN/FINANCE in S5). Effective requirement OR's with
  // UserProfile.mfaRequired.
  requireMfa  Boolean  @default(false)
  createdAt   DateTime @default(now())
  updatedAt   DateTime @updatedAt

  assignments UserRole[]
  invitations Invitation[]

  @@index([isSystem])
  @@index([workspaceId])
}

// Assignment of a role to a user, optionally scoped to channels/markets.
// A user may hold multiple assignments; the effective permission set is
// the union. OWNER assignment ignores channelScope (implicit-all).
model UserRole {
  id     String      @id @default(cuid())
  userId String
  user   UserProfile @relation(fields: [userId], references: [id], onDelete: Cascade)
  roleId String
  role   Role        @relation(fields: [roleId], references: [id], onDelete: Cascade)

  // null = all channels/marketplaces (fast path — most assignments).
  // Else e.g. { "channels": ["EBAY"], "marketplaces": ["IT"] }.
  // Column exists from day one; enforcement wiring + UI ship in S4+.
  channelScope    Json?
  // Accountability — who granted this assignment, when.
  grantedByUserId String?
  createdAt       DateTime @default(now())

  @@unique([userId, roleId])
  @@index([userId])
  @@index([roleId])
}

// Invite-only access. No public registration. Single-use, hashed token,
// 72h TTL, bound to an email + role (+ optional channel scope). Delivered
// as a copyable link and/or a Resend email.
model Invitation {
  id              String      @id @default(cuid())
  email           String
  roleId          String
  role            Role        @relation(fields: [roleId], references: [id], onDelete: Restrict)
  // sha256 of the raw token. The raw token is shown once at creation and
  // emailed; only the hash is stored, so a DB read cannot forge an invite.
  tokenHash       String      @unique
  // Mirrors UserRole.channelScope for the assignment created on accept.
  channelScope    Json?
  invitedByUserId String
  invitedBy       UserProfile @relation("invitedBy", fields: [invitedByUserId], references: [id], onDelete: Cascade)
  expiresAt       DateTime
  acceptedAt      DateTime?
  acceptedUserId  String?
  revokedAt       DateTime?
  createdAt       DateTime    @default(now())

  @@index([email])
  @@index([expiresAt])
}

// Password reset. Single-use, hashed token, ≤60min TTL. On successful
// reset every session for the user is revoked.
model PasswordResetToken {
  id        String      @id @default(cuid())
  userId    String
  user      UserProfile @relation(fields: [userId], references: [id], onDelete: Cascade)
  tokenHash String      @unique
  expiresAt DateTime
  usedAt    DateTime?
  createdAt DateTime    @default(now())

  @@index([userId])
  @@index([expiresAt])
}

// ── Webhook Event Tracking ─────────────────────────────────────────

model WebhookEvent {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String    @id @default(cuid())
  channel     String // SHOPIFY, WOOCOMMERCE, ETSY
  eventType   String // product/update, inventory/update, order/create, etc.
  externalId  String // Unique ID from marketplace (for idempotency)
  payload     Json // Raw webhook payload
  signature   String? // Webhook signature for verification
  isProcessed Boolean   @default(false)
  processedAt DateTime?
  error       String?
  createdAt   DateTime  @default(now())
  updatedAt   DateTime  @updatedAt

  // RT.3 — provider-reported event time. Lets us measure end-to-end
  // push latency as (createdAt - providerTimestamp). Nullable because
  // older rows + sources that don't expose a timestamp won't populate
  // it. The (channel, providerTimestamp) index supports the per-source
  // percentile queries on /api/admin/push-latency.
  providerTimestamp DateTime?

  // ── CX.4a — the inbound ledger ──────────────────────────────────
  // WebhookEvent IS the programme's InboundEvent (§3.4.3), extended rather
  // than replaced so the 5,158 rows already here stay part of the history.
  connectionId  String?
  // pending | done | failed | dlq. Derived from isProcessed at migration time
  // so the two can never disagree about the rows that predate this.
  status        String    @default("pending")
  attempts      Int       @default(0)
  nextAttemptAt DateTime?
  // Tri-state on purpose: true = checked and passed, false = checked and
  // failed, null = this transport carries no signature. Amazon's SQS
  // notifications are unsigned JSON trusted via the queue's IAM policy, so
  // neither true nor false would be honest about them.
  signatureOk   Boolean?
  // 'ebay_ecdsa' | 'sqs_iam' | 'shopify_hmac' | 'none'
  verifiedBy    String?
  payloadDigest String?
  lastError     String?
  // Decision 9 — archive, never delete.
  archivedAt    DateTime?
  archiveUri    String?

  @@unique([workspaceId, channel, externalId], name: "channel_externalId", map: "WebhookEvent_channel_externalId_key")
  @@index([isProcessed])
  @@index([channel])
  @@index([channel, providerTimestamp])
  @@index([status, nextAttemptAt])
  @@index([connectionId])
  @@index([workspaceId])
}

// ── CS.1: Channel → us inbound stock event ───────────────────────────
//
// We push outbound stock to channels (OutboundSyncQueue), but channels
// can adjust on their side too: Shopify admin manual edits, eBay
// merchant stock corrections, FBA inbound losses, etc. Without an
// inbound path our local StockLevel drifts and overselling becomes
// possible.
//
// Each row captures one channel-reported stock observation:
//   - channelReportedQty: what the channel says we have
//   - localQtyAtObservation: what our StockLevel said at ingest time
//   - drift: channelReportedQty - localQtyAtObservation
//
// Status lifecycle:
//   PENDING        — fresh ingest, awaits triage
//   AUTO_APPLIED   — small drift (≤ AUTO_APPLY_THRESHOLD), self-applied
//   REVIEW_NEEDED  — drift exceeded threshold, operator must review
//   APPLIED        — operator confirmed, applyStockMovement fired with
//                    reason=CHANNEL_STOCK_RECONCILIATION
//   IGNORED        — operator decided channel is wrong, no DB change
//
// Idempotency: (channel, channelEventId) unique — webhooks fire
// duplicates on retries; we accept the same event-id at most once.
/// IE.4 — Live channel image snapshots.
///
/// Stores what Amazon / eBay / Shopify are CURRENTLY serving as the
/// product's images. Refreshed on demand (operator click) and via
/// a cron sweep (IE.4b) so the workspace can show "this is what the
/// buyer sees" alongside Nexus' staged ListingImage rows. The IE.5
/// drift detector diffs these snapshots against the local intent
/// and surfaces mismatches.
///
/// This table is fed from outside-in (SP-API GetListingsItem, eBay
/// GetItem, Shopify product.media). Editing here doesn't touch the
/// channel — it's a read-replica of channel state. Use ListingImage
/// for the data Nexus intends to send.
model ChannelLiveImage {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id        String  @id @default(cuid())
  product   Product @relation(fields: [productId], references: [id], onDelete: Cascade)
  productId String

  // 'AMAZON' | 'EBAY' | 'SHOPIFY'. Three channels supported today;
  // Italian + EU compliance (project_active_channels) means no Woo / Etsy.
  channel String

  // Two-letter Amazon marketplace code (IT / DE / FR / ES / UK).
  // Null for eBay + Shopify which are not per-marketplace today.
  marketplace String?

  // The SKU we sent — Amazon uses sellerSku as the key when fetching
  // via GetListingsItem. Null for eBay + Shopify where the channel's
  // own product id is the natural key (stored separately if needed).
  externalSku String?

  // Amazon's assigned ASIN at the time of fetch. Surfaced in the UI
  // so the operator can confirm what's live without round-tripping.
  asin String?

  // Channel-specific slot identifier. Amazon: MAIN | PT01..PT08 | SWCH.
  // eBay: position-as-string ('0', '1', …). Shopify: media node id.
  slot String?

  url       String
  width     Int?
  height    Int?
  sortOrder Int    @default(0)

  // Channel response identifier for short-circuit on next fetch. SP-API
  // doesn't return ETag headers per-image but the GetListingsItem
  // response body changes when images change — we hash + store it
  // here to skip downstream work when nothing moved.
  etag String?

  fetchedAt DateTime @default(now())

  @@unique([workspaceId, productId, channel, marketplace, externalSku, slot], name: "productId_channel_marketplace_externalSku_slot", map: "ChannelLiveImage_productId_channel_marketplace_extern_e9f2711dd")
  @@index([productId, channel])
  @@index([fetchedAt])
  @@index([workspaceId])
}

model ChannelStockEvent {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  // SHOPIFY | EBAY | AMAZON | WOOCOMMERCE — narrowed at the route layer
  channel        String
  // Channel-side identifier for this stock observation (Shopify
  // inventory_level_id + updated_at, eBay variation key + timestamp,
  // SP-API report id). Null when the channel doesn't expose one
  // (legacy paths) — falls back to externalId.
  channelEventId String

  // Our product (resolved from channel SKU at ingest time).
  product     Product? @relation(fields: [productId], references: [id], onDelete: SetNull)
  productId   String?
  variationId String?
  sku         String

  // Optional location pin. Channels with multi-warehouse mapping
  // (Shopify locations, FBA fulfillment centers) carry this; null
  // for single-location channels.
  locationId String?

  channelReportedQty    Int
  localQtyAtObservation Int
  // Computed at ingest: channelReportedQty - localQtyAtObservation.
  // Persisted so list views don't recompute on every render.
  drift                 Int

  status              ChannelStockEventStatus @default(PENDING)
  // Free-form reason recorded when an operator picks IGNORED or
  // when AUTO_APPLY_THRESHOLD self-resolves a small drift.
  resolution          String?
  // Audit pointers — populated when status flips to APPLIED so the
  // operator can trace the resulting StockMovement back to its
  // origin event.
  resultingMovementId String?
  resolvedByUserId    String?
  resolvedAt          DateTime?

  // Raw channel payload — kept for forensic debug. JSONB so a
  // schema bump on the channel side doesn't require a migration.
  rawPayload Json?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@unique([workspaceId, channel, channelEventId], name: "channel_channelEventId", map: "ChannelStockEvent_channel_channelEventId_key")
  @@index([status])
  @@index([channel])
  @@index([productId])
  @@index([sku])
  @@index([createdAt])
  // Composite for the operator triage list:
  // "show me PENDING + REVIEW_NEEDED, newest first per channel".
  @@index([status, channel, createdAt(sort: Desc)])
  @@index([workspaceId])
}

enum ChannelStockEventStatus {
  PENDING
  AUTO_APPLIED
  REVIEW_NEEDED
  APPLIED
  IGNORED
}

// (model MarketplaceCredential removed in 20260506_h2_unify_channel_connection.
//  Designed for SHOPIFY/WOOCOMMERCE/ETSY but never wired up — their service
//  code reads process.env directly. All connection credentials now live on
//  ChannelConnection.)

// ── Rate Limit Tracking ────────────────────────────────────────────

model RateLimitLog {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id           String   @id @default(cuid())
  channel      String // SHOPIFY, WOOCOMMERCE, ETSY
  endpoint     String // API endpoint being rate limited
  requestCount Int      @default(0)
  resetAt      DateTime // When the rate limit window resets
  createdAt    DateTime @default(now())
  updatedAt    DateTime @updatedAt

  @@unique([workspaceId, channel, endpoint, resetAt], name: "channel_endpoint_resetAt", map: "RateLimitLog_channel_endpoint_resetAt_key")
  @@index([channel])
  @@index([resetAt])
  @@index([workspaceId])
}

// ── Amazon Catalog Sync Logging ─────────────────────────────────────────

