// ── Phase 2: Orders & Financials ────────────────────────────────────────

enum OrderChannel {
  AMAZON
  EBAY
  SHOPIFY
  WOOCOMMERCE
  ETSY
  MANUAL
}

enum OrderStatus {
  PENDING
  PROCESSING // O.1: paid, not yet shipped (Amazon "Unshipped", Woo "processing")
  PARTIALLY_SHIPPED // O.1: multi-package — some shipped, some not (Amazon "PartiallyShipped")
  ON_HOLD // O.1: fraud/address/inventory hold (Woo "on-hold")
  AWAITING_PAYMENT // O.1: Woo "pending", Shopify draft
  SHIPPED
  DELIVERED
  CANCELLED
  REFUNDED // O.1: Woo "refunded", Amazon refunded
  RETURNED // O.1: shipped → returned (distinct from REFUNDED if no money back yet)
}

model Order {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  // ── Phase 26: Unified Order Command ──────────────────────────────────
  // Cross-channel order ingestion
  channel         OrderChannel
  // D.1: marketplace code (IT/DE/UK/GLOBAL/etc.) — nullable for legacy rows.
  marketplace     String?
  channelOrderId  String // Unique per channel
  status          OrderStatus  @default(PENDING)
  totalPrice      Decimal      @db.Decimal(12, 2)
  // D.1: per-order currency snapshot at import time. Falls back to EUR.
  currencyCode    String?      @default("EUR")
  // O.20: customerName + customerEmail are KEPT as denormalized cache so
  // existing read paths (OrdersWorkspace + every dashboard query that
  // groupBy's on customerEmail) keep working unchanged. The Customer
  // relation below is the canonical identity; new code reads through it.
  customerName    String
  customerEmail   String
  customer        Customer?    @relation(fields: [customerId], references: [id], onDelete: SetNull)
  customerId      String?
  shippingAddress Json // { street, city, state, postalCode, country }

  // F.1 — Italian fiscal snapshot at sale time. Italian fiscal law
  // (DPR 633/72) cares about the values as of the order date, not
  // whatever the customer's profile happens to say later. Mirror of
  // the Customer.* fields below, snapshotted on order ingest.
  codiceFiscale      String? // 16 chars (individuals)
  partitaIva         String? // 11 digits (businesses)
  fiscalKind         String? // 'B2B' | 'B2C' | NULL = unknown
  pecEmail           String? // SDI fallback delivery
  codiceDestinatario String? // 7-char SDI routing code

  // D.1: Phase 28 — real customer-side timestamps. createdAt is the row
  // insert time (ingestion); these track the order's own lifecycle.
  purchaseDate DateTime?
  paidAt       DateTime?
  shippedAt    DateTime?
  deliveredAt  DateTime?
  cancelledAt  DateTime?

  // RV.2.1 — provenance of deliveredAt. The review-request pipeline keys
  // entirely off deliveredAt; we need to know whether a given value is
  // an authoritative signal (carrier confirm, MCF API, SP-API Delivered)
  // or a heuristic guess (FBA shippedAt + 3 business days). Higher-
  // authority sources never get overwritten by lower-authority ones.
  // Source enum:
  //   AMAZON_API       — SP-API GetOrder OrderStatus=Delivered
  //   AMAZON_REPORT    — _GET_FLAT_FILE_ORDERS_DATA_ report (future)
  //   CARRIER_WEBHOOK  — Sendcloud / DHL etc. delivery confirmation
  //   MCF_API          — Amazon MCF firstShipment.deliveredDate
  //   HEURISTIC_FBA_3D — FBA shippedAt + 3 business days (default)
  //   MANUAL           — operator override
  deliveredAtSource String?

  // D.1: FBA vs FBM (Amazon) or null for non-Amazon. Pulled from
  // SP-API FulfillmentChannel (AFN=FBA, MFN=FBM).
  fulfillmentMethod String?

  // O.1: Fulfillment-deadline fields. Drive ship-by urgency tinting on
  // the outbound surface (O.4), Prime SFP routing, and the late-shipment
  // outbound risk job (O.19). All nullable — non-Amazon channels often
  // don't supply them, and downstream code must tolerate absence.
  shipByDate         DateTime? // Amazon LatestShipDate / eBay handling deadline / Woo+Shopify: purchaseDate + fulfillmentLatency
  earliestShipDate   DateTime? // Amazon EarliestShipDate (don't ship before; Prime SFP gating)
  latestDeliveryDate DateTime? // Amazon LatestDeliveryDate — customer-facing promise; drives EDD on /track/...
  fulfillmentLatency Int? // handling-time days; lets us compute shipByDate where the channel doesn't supply it
  isPrime            Boolean? // Amazon Prime SFP eligibility (Amazon-only; null elsewhere)

  // Relations
  items                 OrderItem[]
  financialTransactions FinancialTransaction[]
  shipments             Shipment[]
  returns               Return[]
  reviewRequests        ReviewRequest[]
  reviewSentimentChecks ReviewSentimentCheck[]
  tags                  OrderTag[]
  mcfShipments          MCFShipment[] // S.24
  riskScore             OrderRiskScore? // O.22 — at most one per order
  fiscalInvoice         FiscalInvoice? // F.2 — at most one IT invoice per order
  notes                 OrderNote[] // AU.5 — per-order operator notes
  routingDecisions      RoutingDecision[] // CE.4 — routing audit trail

  // Metadata
  amazonMetadata      Json?
  ebayMetadata        Json?
  shopifyMetadata     Json?
  woocommerceMetadata Json?
  etsyMetadata        Json?
  createdAt           DateTime @default(now())
  updatedAt           DateTime @updatedAt

  // RB.1 — soft-delete (recycle bin). NULL = live, non-NULL = in recycle bin.
  // Status enum CANCELLED is the workflow state (refund processed, etc.);
  // deletedAt is purely a UI hide. They coexist independently.
  deletedAt DateTime?

  // MAP.2a — which connected account this row belongs to.
  channelConnection   ChannelConnection? @relation(fields: [channelConnectionId], references: [id], onDelete: SetNull)
  channelConnectionId String?

  @@unique([workspaceId, channel, channelOrderId], name: "channel_channelOrderId", map: "Order_channel_channelOrderId_key")
  @@index([channelConnectionId])
  @@index([channel])
  @@index([marketplace])
  @@index([status])
  @@index([customerEmail])
  @@index([createdAt])
  @@index([purchaseDate])
  @@index([deliveredAt])
  // O.1: ship-by urgency hot paths. Composite supports
  // "actionable orders by ship-by ASC". Prime partial index lives
  // in migration.sql (Prisma doesn't model partial indexes natively).
  @@index([shipByDate])
  @@index([status, shipByDate])
  @@index([customerId])
  @@index([fiscalKind]) // F.1 — batch SDI submission filters by B2B
  @@index([status, deletedAt]) // RB.1 — hot-path filter: live vs bin
  @@index([workspaceId])
}

// ── O.20: Customer model ─────────────────────────────────────────────
// Canonical customer identity, finally. Pre-O.20 customer info was
// denormalized on Order — repeat-customer detection, LTV, and the
// O.21 /customers page all needed a real table.
//
// Identity = lower(email). Backfill at migration time produces stable
// 'cust_' + md5(lower(email))[:24] ids; future inserts can keep that
// shape or use cuid()s — the FK is on id, not the format.
//
// Aggregate columns (totalOrders / totalSpentCents / firstOrderAt /
// lastOrderAt / channelOrderCounts) are a denormalized cache. Backfill
// snapshots them at migration time; subsequent commits wire writers
// at order-ingestion / cancellation / refund sites.
model Customer {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id    String  @id
  email String
  name  String?

  // F.1 — Italian fiscal identity. Codice fiscale for individuals
  // (16 alphanumeric) or partita IVA for businesses (11 digits).
  // fiscalKind drives invoice-vs-receipt rendering + SDI submission.
  codiceFiscale      String?
  partitaIva         String?
  fiscalKind         String? // 'B2B' | 'B2C' | NULL
  pecEmail           String? // SDI fallback delivery
  codiceDestinatario String? // 7-char SDI routing code

  totalOrders        Int       @default(0)
  // Cents to avoid Decimal vs JS-number drift on the read side.
  // BIGINT in SQL; Prisma maps to BigInt — but for a small-business-
  // scale app totals fit in Int safely (€20M cap at €0.01 precision).
  totalSpentCents    BigInt    @default(0)
  firstOrderAt       DateTime?
  lastOrderAt        DateTime?
  channelOrderCounts Json?

  // Operator surface
  tags               String[]  @default([])
  // O.22 risk engine populates these. NULL = unscored.
  riskFlag           String?
  manualReviewState  String?
  // O.22: timestamp of the last rollup. Drives "stale risk" affordances
  // on /customers (operator can see a customer scored hours ago vs
  // re-scored on every recent order).
  lastRiskComputedAt DateTime?

  // CI.1 — RFM scoring (Recency × Frequency × Monetary).
  // Computed nightly by rfm-scoring.job.ts. Each dimension is a quintile
  // 1–5 (5 = best). rfmScore is a 3-digit code e.g. '554'.
  // rfmLabel drives the segment color-coding and filter DSL.
  rfmScore      String? // e.g. '554' (R=5, F=5, M=4)
  rfmLabel      String? // CHAMPION | LOYAL | POTENTIAL | AT_RISK | LOST | NEW | ONE_TIME
  rfmComputedAt DateTime?

  // Relations
  orders    Order[]
  addresses CustomerAddress[]
  notes     CustomerNote[]

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([lastOrderAt])
  @@index([totalSpentCents])
  @@index([riskFlag])
  @@index([fiscalKind]) // F.1 — drives B2B/B2C filtering on /customers
  @@index([rfmLabel]) // CI.1 — segment filter + distribution query
  @@unique([workspaceId, email], name: "workspace_email", map: "Customer_workspace_email_key")
  @@index([workspaceId])
}

// CI.2 — Customer Segment / Cohort.
//
// Named cohorts defined by a multi-field filter DSL (same operators as
// AutomationRule). The engine evaluates conditions against Customer fields
// and caches the count. Operators use segments for bulk tagging, email
// export, and review-request scheduling.
//
// Condition DSL shape (same as AutomationRule.conditions):
//   [{ field: 'totalSpentCents', op: 'gte', value: 100000 },
//    { field: 'rfmLabel', op: 'in', value: ['CHAMPION', 'LOYAL'] }]
// Supported fields: totalSpentCents, totalOrders, riskFlag, fiscalKind,
//   rfmLabel, rfmScore, lastOrderAt (date ops), firstOrderAt, tags.
model CustomerSegment {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id            String    @id @default(cuid())
  name          String
  description   String?
  conditions    Json      @default("[]")
  customerCount Int       @default(0)
  lastCountedAt DateTime?
  createdBy     String?
  createdAt     DateTime  @default(now())
  updatedAt     DateTime  @updatedAt

  @@index([createdAt(sort: Desc)])
  @@unique([workspaceId, name], name: "workspace_name", map: "CustomerSegment_workspace_name_key")
  @@index([workspaceId])
}

model CustomerAddress {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  customer   Customer @relation(fields: [customerId], references: [id], onDelete: Cascade)
  customerId String

  // 'SHIPPING' | 'BILLING' | 'BOTH'
  type      String
  isPrimary Boolean @default(false)

  recipient  String?
  line1      String
  line2      String?
  city       String
  state      String?
  postalCode String
  country    String
  phone      String?

  // Source attribution: which channel/order seeded this row.
  source         String?
  channelOrderId String?

  createdAt DateTime @default(now())

  @@index([customerId])
  @@index([country])
  @@index([workspaceId])
}

model CustomerNote {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  customer   Customer @relation(fields: [customerId], references: [id], onDelete: Cascade)
  customerId String

  body         String
  authorUserId String?
  authorEmail  String?
  pinned       Boolean @default(false)

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([customerId])
  @@index([createdAt])
  @@index([workspaceId])
}

// ── F.2: Italian fiscal-year invoice numbering ───────────────────────
// Italian law (DPR 633/72 art. 21) requires sequential gap-free
// invoice numbering reset every fiscal year. FiscalInvoiceCounter
// tracks the current max per (year, issuer); FiscalInvoice records
// each assigned number (1:1 with Order, idempotent re-assignment).
model FiscalInvoiceCounter {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  fiscalYear Int
  issuer     String   @default("XAVIA")
  current    Int      @default(0)
  updatedAt  DateTime @default(now()) @updatedAt

  @@id([fiscalYear, issuer])
  @@index([workspaceId])
}

model FiscalInvoice {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id      String @id @default(cuid())
  order   Order  @relation(fields: [orderId], references: [id], onDelete: Cascade)
  orderId String @unique

  issuer         String @default("XAVIA")
  fiscalYear     Int
  sequenceNumber Int
  // Materialised "NNNNN/YYYY" — computed at insert time so PDF
  // rendering doesn't have to re-format.
  invoiceNumber  String

  // F.4 — SDI submission audit. NULL until the FatturaPA XML is
  // generated + dispatched.
  sdiTransmissionId String?
  sdiStatus         String? // 'PENDING' | 'SENT' | 'ACCEPTED' | 'REJECTED'

  issuedAt DateTime @default(now())

  // F1.4 — credit notes (note di credito) tied to this invoice.
  creditNotes CreditNote[]

  @@unique([workspaceId, issuer, fiscalYear, sequenceNumber], name: "issuer_fiscalYear_sequenceNumber", map: "FiscalInvoice_issuer_fiscalYear_sequenceNumber_key")
  @@index([invoiceNumber])
  @@index([issuedAt])
  @@index([sdiStatus])

  @@index([workspaceId])
}

// ── F1.4: Italian nota di credito (credit note) ──────────────────────
// DPR 633/72 Art. 26: when a sale is refunded (full or partial), the
// seller MUST issue a credit note that references the original
// invoice and submit it to SDI as TipoDocumento TD04. Without this
// the VAT remains owed to the state — the refund is fiscally invisible.
//
// Per-fiscal-year sequence is gap-free + monotonic, separate from the
// invoice counter (operator audit clarity). NC- prefix on the
// materialised number distinguishes credit notes from invoices in
// list views.
//
// Active for B2B orders (FatturaPA dispatch). B2C corrispettivi
// (telematic receipts) have a separate void/correction flow on the
// hardware register; we still track the credit note locally for
// fiscal audit even when SDI dispatch is not applicable.
model CreditNoteCounter {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  fiscalYear Int
  issuer     String   @default("XAVIA")
  current    Int      @default(0)
  updatedAt  DateTime @default(now()) @updatedAt

  @@id([fiscalYear, issuer])
  @@index([workspaceId])
}

model CreditNote {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  // One credit note per refund.
  refund   Refund @relation(fields: [refundId], references: [id], onDelete: Cascade)
  refundId String @unique

  // Reference to the original FiscalInvoice when one was issued.
  // NULL when the underlying order is B2C without an explicit invoice
  // (most common Xavia case — Amazon IT B2C corrispettivi-only).
  originalInvoice   FiscalInvoice? @relation(fields: [originalInvoiceId], references: [id], onDelete: SetNull)
  originalInvoiceId String?

  issuer           String @default("XAVIA")
  fiscalYear       Int
  sequenceNumber   Int
  // "NC-NNNNN/YYYY"
  creditNoteNumber String

  // Snapshot at issue time. Italian fiscal records are immutable
  // post-issue — never recompute from the live Refund.
  amountCents  Int
  currencyCode String @default("EUR")

  // Italian "Causale" shown on the PDF and submitted via SDI TD04.
  // e.g. "Resa merce — RMA-2026-0001"
  causale String?

  sdiTransmissionId String?
  sdiStatus         String? // 'PENDING' | 'SENT' | 'ACCEPTED' | 'REJECTED' | 'NOT_APPLICABLE'

  issuedAt DateTime @default(now())

  @@unique([workspaceId, issuer, fiscalYear, sequenceNumber], name: "issuer_fiscalYear_sequenceNumber", map: "CreditNote_issuer_fiscalYear_sequenceNumber_key")
  @@index([refundId])
  @@index([creditNoteNumber])
  @@index([issuedAt])
  @@index([sdiStatus])
  @@index([originalInvoiceId])

  @@index([workspaceId])
}

// ── AU.5: Per-order operator notes ───────────────────────────────────
// Distinct from CustomerNote (which persists across all the customer's
// orders). OrderNote is about THIS order: pack instructions, fraud
// review notes, buyer-messaged-about-gift-wrap memos, etc.
model OrderNote {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  order   Order  @relation(fields: [orderId], references: [id], onDelete: Cascade)
  orderId String

  body         String
  authorUserId String?
  authorEmail  String?
  pinned       Boolean @default(false)

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([orderId])
  @@index([createdAt])
  @@index([workspaceId])
}

// ── O.22: Per-order risk audit ───────────────────────────────────────
// One score per Order. Customer.riskFlag is the rolled-up worst flag
// across the customer's orders; this table is the breakdown an
// operator drills into when they want to know WHY a customer was
// flagged. Recompute = upsert on the (orderId) unique.
model OrderRiskScore {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  order   Order  @relation(fields: [orderId], references: [id], onDelete: Cascade)
  orderId String @unique

  // 0–100 cumulative
  score Int
  // Bucketed: LOW | MEDIUM | HIGH (LOW renders as no-badge in the UI;
  // MEDIUM amber, HIGH red).
  flag  String

  // Per-signal flags / counts. JSONB so adding a new signal in a
  // follow-up commit doesn't require a schema migration.
  signals Json

  // Operator-readable explanation, one entry per fired signal.
  reasons String[] @default([])

  computedAt DateTime @default(now())

  @@index([flag])
  @@index([score])
  @@index([computedAt])

  @@index([workspaceId])
}

model OrderItem {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  // Order Reference
  order   Order  @relation(fields: [orderId], references: [id], onDelete: Cascade)
  orderId String

  // Product Reference
  product   Product? @relation(fields: [productId], references: [id], onDelete: SetNull)
  productId String?

  // ── Phase 26: Unified Order Item ────────────────────────────────────
  sku      String
  quantity Int
  price    Decimal @db.Decimal(10, 2)

  // ── O.5: per-line idempotency key ──────────────────────────────────
  // Channel-side immutable line id (Amazon OrderItemId / eBay
  // lineItemId / Shopify line_items[].id). Lets channel ingestion
  // upsert by (orderId, externalLineItemId) on webhook redelivery
  // instead of delete-then-create, so OrderItem.id stays stable for
  // ReturnItem.orderItemId and any future FK reference. Nullable for
  // legacy rows + channels without a per-line id (WooCommerce today).
  // Standard Postgres NULL-distinct unique semantics let those rows
  // coexist without a partial index.
  externalLineItemId String?

  // F.1 — per-line Italian VAT rate (22 / 10 / 4). NULL = not
  // applicable (non-IT marketplace) or legacy. F.3 PDF + F.4 SDI
  // XML default to 22 on Italian orders when NULL.
  itVatRatePct Decimal? @db.Decimal(5, 2)

  // Metadata
  amazonMetadata Json?
  ebayMetadata   Json?
  createdAt      DateTime @default(now())
  updatedAt      DateTime @updatedAt

  @@unique([workspaceId, orderId, externalLineItemId], name: "orderId_externalLineItemId", map: "OrderItem_orderId_externalLineItemId_key")
  @@index([orderId])
  @@index([productId])
  @@index([sku])
  @@index([externalLineItemId])
  @@index([workspaceId])
}

// ── F.1: Daily Sales Aggregate ─────────────────────────────────────────────
// One row per (sku, channel, marketplace, day) — pre-aggregated demand
// signal that the replenishment algorithm reads from. Replaces live
// `OrderItem.groupBy` on the read path. Refreshed by a service that
// re-aggregates from OrderItem on a schedule + after every order write.
//
// Future SP-API report ingest (F.3) writes the same shape with `source`
// flipped to `AMAZON_REPORT` etc., overriding the OrderItem-derived
// numbers when reports land canonical figures (refunds, taxes, returns).
model DailySalesAggregate {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  // ── Identity ────────────────────────────────────────────────────
  sku         String
  // OrderChannel as a string (AMAZON/EBAY/SHOPIFY/...) so SP-API report
  // ingest paths can write here without depending on the enum.
  channel     String
  // Country code (IT/DE/...) for region-scoped channels, GLOBAL for
  // single-store channels (Shopify, Etsy, WooCommerce). Mirrors the
  // ChannelListing.marketplace convention.
  marketplace String
  // Day key (DATE, no time component). Postgres `DATE` storage.
  day         DateTime @db.Date

  // ── Core demand metrics (always populated) ──────────────────────
  unitsSold    Int     @default(0)
  // Sum of OrderItem.price * quantity in the order's currency. For
  // multi-currency setups, the currency is tracked per source channel;
  // analytics that compare across marketplaces should normalize separately.
  grossRevenue Decimal @default(0) @db.Decimal(14, 2)
  // Distinct order count contributing to this row (units / orders =
  // average basket size for this SKU on this day).
  ordersCount  Int     @default(0)

  // ── F.3: SP-API report fields (nullable until reports land) ────
  // Populated by Amazon Sales & Traffic report (sessions, buy-box %,
  // conversion). Left null for OrderItem-derived rows.
  sessions            Int?
  buyBoxPct           Decimal? @db.Decimal(5, 2)
  conversionRate      Decimal? @db.Decimal(5, 4)
  // True if the SKU was out of stock at any point during the day.
  // Critical for the forecaster — zero sales due to no stock should
  // not lower the demand baseline.
  isStockOut          Boolean  @default(false)
  // ASP (average selling price) for the day. Helps detect price
  // changes that explain demand shifts.
  averageSellingPrice Decimal? @db.Decimal(10, 2)

  // ── Provenance ──────────────────────────────────────────────────
  // ORDER_ITEM | AMAZON_REPORT | EBAY_REPORT | SHOPIFY_REPORT | MANUAL
  // The forecaster prefers report-sourced rows when available; the
  // refresh service won't overwrite a higher-priority source with a
  // lower-priority one (see refreshSalesAggregates docstring).
  source String @default("ORDER_ITEM")

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  // One row per identity tuple — upsert key. Source is intentionally
  // NOT in the unique because a SKU's day should resolve to a single
  // canonical aggregate; precedence is resolved at write time.
  @@unique([workspaceId, sku, channel, marketplace, day], name: "sku_channel_marketplace_day", map: "DailySalesAggregate_sku_channel_marketplace_day_key")
  @@index([sku, day])
  @@index([channel, marketplace, day])
  @@index([day])
  @@index([workspaceId])
}

// ── F.4: Replenishment forecast ────────────────────────────────────────────
// Per-(sku, channel, marketplace, day) demand prediction for the next 90
// days. Generated nightly by the forecast worker (Holt-Winters baseline +
// external signal multipliers). The replenishment endpoint sums the
// horizon window (today + leadTime + safetyDays) instead of doing live
// velocity math, which lets seasonality + retail events + weather
// elasticities flow through to the urgency calculation.
//
// Confidence bands (lower80 / upper80) come from Holt-Winters' built-in
// prediction intervals — UI shows "reorder 200 units (140-280 likely)"
// so the user understands when the model is uncertain.
model ReplenishmentForecast {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  // ── Identity ────────────────────────────────────────────────────
  sku         String
  channel     String
  marketplace String
  // The day this forecast targets (UTC, no time component).
  horizonDay  DateTime @db.Date

  // ── Forecast values ─────────────────────────────────────────────
  // Point forecast in units. Always >= 0 (clamped at the source).
  forecastUnits Decimal @db.Decimal(12, 2)
  // 80% prediction interval. Lower can be 0 (clamped); upper bounds the
  // headroom the user might want to hold for tail demand.
  lower80       Decimal @default(0) @db.Decimal(12, 2)
  upper80       Decimal @default(0) @db.Decimal(12, 2)

  // ── Provenance / signals ────────────────────────────────────────
  // Which model generated this row. Lets future versions of the worker
  // (e.g. LightGBM v2) coexist with v1 baselines and lets the UI tag
  // forecasts with their generation. 'HOLT_WINTERS_V1' for v0.
  model         String  @default("HOLT_WINTERS_V1")
  // Multiplicative factors that shaped the point forecast, kept for
  // transparency in the UI: { weather: 1.1, holiday: 1.5, retail: 2.0 }.
  // Default {} for forecasts with no external adjustment.
  signals       Json    @default("{}")
  // Free-form note; rows with sparse history get tagged 'COLD_START',
  // rows that fell back from Holt-Winters → trailing-mean get tagged
  // 'TRAILING_MEAN_FALLBACK', etc.
  generationTag String?

  // When this row was generated. Forecast workers always overwrite via
  // upsert — there's only ever one row per (sku, channel, marketplace,
  // horizonDay) regardless of how many times the worker has run.
  generatedAt DateTime @default(now())

  // R.16 — unique key includes model so champion + challenger can
  // both write rows for the same (sku, channel, marketplace, day).
  @@unique([workspaceId, sku, channel, marketplace, horizonDay, model], name: "sku_channel_marketplace_horizonDay_model", map: "ReplenishmentForecast_sku_channel_marketplace_horizon_5a855b66a")
  @@index([sku, horizonDay])
  @@index([channel, marketplace, horizonDay])
  @@index([horizonDay])
  @@index([workspaceId])
}

// ── R.16: Forecast model A/B / champion-challenger ─────────────────
// One row per (sku, model) assignment. Champion always present;
// challenger is optional rollout. The forecast generator reads this
// table and dual-writes ReplenishmentForecast rows when both
// cohorts are active. Accuracy infrastructure (R.1) already tracks
// `model` per row, so MAPE rolls up per (sku, model) naturally.
model ForecastModelAssignment {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id         String    @id @default(cuid())
  sku        String
  modelId    String // 'HOLT_WINTERS_V1' | 'PROPHET_V1' | etc.
  cohort     String // 'champion' | 'challenger' | 'control'
  assignedAt DateTime  @default(now())
  assignedBy String // 'cron' | 'manual' | 'rollout'
  expiresAt  DateTime?

  @@unique([workspaceId, sku, modelId], name: "sku_modelId", map: "ForecastModelAssignment_sku_modelId_key")
  @@index([modelId])
  @@index([cohort])
  @@index([sku])
  @@index([workspaceId])
}

// ── R.1: Forecast accuracy (MAPE) ─────────────────────────────────────────
// One row per (sku, channel, marketplace, day) where (a) we had a
// prediction in advance (forecast.generatedAt < day_start_UTC) and
// (b) the actual is now known (DailySalesAggregate exists for day).
// Populated by a daily cron at 04:00 UTC (after sales-ingest 02:00
// + forecast 03:30). Idempotent — re-runs UPSERT on the unique key.
//
// Why denormalize absoluteError + percentError + withinBand at insert:
// dashboards roll up MAPE / MAE / calibration over date ranges with
// AVG() — pre-computing those per row is much cheaper than re-deriving
// from forecastUnits + actualUnits each query.
//
// percentError is NULL when actualUnits=0 (MAPE is undefined). MAE
// rolls up from absoluteError which is always defined; MAPE rolls up
// from percentError WHERE NOT NULL. withinBand is independent of
// either error metric.
model ForecastAccuracy {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  // Identity (matches ReplenishmentForecast + DailySalesAggregate)
  sku         String
  channel     String
  marketplace String
  day         DateTime @db.Date

  // What we predicted (snapshot from ReplenishmentForecast)
  forecastUnits   Decimal  @db.Decimal(12, 2)
  forecastLower80 Decimal? @db.Decimal(12, 2)
  forecastUpper80 Decimal? @db.Decimal(12, 2)

  // What actually happened (from DailySalesAggregate.unitsSold)
  actualUnits Int

  // Pre-computed error metrics
  absoluteError Decimal  @db.Decimal(12, 2) // |forecast - actual|
  percentError  Decimal? @db.Decimal(7, 2) // NULL when actualUnits=0
  withinBand    Boolean

  // Provenance (snapshot from ReplenishmentForecast)
  modelRegime         String // COLD_START | TRAILING_MEAN_FALLBACK | HOLT_LINEAR | HOLT_WINTERS
  model               String
  forecastGeneratedAt DateTime
  evaluatedAt         DateTime @default(now())

  @@unique([workspaceId, sku, channel, marketplace, day], name: "sku_channel_marketplace_day", map: "ForecastAccuracy_sku_channel_marketplace_day_key")
  @@index([day])
  @@index([modelRegime])
  @@index([sku, day])
  @@index([workspaceId])
}

// ── F.4: Retail event calendar ──────────────────────────────────────────────
// Pre-known sales events that drive demand spikes (Prime Day, Black
// Friday, Italian saldi, EICMA, etc.). The forecast worker reads this
// table and applies expectedLift as a multiplicative factor on event
// days for the relevant scope (channel / marketplace / category).
//
// Seeded with a starter set in scripts/seed-retail-events.ts; sellers
// add to it as they hear about category-specific events. UI surfaces
// the next 3 events as banners on /fulfillment/replenishment with prep
// deadline = event_date - max(supplier_lead_times).
// ── F.6: Brand / company settings ─────────────────────────────────────────
// Single-row table for the seller's brand identity used on outbound
// artifacts: factory POs, packing slips, GTIN exemption letters, etc.
// Edited via /settings/company; rendered into PDF letterheads by the
// factory-po-pdf service. Seeded as a single empty row on first read so
// the GET endpoint never has to handle the missing-row case.
model BrandSettings {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  // ── Company identity ────────────────────────────────────────────
  companyName  String?
  // Multi-line address rendered on the letterhead. JSON array of strings.
  // ["Via Aurelia 123", "00165 Roma RM", "Italia"] for Xavia.
  addressLines String[] @default([])
  // VAT / partita IVA / tax ID — varies by jurisdiction; free-form.
  // Legacy free-text field kept for backwards-compat with anything
  // that already pulls from it. New Italian-specific fields below
  // are the canonical source for fiscal docs.
  taxId        String?
  // Public-facing contact info on the PO header.
  contactEmail String?
  contactPhone String?
  websiteUrl   String?

  // ── Phase D — Italian fiscal fields (B2B e-invoicing). ──────────
  // All nullable so non-IT operators don't need to populate them;
  // strict checksum validation lives in the API. P.IVA = 11 digits,
  // mod-11 Luhn-style. Codice Fiscale = 16 alphanumerics with a
  // checksum letter at position 16. SDI = 7 alphanumerics (no
  // checksum); pecEmail = certified email (PEC) used as the
  // alternative when no SDI code is provisioned. One of (sdiCode |
  // pecEmail) must be present for valid Italian B2B invoicing.
  piva          String?
  codiceFiscale String?
  sdiCode       String?
  pecEmail      String?
  // VAT regime selector. Drives downstream invoice math and the
  // /fulfillment/stock rimanenze valuation. Free-text would be
  // fragile here — we constrain to a known set.
  // Values: 'ORDINARIO' | 'FORFETTARIO' | 'OSS' | 'IOSS' | 'ESENTE'.
  vatScheme     String?

  // ── Letterhead assets ───────────────────────────────────────────
  // Cloudinary or other hosted URL — pdfkit downloads + embeds at
  // render time. ~600×200 transparent PNG works best at letter size.
  logoUrl String?

  // ── PDF defaults ────────────────────────────────────────────────
  // Free-form signature block, e.g. "Per: Awais Sulhry / Procurement".
  // Rendered above the signature line on factory POs.
  signatureBlockText String?
  // Default PO notes appended to every factory PO body. Sellers
  // override per-PO via the bulk-PO modal's notes field.
  defaultPoNotes     String?
  // Default sender line for emails to suppliers (display + email).
  // Future: when SES is wired this drives the From: header. v0
  // surfaces it for the user to copy into their mail client.
  factoryEmailFrom   String?

  // R.7 — approval workflow gate. False (default for Xavia) auto-
  // advances DRAFT → REVIEW → APPROVED on a single submit-for-review
  // call; true requires a separate human APPROVE action.
  requireApprovalForPo Boolean @default(false)

  // PO.1 — value-based approval ladder. When poApprovalThresholdCents
  // is null OR a PO's totalCents is at-or-below it, submit-for-review
  // auto-approves (matches the legacy requireApprovalForPo=false path).
  // When totalCents exceeds the threshold, the PO is routed to
  // poApprovalApproverEmail (notified out-of-band; UI surfaces in the
  // "Awaiting my approval" saved view in PO.14). Both null = ladder
  // disabled and only requireApprovalForPo gates the flow.
  poApprovalThresholdCents Int?
  poApprovalApproverEmail  String?

  // R.20 — operator-entered cash position in EUR cents. Powers the
  // 13-week cash-flow projection card on the replenishment page.
  // Null = card hidden + projection still computes without a starting
  // balance (useful for quick what-if).
  cashOnHandCents Int?

  // UFX GPSR.1 — hosted CE/PPE user-manual URLs per language, keyed by
  // UPPER language code ("EN", "DE", …) → public https URL (.pdf/.jpg).
  // Feeds Amazon compliance_media.source_location per marketplace
  // (buildAmazonComplianceMediaColumns). Null = no manuals hosted yet.
  userManualUrls Json?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt
  @@index([workspaceId])
}

model RetailEvent {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  // ── Identity ────────────────────────────────────────────────────
  name      String
  // Inclusive event window. Single-day events have startDate == endDate.
  startDate DateTime @db.Date
  endDate   DateTime @db.Date

  // ── Scope (any/all may be null = applies broadly) ───────────────
  // null => applies to every channel
  channel     String?
  // null => applies to every marketplace under the channel
  marketplace String?
  // null => applies to every product type
  productType String?

  // ── Multiplier ──────────────────────────────────────────────────
  // Expected demand lift on event days. 1.0 = no lift; 4.0 = 4x typical.
  // Conservative defaults: Prime Day 3.0, Black Friday 4.0, Cyber
  // Monday 2.5, Italian saldi 1.4, EICMA 1.3. Sellers tune from data.
  expectedLift Decimal @default(1) @db.Decimal(4, 2)

  // Lead-time-aware reminder offset. UI uses this to surface
  // "Black Friday in 47 days — last day to PO: Oct 13". Optional;
  // default 30d for events that don't specify.
  prepLeadTimeDays Int @default(30)

  // ── Metadata ────────────────────────────────────────────────────
  description String?
  source      String? // 'AMAZON_OFFICIAL', 'CUSTOM', 'INDUSTRY_CAL'
  isActive    Boolean @default(true)

  // G.5 — Optional price actions for this event. When present, the
  // scheduler materializes ChannelListing.salePrice for the event window
  // and clears it after.
  priceActions RetailEventPriceAction[]

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([startDate, endDate])
  @@index([channel, marketplace])
  @@index([isActive])
  @@index([workspaceId])
}

// ── G.1: Pricing snapshot ──────────────────────────────────────────────────
// Materialized output of pricing-engine.service.ts. One row per
// (sku, channel, marketplace, fulfillmentMethod) — sub-50ms reads even at
// 32K cells. Refreshed on price/cost/rule change, on FX update, and when
// scheduled promotions enter or exit a window.
model PricingSnapshot {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  sku               String
  channel           String
  marketplace       String
  // null => the listing's default fulfillment (used when no per-FBA/FBM
  // override exists). FBA/FBM rows materialize separately when an Offer
  // override is set.
  fulfillmentMethod String?

  // The resolved price + currency the engine arrived at.
  computedPrice Decimal @db.Decimal(12, 2)
  currency      String

  // Where the price came from in the resolver chain (see
  // pricing-engine.service.ts PriceSource enum).
  source String // SCHEDULED_SALE | OFFER_OVERRIDE | CHANNEL_OVERRIDE |
  // CHANNEL_RULE | PRICING_RULE | MASTER_INHERIT | FALLBACK

  // Full resolution breakdown for the UI drawer + audit + "what would
  // happen" simulator. JSON shape matches PriceResolution.breakdown.
  breakdown Json @default("{}")

  // Constraint clamping flag — true when the resolver had to floor or
  // ceiling-cap. Pre-clamp value preserved for debugging.
  isClamped   Boolean  @default(false)
  clampedFrom Decimal? @db.Decimal(12, 2)

  // Soft warnings the UI surfaces as cell badges ("FX stale", "MAP
  // violated", "cost not set", etc.). Non-blocking.
  warnings String[] @default([])

  computedAt DateTime @default(now())

  @@unique([workspaceId, sku, channel, marketplace, fulfillmentMethod], name: "sku_channel_marketplace_fulfillmentMethod", map: "PricingSnapshot_sku_channel_marketplace_fulfillmentMethod_key")
  @@index([sku])
  @@index([channel, marketplace])
  @@index([source])
  @@index([computedAt])
  @@index([workspaceId])
}

// ── PH.1: Unified price-change timeline ──────────────────────────────────
// One append-only row per price change, written from every source that
// mutates a live price: bulk/manual override, repricer live-apply,
// promotion enter/exit. Distinct from RepricingDecision (rule-eval audit,
// keyed by ruleId) and ChannelListingOverride (override-field audit, keyed
// by channelListingId): this is the single coordinate-keyed feed the
// /pricing drawer reads to answer "why did this price change, and what was
// it before?". Best-effort writes — history must never break the price
// write that triggered it.
model PriceChangeEvent {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id        String  @id @default(cuid())
  product   Product @relation(fields: [productId], references: [id], onDelete: Cascade)
  productId String
  sku       String // denormalized for fast per-SKU timeline reads

  channel           String // AMAZON | EBAY | SHOPIFY
  marketplace       String // IT | DE | FR | …
  fulfillmentMethod String? // FBA | FBM | null when not method-specific

  // Stored as Decimal so the timeline reads back numerically. oldPrice is
  // null when no prior price is known; newPrice is null on CLEAR (price
  // reverts to inherited/master).
  oldPrice Decimal? @db.Decimal(12, 2)
  newPrice Decimal? @db.Decimal(12, 2)
  currency String   @default("EUR")

  source PriceChangeSource
  reason String // human-readable: 'bulk-override SET_FIXED 89.99', 'matched buy box at €89.99', 'promo "Black Friday" started'
  ruleId String? // links to the RepricingRule when source=REPRICER
  actor  String? // 'bulk-override' | 'repricer' | 'promo-scheduler' | userId

  changedAt DateTime @default(now())

  @@index([productId, channel, marketplace, changedAt])
  @@index([sku, changedAt])
  @@index([changedAt])
  @@index([workspaceId])
}

enum PriceChangeSource {
  MANUAL_OVERRIDE
  BULK_OVERRIDE
  REPRICER
  PROMO_START
  PROMO_END
  CHANNEL_RULE
  MASTER_INHERIT
  FX
}

// ── Pricing F.1: Buy Box observation log ─────────────────────────────────
// Per-marketplace, per-product timeseries written by sp-api-pricing.service
// on each daily competitive-pricing refresh. One row = one
// getItemOffersBatch observation for one ASIN. Powers win-rate trends,
// repricer feedback ("did we win the box after that price cut?"), and
// competitor-identity tracking.
//
// Product.buyBoxPrice continues to hold the most-recent snapshot for fast
// "current state" reads (no aggregate scan); this table is additive
// history. We don't truncate aggressively — observations are one row per
// ASIN per day per marketplace, ~3.2K × 9 markets × 1/day ≈ 28K rows/day,
// 10M/year. Size is fine for Postgres; future trim policy can drop rows
// >12 months once the win-rate-trend window stabilizes.
model BuyBoxHistory {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String   @id @default(cuid())
  product     Product  @relation(fields: [productId], references: [id], onDelete: Cascade)
  productId   String
  channel     String // 'AMAZON' (only channel with a Buy Box concept today)
  marketplace String // 'IT' | 'DE' | 'UK' | ...
  observedAt  DateTime @default(now())

  // Capture both the Buy Box price (the offer Amazon featured) and the
  // lowest price across all offers — they often diverge.
  buyBoxPrice           Decimal? @db.Decimal(10, 2)
  lowestCompetitorPrice Decimal? @db.Decimal(10, 2)

  // True when this observation showed our seller account holding the box.
  // Win-rate = count(*) FILTER (WHERE isOurOffer = true) / count(*).
  isOurOffer        Boolean @default(false)
  winnerSellerId    String? // SP-API SellerId; null when un-exposed
  fulfillmentMethod String? // 'FBA' | 'FBM' from the winning offer

  // CE.3 — margin at the time of this observation.
  // (buyBoxPrice - costPrice) / buyBoxPrice. Null when costPrice unknown.
  // Used by MAXIMIZE_MARGIN_WIN_BOX to compute the highest price at which
  // we historically won the box with acceptable margin.
  marginAtObservation Decimal? @db.Decimal(8, 4)

  @@index([productId, observedAt])
  @@index([channel, marketplace, observedAt])
  @@index([isOurOffer, observedAt])
  @@index([workspaceId])
}

// ── G.2: FX rate cache ─────────────────────────────────────────────────────
// Daily snapshot from frankfurter.app (ECB-backed, free, no auth).
// Engine uses 24h cache; falls back to most-recent rate when fetch fails.
// `source = 'manual'` rows let the seller override (e.g. lock UK at a fixed
// rate while EUR/GBP shifts).
model FxRate {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id           String   @id @default(cuid())
  fromCurrency String // 'EUR'
  toCurrency   String // 'GBP'
  rate         Decimal  @db.Decimal(14, 8)
  asOf         DateTime @db.Date
  source       String   @default("frankfurter") // 'frankfurter' | 'manual'

  createdAt DateTime @default(now())

  @@unique([workspaceId, fromCurrency, toCurrency, asOf], name: "fromCurrency_toCurrency_asOf", map: "FxRate_fromCurrency_toCurrency_asOf_key")
  @@index([asOf])
  @@index([workspaceId])
}

// ── G.5: Retail event price action ─────────────────────────────────────────
// Links a RetailEvent to a price action (PERCENT_OFF / FIXED_PRICE) scoped
// to (channel, marketplace, productType). Scheduler applies the action to
// every matching ChannelListing.salePrice for the event window. Engine
// reads salePrice as source = SCHEDULED_SALE.
model RetailEventPriceAction {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id      String      @id @default(cuid())
  eventId String
  event   RetailEvent @relation(fields: [eventId], references: [id], onDelete: Cascade)

  // Scope filters — null on any field => applies broadly.
  channel     String?
  marketplace String?
  productType String?

  // PERCENT_OFF: salePrice = currentPrice × (1 − value/100)
  // FIXED_PRICE: salePrice = value (in marketplace currency)
  action String // 'PERCENT_OFF' | 'FIXED_PRICE'
  value  Decimal @db.Decimal(10, 2)

  isActive Boolean @default(true)

  // Timestamps the scheduler stamps onto affected ChannelListings as
  // salePrice activation / expiry windows. Defaults to event window
  // when null.
  setSalePriceFrom  DateTime?
  setSalePriceUntil DateTime?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([eventId])
  @@index([isActive])
  @@index([workspaceId])
}

/// Phase 6.B — Amazon SP-API settlement reports.
///
/// Bank-reconciliation surface. Where FinancialTransaction captures the
/// per-event ledger (one row per fee/refund/order event from
/// listFinancialEvents), SettlementReport captures Amazon's bank-side
/// aggregation — one row per (marketplace, settlement period) with the
/// deposit total.
///
/// Reports are auto-published by Amazon every ~7-14 days per marketplace.
/// The ingester (amazon-settlements.service.ts) calls GET /reports/...
/// to LIST already-published reports (no createReport needed), downloads
/// each via getReportDocument, and upserts a summary row.
///
/// The full tab-separated body is preserved in `rawBody` so a future
/// per-line reconciliation feature can parse it without re-fetching.
/// Splitting into a SettlementLine table is deferred until that ships.
///
/// reportId is globally unique on Amazon's side, so the unique index
/// gives idempotent upsert semantics: re-running the sync on the same
/// window is a no-op.
model SettlementReport {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  // SP-API identifiers
  reportId   String
  documentId String?
  reportType String  @default("GET_V2_SETTLEMENT_REPORT_DATA_FLAT_FILE_V2")

  // Marketplace scope (the SP-API marketplaceId, e.g. APJ6JRA9NG5V4)
  marketplaceId String

  // Settlement window (from the report header)
  startDate DateTime
  endDate   DateTime

  // Bank-side totals (from the summary row)
  depositDate      DateTime?
  totalAmount      Decimal   @default(0) @db.Decimal(14, 2)
  currencyCode     String    @default("EUR")
  transactionCount Int       @default(0)

  // Raw flat-file body — tab-separated. NULL when ingester runs in
  // "summary-only" mode. Postgres TEXT has no length cap so multi-MB
  // monthly settlements fit fine.
  rawBody String?

  // Tracking + operator notes
  fetchedAt      DateTime @default(now())
  status         String   @default("INGESTED") // INGESTED | RECONCILED | EXCEPTION
  reconcileNotes String?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([marketplaceId, startDate])
  @@index([depositDate])
  @@unique([workspaceId, reportId], name: "workspace_reportId", map: "SettlementReport_workspace_reportId_key")
  @@index([workspaceId])
}

model FinancialTransaction {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  // Channel-specific Transaction IDs
  amazonTransactionId String? // Nullable for non-Amazon transactions
  ebayTransactionId   String? // eBay transaction ID

  // Order Reference
  order   Order  @relation(fields: [orderId], references: [id], onDelete: Cascade)
  orderId String

  // Transaction Details
  transactionType String // "Order", "Refund", "FBA_Fee", "Shipping_Fee", "Tax", "Adjustment", "eBay_Fee", "PayPal_Fee"
  transactionDate DateTime

  // Financial Amounts
  amount       Decimal @db.Decimal(12, 2)
  currencyCode String  @default("USD")

  // Fee Breakdown
  amazonFee          Decimal @default(0) @db.Decimal(10, 2)
  fbaFee             Decimal @default(0) @db.Decimal(10, 2)
  paymentServicesFee Decimal @default(0) @db.Decimal(10, 2)
  ebayFee            Decimal @default(0) @db.Decimal(10, 2) // eBay final value fee
  paypalFee          Decimal @default(0) @db.Decimal(10, 2) // PayPal transaction fee
  otherFees          Decimal @default(0) @db.Decimal(10, 2)

  // Net Revenue Calculation
  grossRevenue Decimal @db.Decimal(12, 2)
  netRevenue   Decimal @db.Decimal(12, 2)

  // Status
  status String // "Pending", "Completed", "Reversed"

  // Metadata
  amazonMetadata Json?
  createdAt      DateTime @default(now())
  updatedAt      DateTime @updatedAt

  @@index([orderId])
  @@index([transactionType])
  @@index([transactionDate])
  @@index([status])
  @@index([workspaceId])
}

model ChannelConnection {
  ingressRoute ChannelAccountRoute?
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  workspace Workspace @relation(fields: [workspaceId], references: [id], onDelete: Restrict)
  @@index([workspaceId, channelType])
  id String @id @default(cuid())

  // ── Channel ────────────────────────────────────────────────────
  // channelType: "AMAZON", "EBAY", "SHOPIFY", "WOOCOMMERCE", "ETSY"
  // marketplace: per-marketplace scope when applicable (e.g. "IT",
  //   "DE", "GLOBAL", null). eBay grants are multi-marketplace under
  //   a single token, so eBay rows have marketplace=null. Amazon
  //   per-region OAuth (P2-2) will populate marketplace.
  // managedBy: "oauth" | "env" | "pending"
  //   - oauth   = real OAuth grant; tokens populated below
  //   - env     = synthesised from process.env (Amazon today)
  //   - pending = adapter not yet shipped
  channelType String
  marketplace String?
  managedBy   String  @default("oauth")

  // ── Generic credentials ────────────────────────────────────────
  // Used by all connectors going forward. Legacy ebay* columns
  // below are dual-written for one release while callers migrate.
  accessToken    String?
  refreshToken   String?
  tokenExpiresAt DateTime?
  displayName    String? // seller signin / shop name / store handle

  // ── Legacy eBay-specific columns (DEPRECATED) ──────────────────
  // Kept for one release while ebay-auth.service.ts dual-writes to
  // both legacy and generic columns. A follow-up migration will drop
  // these once all callers read generic-only.
  ebayAccessToken    String?
  ebayRefreshToken   String?
  ebayTokenExpiresAt DateTime?
  ebayDevId          String?
  ebayAppId          String?
  ebaySignInName     String?
  ebayStoreName      String?
  ebayStoreFrontUrl  String?

  // ── Connection status ──────────────────────────────────────────
  isActive       Boolean   @default(false)
  lastSyncAt     DateTime?
  lastSyncStatus String? // "SUCCESS", "FAILED", "PARTIAL"
  lastSyncError  String?

  // ── MAP.2a — account identity ───────────────────────────────────
  // accountLabel/accountColor are the operator's own name and colour for this
  // account; they exist because neither channel gives us a usable one. eBay's
  // OAuth scope returns no identity (ebay-auth.service.ts:451 writes the literal
  // "eBay seller (verified)") and Amazon's displayName is the raw merchant id.
  accountLabel      String?
  accountColor      String?
  // Exactly one primary per channelType, enforced by a partial unique index.
  isPrimary         Boolean @default(false)
  sortOrder         Int     @default(0)
  // The account's identity AT the marketplace — Amazon merchant id, eBay sign-in
  // name, Shopify shop domain. Load-bearing: the partial unique index
  // `ChannelConnection_active_account_key` keys on it, so two accounts we cannot
  // tell apart cannot both be active. NULL until MAP.4 adds eBay's identity scope.
  externalAccountId String?

  connectionMetadata Json?
  createdAt          DateTime @default(now())
  updatedAt          DateTime @updatedAt

  // ── CX.1 — connection core (docs/2026-08-29-cx1-connection-core.md §1.1) ──
  // authStatus: connected | degraded | needs_reauth | revoked | disconnected | unknown
  authStatus            String    @default("unknown")
  region                String?
  // THE credential blob: envelope-encrypted (v2 = KMS-wrapped data key, v1 = env key).
  // Decrypted only by services/cx/token.service.ts. The plaintext columns above are
  // nulled by the cx1-credentials-backfill job once this is populated.
  credentialsEnc        String?
  credentialsKeyId      String?
  grantedScopes         String[]  @default([])
  accessTokenExpiresAt  DateTime?
  refreshTokenExpiresAt DateTime?
  // The four honest timestamps — never conflated into one "last sync".
  lastRefreshAt         DateTime?
  lastHeartbeatAt       DateTime?
  lastInboundAt         DateTime?
  lastOutboundAt        DateTime?
  lastErrorAt           DateTime?
  lastError             String?
  consecutiveFailures   Int       @default(0)
  // Distributed refresh lease (pgbouncer-safe; no advisory lock across HTTP).
  refreshLeaseUntil     DateTime?
  refreshLeaseOwner     String?
  // { userId, username, storeName?, storeUrl?, sellerId?, shopDomain? }
  identity              Json?
  apiVersion            String?

  scopes ConnectionScope[]
  events ConnectionEvent[]

  variantListings          VariantChannelListing[]
  // MAP.2a — attribution. ON DELETE SET NULL on every one of these: deleting a
  // connection must never delete listings or orders (contrast variantListings
  // above, which cascades). Disconnecting loses attribution, not history.
  channelListings          ChannelListing[]
  listingAliases           ProductListingAlias[] // PES.5
  sharedListingMemberships SharedListingMembership[]
  orders                   Order[]
  syncChannelPolicies      SyncChannelPolicy[]
  // C.14 — eBay Promoted Listings campaigns scoped to this OAuth
  // connection. Cascade so revoking a connection sweeps its
  // campaigns (operationally, eBay also disables them server-side).
  ebayCampaigns            EbayCampaign[]

  // The partial unique index `ChannelConnection_channelType_marketplace_active_key`
  // (CREATE UNIQUE INDEX ... WHERE "isActive" = true) is enforced at
  // the DB level in 20260506_h2_unify_channel_connection. Prisma's
  // schema language can't express partial unique indexes, so it lives
  // in raw SQL only. The drift gate accepts this because it doesn't
  // verify indexes — only CREATE TABLE presence per model.
  @@index([channelType])
  @@index([isActive])
  @@index([managedBy])
  @@index([authStatus])
  @@index([accessTokenExpiresAt])
  @@index([refreshTokenExpiresAt])

}

// ── CX.1 — one grant, many scopes (marketplaces / shops / profiles / storefronts) ──
// An SP-API grant covers a whole region (11 EU marketplaces on prod), an Ads grant
// covers N profiles, a TikTok auth N shops, a Kaufland key 9 storefronts. CASCADE:
// a scope has no meaning without its grant (contrast listings/orders, SET NULL).
model ConnectionScope {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id           String            @id @default(cuid())
  connectionId String
  connection   ChannelConnection @relation(fields: [connectionId], references: [id], onDelete: Cascade)
  // marketplace | shop | profile | storefront
  kind         String
  externalId   String
  label        String?
  region       String?
  isActive     Boolean           @default(true)
  metadata     Json?
  createdAt    DateTime          @default(now())
  updatedAt    DateTime          @updatedAt

  @@unique([workspaceId, connectionId, kind, externalId], name: "connectionId_kind_externalId", map: "ConnectionScope_connectionId_kind_externalId_key")
  @@index([kind, externalId])
  @@index([workspaceId])
}

// ── CX.1 — OUR app credentials per channel × environment ───────────────────────
// Never copied into connection rows (the Ads secret was duplicated into 9 rows
// before CX.1). Seeded once from env at boot; the row wins once it exists.
model ChannelApp {
  id              String    @id @default(cuid())
  // EBAY | AMAZON_SP | AMAZON_ADS | SHOPIFY | ETSY | …
  channelKey      String
  // production | sandbox
  environment     String    @default("production")
  clientId        String
  clientSecretEnc String?
  redirectUris    String[]  @default([])
  // eBay RuName, Etsy keystring, SP-API application id …
  extra           Json?
  // eBay Key Management signing key (private key + JWE), envelope-encrypted.
  signingKeyEnc   String?
  signingKeyId    String?
  secretExpiresAt DateTime?
  rotatedAt       DateTime?
  createdAt       DateTime  @default(now())
  updatedAt       DateTime  @updatedAt

  @@unique([channelKey, environment])
}

// ── CX.1 — one OAuth attempt, keyed by the `state` we send to the channel ──────
// Single use (consumedAt), 10-minute TTL, bound to the starting user and to a
// double-submit cookie nonce; holds the PKCE verifier server-side.
model OAuthSession {
  workspaceId String?
  environment String @default("production")
  @@index([workspaceId])
  id                 String    @id
  channelKey         String
  // connect | reconnect | adopt
  intent             String
  targetConnectionId String?
  startedByUserId    String?
  codeVerifier       String?
  redirectUri        String
  cookieNonce        String
  region             String?
  expiresAt          DateTime
  consumedAt         DateTime?
  resultConnectionId String?
  error              String?
  createdAt          DateTime  @default(now())

  @@index([expiresAt])
}

// ── CX.1 — the ledger: every grant, refresh, revoke, heartbeat, status change ──
// `detail` never carries token material (the writer redacts). Archive-never-delete
// (decision 9): rows older than 90 days keep their row, detail moves to the archive.
model ConnectionEvent {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id           String             @id @default(cuid())
  connectionId String?
  connection   ChannelConnection? @relation(fields: [connectionId], references: [id], onDelete: SetNull)
  channelKey   String
  // grant | reconsent | adopt | refresh | refresh_failed | revoke | disconnect |
  // heartbeat_ok | heartbeat_failed | scope_drift | status_change | secret_rotated |
  // signing_key_created | kms_fallback
  type         String
  actorUserId  String?
  detail       Json?
  archivedRef  String?
  createdAt    DateTime           @default(now())

  @@index([connectionId, createdAt])
  @@index([type, createdAt])
  @@index([workspaceId])
}

model OutboundSyncQueue {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  // ── PHASE 9: Support both Product and ChannelListing changes ────
  // At least one must be set
  productId String?
  product   Product? @relation(fields: [productId], references: [id], onDelete: Cascade)

  channelListingId String?
  channelListing   ChannelListing? @relation(fields: [channelListingId], references: [id], onDelete: Cascade)

  offerId String?
  // Note: Offer doesn't have direct relation; tracked via channelListingId

  // ── Target channel ─────────────────────────────────────────────
  targetChannel SyncChannel @default(AMAZON)
  targetRegion  String? // e.g., "US", "DE" (for regional syncs)

  // ── Sync status ────────────────────────────────────────────────
  syncStatus OutboundSyncStatus @default(PENDING)

  // ── Payload (what to sync) ─────────────────────────────────────
  payload Json // { "price": 99.99, "quantity": 50, "title": "...", "offers": [...] }

  // ── Error tracking ─────────────────────────────────────────────
  errorMessage String?
  errorCode    String?
  retryCount   Int     @default(0)
  maxRetries   Int     @default(3)

  // ── Timestamps ─────────────────────────────────────────────────
  createdAt   DateTime  @default(now())
  updatedAt   DateTime  @updatedAt
  syncedAt    DateTime? // When successfully synced
  nextRetryAt DateTime? // When to retry if failed

  // ── PHASE 12a: Grace Period (Undo Sync) ─────────────────────────
  // If set, Autopilot will not process this item until holdUntil <= NOW()
  // Allows 5-minute window to cancel syncs before they go live
  holdUntil DateTime? // Hold sync until this time (grace period)

  // ── Metadata ───────────────────────────────────────────────────
  syncType          String // "PRICE_UPDATE", "QUANTITY_UPDATE", "LISTING_SYNC", "OFFER_SYNC", "FULL_SYNC"
  externalListingId String? // Amazon ASIN or eBay ItemID

  // ── P3.2 — Dead-letter queue ────────────────────────────────────
  // Set to true when retryCount >= maxRetries and the job is FAILED.
  // These jobs are surfaced in the Dead Letters tab and require manual re-enqueue.
  isDead Boolean   @default(false)
  diedAt DateTime?

  @@index([productId])
  @@index([channelListingId])
  @@index([syncStatus])
  @@index([targetChannel])
  @@index([nextRetryAt])
  @@index([isDead, targetChannel])
  @@index([workspaceId])
}

// ── Phase 5: Bulk Operations Audit Log ───────────────────────────────
// Records every PATCH /api/products/bulk request for traceability.
// userId left nullable until auth is wired; populated as null for now.
model BulkOperation {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id           String  @id @default(cuid())
  userId       String?
  productCount Int
  changeCount  Int
  changes      Json // [{ id, field, oldValue, newValue }]
  status       String // SUCCESS | PARTIAL | FAILED | PENDING_APPLY
  errors       Json? // [{ id, field, error }]

  // ── Phase D.3: Cascade audit ─────────────────────────────────────
  // How many cascade fan-outs this operation triggered (0 if no
  // cascade flags were set in the request).
  cascadeCount     Int      @default(0)
  // Product IDs of every child that was updated as a cascade target.
  // Useful for "undo" — replay these in reverse.
  affectedChildren String[] @default([])

  // ── Phase D.4: CSV/XLSX upload preview state ────────────────────
  // status='PENDING_APPLY' rows hold a parsed-and-validated upload
  // waiting on user confirmation; expiresAt clears stale rows.
  expiresAt      DateTime?
  completedAt    DateTime?
  uploadFilename String?
  /**
   * D15.15 — import preview/apply progress. Nullable because every existing
   * BulkOperation predates them; a null means "this operation never reported
   * progress", which is not the same as zero.
   */
  processed Int?
  total     Int?

  /**
   * P10 / PES.5 — the `expectedVersion` the REQUEST carried, or null when it
   * carried none. Nullable for the same reason as `processed` above: every
   * existing row predates the column, and a null means "this operation did not
   * record a token", which is NOT the same as "the write was unguarded" for
   * rows written before this shipped.
   *
   * Why it exists: the AIREON incident (2026-09-02). A probe sent what it
   * believed was a stale token, the route could not parse it, no CAS statement
   * was built, and the write landed unrefused — and NOTHING in the audit row
   * could say so afterwards, because `changes` holds only the per-cell array.
   * With this column an audit row can answer "was this write version-guarded",
   * which is the question the incident could not answer about itself.
   */
  expectedVersion Int?

  createdAt DateTime @default(now())

  @@index([createdAt])
  @@index([userId])
  @@index([status])
  @@index([status, expiresAt])
  @@index([workspaceId])
}

// ── T.6: Bulk-ops templates ──────────────────────────────────────────
// Server-side replacement for the localStorage saved-views the bulk-
// ops grid used to ship with. Stores the full state needed to rebuild
// the grid: visible columns, filter dimensions, enabled channels, and
// enabled productTypes. Shared across the workspace today (no userId
// scoping yet) so teammates can share grid configurations; userId
// reserved for a future per-user / per-workspace scope.
model BulkOpsTemplate {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String  @id @default(cuid())
  name        String
  description String?
  /**
   * Reserved — null today (workspace-shared). When set, scopes the
   * template to a specific user. Indexed so per-user lookups stay
   * cheap when scoping lands.
   */
  userId      String?

  /**
   * Column ids to render, in display order. Mirrors the existing
   * saved-views shape.
   */
  columnIds String[]

  /**
   * FilterState shape from apps/web/.../bulk-operations/lib/types.ts:
   * status[], channels[], stockLevel, productTypes[], parentage,
   * hasAsin, hasGtin, missingRequired. Stored as JSONB so the shape
   * can evolve without migrations.
   */
  filterState Json?

  /**
   * Channel + productType filters that drive the column registry —
   * separate from filterState because they affect WHICH fields are
   * fetched, not WHICH rows are visible.
   */
  enabledChannels     String[] @default([])
  enabledProductTypes String[] @default([])

  /**
   * W.10 — group keys collapsed in the band when the user saved the
   * template. Restored on load so the user's preferred density
   * survives.
   */
  collapsedGroups String[] @default([])

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([userId])
  @@index([updatedAt])
  @@index([workspaceId])
}

// ── W5 / Wave-5: Reusable bulk-action templates ─────────────────────
//
// Distinct from BulkOpsTemplate (which captures a grid VIEW: columns,
// filters, sort). BulkActionTemplate captures a bulk OPERATION the
// operator wants to re-run with one click — "+5% pricing on Amazon
// IT", "translate to Italian", "end-of-life clearance status flip".
//
// Parameters give a single template multi-use legs: instead of saving
// one row per discount tier, the template carries `{value: number,
// channel: string}` placeholders the apply UI fills in at run time.
//
// `isBuiltin=true` flags seeded templates that ship with the product
// (W5.4 seeds 10–20 of these). Operators can't delete builtins, but
// they CAN duplicate one and edit the copy.
//
// usageCount + lastUsedAt let the library sort by "most used" so
// operator's go-to templates float to the top of the list. Updated
// transactionally when the apply path fires.
model BulkActionTemplate {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  name        String
  description String?

  /**
   * One of BulkActionType (PRICING_UPDATE / INVENTORY_UPDATE / …)
   * — see KNOWN_BULK_ACTION_TYPES in bulk-action.service.ts. Stored
   * as String for the same reason BulkActionJob.actionType is — keeps
   * the union extensible without a migration.
   */
  actionType String

  /**
   * ISO channel code ('AMAZON' / 'EBAY' / null = all).
   */
  channel String?

  /**
   * The default actionPayload (what BulkActionService.createJob
   * receives). Parameter placeholders use the form `${name}` inside
   * string values — the apply path interpolates them via parameters[].
   * Example for PRICING_UPDATE:
   * { adjustmentType: 'PERCENT', value: '${pct}' }
   */
  actionPayload Json @default("{}")

  /**
   * Default scope filters (matches CreateBulkJobSchema.filters).
   * Operators override these per-apply via the modal scope picker.
   */
  defaultFilters Json?

  /**
   * Parameter declarations. Shape:
   * [{ name: 'pct', label: 'Discount %', type: 'number',
   * defaultValue: 5, required: true, min: 0, max: 50 }]
   * The apply UI renders one input per declaration and substitutes
   * the typed value into actionPayload before POSTing.
   */
  parameters Json @default("[]")

  /**
   * Free-form category ('pricing' / 'inventory' / 'translation' /
   * 'cleanup' / …). Drives the library grouping. Empty = uncategorized.
   */
  category String?

  /**
   * Operator who owns the template. Null = workspace-shared (same
   * convention as BulkOpsTemplate.userId). Builtin templates carry
   * userId='__builtin' so the unique index isn't violated by multiple
   * seed entries.
   */
  userId String?

  /**
   * Built-in flag. Operators can't delete or edit these directly —
   * the UI offers "Duplicate" instead. W5.4 seeds 10-20 templates
   * for common Xavia / Amazon / eBay flows.
   */
  isBuiltin Boolean @default(false)

  /**
   * Telemetry — incremented in a transaction when the apply path
   * fires. Used to surface most-used templates at the top of the
   * library and to spot dead seeds in production.
   */
  usageCount Int       @default(0)
  lastUsedAt DateTime?

  createdBy String?
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([userId])
  @@index([category])
  @@index([actionType])
  @@index([usageCount(sort: Desc)])
  @@index([workspaceId])
}

// ── W6 / Wave-6: Scheduled bulk actions ───────────────────────────
//
// Operators want to fire bulk operations at a future time, or on a
// recurring cadence (every Monday 02:00, daily at 06:30, end of every
// month). The data shape mirrors a unix cron entry plus enough state
// to make pause / resume + manual-run + audit cheap.
//
// One-time vs recurring:
//   - cronExpression null + scheduledFor set → one-time, fires once
//   - cronExpression set + scheduledFor null → recurring, scheduler
//     computes the next nextRunAt after each fire
//   - both set → recurring, but won't start firing until scheduledFor
//
// `nextRunAt` is the canonical "when do I run next" timestamp the
// minute-tick cron scans against. Setting it to null pauses the
// schedule; the resume path recomputes from cronExpression.
//
// Each fire creates a real BulkActionJob row via BulkActionService
// .createJob; the link in `lastJobId` lets the schedule UI show what
// the most recent run produced.
model ScheduledBulkAction {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  name        String
  description String?

  /**
   * BulkActionType — see KNOWN_BULK_ACTION_TYPES. Stored as String
   * for the same extensibility reason as BulkActionJob.
   */
  actionType String

  /**
   * ISO channel code, null = all. Same shape as BulkActionJob.
   */
  channel String?

  /**
   * Job payload. Same shape as BulkActionJob.actionPayload. May
   * carry parameter placeholders if the schedule was created from a
   * BulkActionTemplate — substitution happens once at create time,
   * not per-fire.
   */
  actionPayload Json @default("{}")

  /**
   * Either explicit target IDs OR filters (mutually exclusive at
   * the API boundary, both fields here for shape compatibility
   * with BulkActionJob).
   */
  targetProductIds   String[] @default([])
  targetVariationIds String[] @default([])
  filters            Json?

  /**
   * One-time scheduled time. Null when this schedule is purely
   * recurring (cronExpression set). When both are set, the
   * scheduler waits until scheduledFor before honoring the cron.
   */
  scheduledFor DateTime?

  /**
   * Standard 5-field cron expression ('0 2 * * *' = 02:00 daily).
   * Null = one-time only. The scheduler uses cron-parser to compute
   * nextRunAt; invalid expressions are rejected at create time.
   */
  cronExpression String?

  /**
   * IANA timezone for cron evaluation ('Europe/Rome' default since
   * Awa is in CEST). Stored explicitly so a schedule survives a
   * server timezone change.
   */
  timezone String @default("Europe/Rome")

  /**
   * The next time the scheduler should fire this entry. Null = paused
   * (operator paused, or recurring schedule has no future runs left).
   * Indexed alongside enabled so the minute-tick scan is just a range
   * lookup, not a full table scan.
   */
  nextRunAt DateTime?

  /**
   * Toggle the operator flips to pause / resume. When false, the
   * scheduler skips this row even if nextRunAt is in the past.
   */
  enabled Boolean @default(true)

  /**
   * Audit + UX: every fire bumps these.
   */
  lastRunAt  DateTime?
  lastJobId  String?
  /**
   * Last-fire status: 'SUCCESS' | 'FAILED' | 'SKIPPED'
   */
  lastStatus String?
  lastError  String?
  runCount   Int       @default(0)

  /**
   * Optional link back to the BulkActionTemplate the operator
   * scheduled. Lets the UI show "from template: Spring sale" and
   * keeps the audit trail when a template gets duplicated.
   */
  templateId String?

  createdBy String?
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([enabled, nextRunAt])
  @@index([actionType])
  @@index([templateId])
  @@index([workspaceId])
}

// ── W7.7 / Wave-7: Approval gates for bulk-ops automation ──────────
//
// When a rule's actions exceed an operator-defined blast radius,
// the engine doesn't fire them — it parks the run in a queue with
// state='PENDING' and the operator either Approves (engine resumes
// the action) or Rejects (engine logs + drops). Distinct from
// AutomationRuleExecution (the audit trail of completed runs)
// because pending approvals need their own indexing + lifecycle.
//
// `threshold` captures WHY the gate fired — 'value' for the
// maxValueCentsEur cap, 'manual' for rules explicitly flagged
// requireApproval=true, 'safety' for hard-coded blast-radius
// guards (e.g. pause_schedules_matching with confirmAll=true).
//
// `expiresAt` lets operators ignore stale pending approvals — if a
// rule's threshold was breached six hours ago, firing the action
// now is probably the wrong move. The W7.7 worker auto-expires
// pending rows past their expiry.
model BulkAutomationApproval {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  /**
   * The rule that requested approval. No FK so deleting a rule
   * doesn't lose the audit trail of past pending approvals.
   */
  ruleId   String
  /**
   * Snapshot of the rule's name at request time — survives a rule
   * rename or delete so the queue UI can still show what it was.
   */
  ruleName String

  /**
   * Snapshot of the trigger payload + the action plan the engine
   * was about to execute. Approving replays this exactly.
   */
  triggerPayload Json
  actionPlan     Json

  /**
   * Why this approval was required:
   * 'value'   exceeded rule.maxValueCentsEur
   * 'manual'  rule explicitly carries requireApproval=true
   * 'safety'  hard-coded blast-radius guard fired
   */
  threshold String

  /**
   * Estimated EUR-cents value of the actions being approved.
   * Drives the operator's read-the-room: "this would spend €1,200"
   * vs "this would publish 47 listings". Null when N/A.
   */
  estimatedValueCentsEur Int?

  /**
   * State machine:
   * PENDING                         (created)
   * APPROVED  → action fired        (operator clicks Approve)
   * REJECTED  → action dropped      (operator clicks Reject)
   * EXPIRED   → action dropped      (auto-expired after expiresAt)
   */
  status String @default("PENDING")

  /**
   * Soft cutoff. Default 24h from createdAt; operators can extend
   * by editing the row from the queue UI in a follow-up. Stale
   * pending rows past this timestamp get auto-EXPIRED by the
   * approval-cleanup tick.
   */
  expiresAt DateTime

  /**
   * Audit fields populated when the operator acts.
   */
  approvedBy     String?
  approvedAt     DateTime?
  rejectedBy     String?
  rejectedAt     DateTime?
  rejectedReason String?

  /**
   * Outcome from the resumed action (when status='APPROVED' and
   * the action successfully fired). Same shape as
   * AutomationRuleExecution.actionResults. Null until resumed.
   */
  resolvedActionResults Json?

  /**
   * Optional link to the AutomationRuleExecution row created when
   * the approved action fires — lets the queue UI link straight
   * through to the per-execution drill-down.
   */
  resolvedExecutionId String?

  createdBy String?
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([status, expiresAt])
  @@index([ruleId, createdAt(sort: Desc)])
  @@index([workspaceId])
}

// ── W8 / Wave-8: Import wizard depth ──────────────────────────────
//
// Replaces the legacy BulkOperation CSV-upload flow (53% production
// failure rate) with a per-row tracked import job. Per-row state +
// rollback + retry-failed are first-class so a partial import never
// leaves the operator guessing what landed.
//
// Lifecycle:
//   PENDING_PREVIEW   parse + validate finished, awaiting confirm
//   APPLYING          rows are landing on the catalog
//   COMPLETED         every row SUCCESS or SKIPPED
//   PARTIAL           some rows FAILED, some SUCCESS
//   FAILED            zero rows committed (parser / validator
//                     blew the whole file)
//   CANCELLED         operator dropped before apply, or scheduled
//                     pull retired the job
//
// Source paths today:
//   upload    operator picked a file in the browser
//   url       scheduled pull from a URL (W8.4)
//   ftp       scheduled pull from FTP (W8.4)
// ── FF2: Flat-file import history ─────────────────────────────────────
//
// One row per flat-file import (preview → apply). Persists the uploaded
// file handle, the dry-run diff, the inverse diff (for one-click rollback),
// and the scope, so imports are auditable and reversible. Additive table;
// distinct from the legacy ImportJob (which serves the old import wizard).
model FlatFileImport {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id            String    @id @default(cuid())
  channel       String
  markets       Json
  includeMaster Boolean   @default(false)
  snapshotId    String?
  filename      String?
  uploadHandle  String?
  reportHandle  String?
  diff          Json?
  inverseDiff   Json?
  status        String    @default("PREVIEW")
  appliedCount  Int       @default(0)
  skippedCount  Int       @default(0)
  failedCount   Int       @default(0)
  rolledBackAt  DateTime?
  createdBy     String?
  createdAt     DateTime  @default(now())
  updatedAt     DateTime  @updatedAt

  @@index([channel, createdAt(sort: Desc)])
  @@index([status])
  @@index([workspaceId])
}

model ImportJob {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  jobName     String
  description String?

  /**
   * Where the file came from. 'upload' is the operator-driven
   * path; 'url' / 'ftp' are scheduled pulls.
   */
  source    String  @default("upload")
  /**
   * For url / ftp sources, the location pulled. Null for uploads.
   */
  sourceUrl String?
  /**
   * Original filename when known (uploads carry it).
   */
  filename  String?
  /**
   * Detected file kind: 'csv' | 'xlsx' | 'json'.
   */
  fileKind  String

  /**
   * What entity these rows write to:
   * 'product'         — base catalog rows
   * 'channelListing'  — per-marketplace overrides
   * 'inventory'       — stock-only updates
   * Drives validator + write path selection.
   */
  targetEntity String

  /**
   * Operator-supplied or auto-detected column → field mapping. Shape:
   * { sku: 'SKU', name: 'Title', basePrice: 'Price (EUR)' }
   * Fields the operator left unmapped fall through (no write).
   */
  columnMapping Json @default("{}")

  /**
   * Behaviour when a row hits a validation failure:
   * 'abort'   — first failure aborts the whole apply (legacy)
   * 'skip'    — failed rows skipped, successful rows commit
   * (default — partial-import is the expected case)
   */
  onError String @default("skip")

  status String @default("PENDING_PREVIEW")

  /**
   * Aggregate counters — kept on the parent for cheap UI.
   */
  totalRows   Int @default(0)
  successRows Int @default(0)
  failedRows  Int @default(0)
  skippedRows Int @default(0)

  errorSummary String?

  /**
   * AX-IE.5 — dry-run plan handshake.
   * planToken is a fingerprint of the computed plan. Apply must present it and it
   * must still match, which closes the window between "operator approved this
   * preview" and "apply ran": if anything moved underneath — the file re-staged,
   * an entity changed on Amazon — the token no longer matches and apply refuses
   * rather than executing a plan nobody agreed to.
   * planSummary holds the counts and blast-radius figures the operator was shown,
   * so what they approved is recoverable after the fact rather than recomputed.
   */
  planToken      String?
  planComputedAt DateTime?
  planSummary    Json?

  /**
   * Optional schedule that triggered this import (W8.4).
   */
  scheduleId  String?
  /**
   * A rerun-of-failed-rows points back at its parent.
   */
  parentJobId String?

  rows ImportJobRow[]

  createdBy   String?
  createdAt   DateTime  @default(now())
  startedAt   DateTime?
  completedAt DateTime?
  updatedAt   DateTime  @updatedAt

  @@index([status, createdAt(sort: Desc)])
  @@index([scheduleId])
  @@index([parentJobId])
  @@index([workspaceId])
}

model ImportJobRow {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  jobId String
  job   ImportJob @relation(fields: [jobId], references: [id], onDelete: Cascade)

  /**
   * Row index in the source file (1-based, header-skipped). Used to
   * link back to the original spreadsheet for triage.
   */
  rowIndex Int

  /**
   * Resolved target id when the row matched an existing entity (sku
   * match, etc.); null when the row was rejected before lookup.
   */
  targetId String?

  /**
   * Pre-validation snapshot of the row's parsed values. Frozen so
   * rollback can read what was about to be written.
   */
  parsedValues Json

  status String @default("PENDING") // PENDING | SUCCESS | FAILED | SKIPPED

  errorMessage String?

  /**
   * Snapshot of the entity's fields BEFORE the import wrote (only
   * populated when status=SUCCESS) — drives rollback.
   */
  beforeState Json?
  afterState  Json?

  createdAt   DateTime  @default(now())
  completedAt DateTime?

  /// Phase 2 — apply idempotency. Without this, two concurrent /bulk/apply
  /// POSTs both passed the plan-token check and both wrote every row.
  @@unique([workspaceId, jobId, rowIndex], name: "jobId_rowIndex", map: "ImportJobRow_jobId_rowIndex_key")
  @@index([jobId, status])
  @@index([targetId])
  @@index([workspaceId])
}

// ── W8.4: Scheduled imports ───────────────────────────────────────
//
// Recurring URL / FTP pulls. Mirrors ScheduledBulkAction's shape but
// for imports. The W8.4 worker fetches the file, hands it to the
// import service, and the resulting ImportJob row links back via
// scheduleId.
model ScheduledImport {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
