// O.3: Ordered rules engine for outbound shipments. WHEN <conditions>
// THEN <actions>, walked in priority order ASC. The applier (O.16)
// loads the active rule set into TS, matches in-process, and applies
// the first hit's actions to the shipment being created.
//
// conditions + actions are intentionally JSONB rather than normalized
// columns: the rule taxonomy expands fast (new channels, carrier
// services, packaging dimensions) and reads are always whole-rule —
// we never query "find rules where weight > X". Typed shape lives
// alongside the applier code (O.16), validated at write time.
//
// Documented condition keys (all optional; empty = "don't filter"):
//   channel, marketplace, destinationCountry, weightGramsMin,
//   weightGramsMax, orderTotalCentsMin, orderTotalCentsMax,
//   itemCountMin, itemCountMax, isPrime, hasHazmat, skuMatch
// Documented action keys:
//   preferCarrierCode, preferServiceCode, requireSignature,
//   requireInsurance, insuranceCents, packagingId, holdForReview,
//   addLabel
model ShippingRule {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  name        String
  description String?

  // Lower number = higher priority. Applier walks ASC and uses first match.
  priority Int     @default(100)
  // Inactive rules don't fire but stay visible for editing/cloning.
  isActive Boolean @default(true)

  conditions Json @default("{}")
  actions    Json @default("{}")

  // Audit + analytics; lastFiredAt drives rules-list "most active" sort.
  lastFiredAt  DateTime?
  triggerCount Int       @default(0)

  // Free-form operator ID (no first-class User model in this repo yet).
  createdBy String?
  updatedBy String?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  // Applier's primary read: active rules in priority order.
  @@index([isActive, priority])
  // Rules-list UI: "stale" / "most recently fired" sorts.
  @@index([lastFiredAt])
  @@index([workspaceId])
}

model Supplier {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                     String    @id @default(cuid())
  name                   String
  contactName            String?
  email                  String?
  phone                  String?
  addressLine1           String?
  city                   String?
  postalCode             String?
  country                String?   @default("IT")
  taxId                  String? // partita IVA / VAT number
  paymentTerms           String? // e.g. "Net 30" / "30gg DF"
  defaultCurrency        String?   @default("EUR")
  leadTimeDays           Int       @default(14)
  // S2 — production + shipping time split (supplier-level defaults; per-
  // product override lives on SupplierProduct). leadTimeDays stays as the
  // legacy combined fallback so existing data is unchanged. Effective lead
  // time = productionDays(qty) + shippingTimeDays when set, else leadTimeDays.
  // productionTimeDays = flat days; productionUnitsPerDay = rate (production
  // days = ceil(qty / rate)). Operator sets whichever fits; rate wins.
  productionTimeDays     Int?
  productionUnitsPerDay  Int?
  shippingTimeDays       Int?
  // R.11 — observed lead-time variance, computed nightly by
  // lead-time-stats.job from PO createdAt → InboundShipment.arrivedAt.
  // Feeds the second term of the textbook safety-stock formula:
  //   SS = z × √(σ_d² × LT + d² × σ_LT²)
  // Null/0 collapses the formula back to R.4's d-only behavior so
  // suppliers without enough history degrade gracefully.
  leadTimeStdDevDays     Decimal?  @db.Decimal(8, 2)
  leadTimeSampleCount    Int       @default(0)
  leadTimeStatsUpdatedAt DateTime?

  isActive Boolean @default(true)
  notes    String?

  // R.6 — auto-PO opt-in. Both autoTriggerEnabled at the Supplier
  // AND at the per-product ReplenishmentRule must be true for an
  // auto-PO to fire (defense in depth). Per-PO ceilings cap blast
  // radius even when opted in; null = use the global env-var
  // defaults (NEXUS_AUTO_PO_QTY_CEILING_DEFAULT,
  // NEXUS_AUTO_PO_COST_CEILING_CENTS_DEFAULT).
  autoTriggerEnabled           Boolean @default(false)
  autoTriggerMaxQtyPerPo       Int?
  autoTriggerMaxCostCentsPerPo Int?
  // R.13 — separate opt-in for event-prep auto-PO (Black Friday,
  // saldi, etc.). Disabled by default even when autoTriggerEnabled
  // is true: event prep creates large up-front orders that should
  // be explicit. Operator flips on per-supplier when ready.
  autoTriggerEventPrep         Boolean @default(false)

  products        SupplierProduct[]
  purchaseOrders  PurchaseOrder[]
  poTemplates     PoTemplate[]
  // R.19 — optional shipping profile (mode + freight rates +
  // container capacity). When present, enables landed-cost EOQ and
  // container-fill suggestions.
  shippingProfile SupplierShippingProfile?
  contacts        SupplierContact[] // PD.2
  comms           SupplierComm[] // PD.3
  followUps       SupplierFollowUp[] // PD.4
  devCandidates   DevelopmentProjectSupplier[] // PD.5

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt
  @@index([workspaceId])
}

// R.19 — supplier shipping profile drives freight cost in the
// landed-cost EOQ and the container-fill optimizer. One row per
// supplier (supplierId is unique).
//
// Modes:
//   AIR        — costPerKgCents + costPerCbmCents (volumetric ratio 1cbm:167kg)
//   SEA_LCL    — costPerCbmCents dominates (1cbm:333kg ratio)
//   SEA_FCL_20 — fixedCostCents per 20' container (33 cbm / 28000 kg)
//   SEA_FCL_40 — fixedCostCents per 40HQ container (76 cbm / 28800 kg)
//   ROAD       — costPerKgCents + costPerCbmCents (1cbm:333kg ratio)
//
// Cost cents are in `currencyCode`; landed-cost math runs through
// fx-rate.service to convert to EUR matching R.15.
model SupplierShippingProfile {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                   String   @id @default(cuid())
  supplierId           String   @unique
  supplier             Supplier @relation(fields: [supplierId], references: [id], onDelete: Cascade)
  mode                 String // AIR | SEA_LCL | SEA_FCL_20 | SEA_FCL_40 | ROAD
  costPerCbmCents      Int?
  costPerKgCents       Int?
  fixedCostCents       Int?
  currencyCode         String   @default("EUR")
  containerCapacityCbm Decimal? @db.Decimal(8, 2)
  containerMaxWeightKg Decimal? @db.Decimal(10, 2)
  notes                String?
  createdAt            DateTime @default(now())
  updatedAt            DateTime @updatedAt

  @@index([supplierId])

  @@index([workspaceId])
}

model SupplierProduct {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                            String  @id @default(cuid())
  supplierId                    String
  productId                     String
  supplierSku                   String?
  costCents                     Int? // cost per unit in supplier's default currency
  currencyCode                  String? @default("EUR")
  moq                           Int     @default(1) // minimum order quantity
  casePack                      Int? // R.4 — units per carton (orders rounded up to multiples)
  leadTimeDaysOverride          Int?
  // S2 — per-product production + shipping time overrides (fall back to the
  // Supplier-level defaults, then to leadTimeDaysOverride/leadTimeDays).
  productionTimeDaysOverride    Int?
  productionUnitsPerDayOverride Int?
  shippingTimeDaysOverride      Int?
  isPrimary                     Boolean @default(false)

  // PD.1 — factory-facing naming (per-supplier default). Factories often
  // can't read our master SKU/name (different language); these give the
  // operator a name/size/spec the factory understands, auto-filled onto
  // every PO line for this supplier×product and rendered on the factory
  // PDF + supplier email. A PO line can still override per order.
  factoryName String?
  factorySize String?
  factorySpec String?

  // PO-Plus.7 — observed landed cost in EUR cents. Populated when the
  // operator clicks "Push to catalog" on the PO.11 three-way match
  // panel after receiving a PO. Distinct from `costCents` (which is
  // the supplier-quoted factory cost) — landed cost includes the
  // prorated shipping/customs/duties/insurance from the linked
  // InboundShipment. Replenishment recommendations prefer
  // lastLandedCostCents over costCents when present so EOQ math
  // works against true-cost.
  lastLandedCostCents     Int?
  lastLandedCostUpdatedAt DateTime?

  supplier Supplier @relation(fields: [supplierId], references: [id], onDelete: Cascade)

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@unique([workspaceId, supplierId, productId], name: "supplierId_productId", map: "SupplierProduct_supplierId_productId_key")
  @@index([productId])
  @@index([workspaceId])
}

model PurchaseOrder {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                   String              @id @default(cuid())
  poNumber             String
  // PD.8 — sample/development PO linkage.
  developmentProjectId String?
  poKind               String              @default("STANDARD") // STANDARD | SAMPLE
  developmentProject   DevelopmentProject? @relation(fields: [developmentProjectId], references: [id], onDelete: SetNull)
  supplierId           String?
  warehouseId          String?
  status               PurchaseOrderStatus @default(DRAFT)
  expectedDeliveryDate DateTime?
  totalCents           Int                 @default(0)
  currencyCode         String              @default("EUR")
  notes                String?
  createdBy            String?
  version              Int                 @default(1)

  // R.7 — workflow audit. Captured by po-workflow.service when the
  // state machine fires. Each timestamp pairs with the user who
  // triggered that transition.
  reviewedAt        DateTime?
  reviewedByUserId  String?
  approvedAt        DateTime?
  approvedByUserId  String?
  submittedAt       DateTime?
  submittedByUserId String?
  acknowledgedAt    DateTime?
  cancelledAt       DateTime?
  cancelledReason   String?

  // PO.1 — supplier-confirmed ETA + signed-token ack URL.
  // When PO.9 emails the supplier we mint a random `supplierAckToken`
  // and embed it in a public `/po/ack/:token` URL. Supplier opens the
  // URL, confirms (or proposes a new) ETA → backend writes
  // `supplierConfirmedDeliveryDate` + `supplierConfirmedAt` and flips
  // the PO to ACKNOWLEDGED. `supplierAckExpiresAt` caps token lifetime
  // (default 30d) so stale links can't be re-used. Token rotates on
  // every "Send" so a revision (PO.8) invalidates the old link.
  supplierConfirmedDeliveryDate DateTime?
  supplierConfirmedAt           DateTime?
  supplierAckToken              String?
  supplierAckExpiresAt          DateTime?

  // PO-Plus.2 — approver-side signed-token URL. Parallel to the
  // supplier ack columns but bound to the approval workflow: minted
  // by po-workflow.service when submit-for-review lands at REVIEW
  // because totalCents exceeds BrandSettings.poApprovalThresholdCents.
  // The approver clicks the URL in their inbox → public
  // `/po/approve/:token` page → Approve / Decline → backend flips PO
  // to APPROVED (or back to DRAFT). Token rotates on every fresh
  // submit-for-review so a stale email can't double-approve.
  approverAckToken     String?
  approverAckExpiresAt DateTime?

  // PO-Plus.8 — drop-ship override. When set, this PO ships goods
  // directly from supplier to the address in this JSON blob rather
  // than to the configured warehouseId. Shape:
  //   { contactName?, company?, addressLines[], city, postalCode,
  //     country, phone?, instructions? }
  // Surfaces on the factory PDF in PO.12 as the "Ship to" block.
  shipToAddress Json?

  supplier         Supplier?                 @relation(fields: [supplierId], references: [id])
  warehouse        Warehouse?                @relation(fields: [warehouseId], references: [id])
  items            PurchaseOrderItem[]
  inboundShipments InboundShipment[]
  // PO.1 — PO-level docs (supplier quote, contract refs, customer art,
  // EAN labels). Cascade-delete with the parent; survives soft-delete
  // because the parent does too.
  attachments      PurchaseOrderAttachment[]
  revisions        PurchaseOrderRevision[]
  comments         PoComment[]

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  // RB.1 — soft-delete (recycle bin).
  deletedAt DateTime?

  @@index([supplierId])
  @@index([status])
  @@index([status, deletedAt])
  // PO.1 — read-side hot path for the "Awaiting my approval" + late-PO
  // saved views in PO.14. expectedDeliveryDate-without-deletedAt is
  // common enough to warrant its own composite.
  @@index([expectedDeliveryDate, deletedAt])
  @@unique([workspaceId, poNumber], name: "workspace_poNumber", map: "PurchaseOrder_workspace_poNumber_key")
  @@unique([workspaceId, supplierAckToken], name: "workspace_supplierAckToken", map: "PurchaseOrder_workspace_supplierAckToken_key")
  @@unique([workspaceId, approverAckToken], name: "workspace_approverAckToken", map: "PurchaseOrder_workspace_approverAckToken_key")
  @@index([workspaceId])
}

model PurchaseOrderItem {
  // Business ownership comes from verified database context.
