// PO.1 — PO-level attachments (supplier quote PDF, signed contract,
// customer art file, EAN label sheet). Distinct from
// InboundShipmentAttachment which is receive-side (invoice, packing
// list, photos). Cascade-deletes with the parent PO.
model PurchaseOrderAttachment {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id              String   @id @default(cuid())
  purchaseOrderId String
  // QUOTE | CONTRACT | ART | LABEL | EMAIL | OTHER
  kind            String
  url             String
  filename        String?
  contentType     String?
  sizeBytes       Int?
  uploadedBy      String?
  uploadedAt      DateTime @default(now())

  purchaseOrder PurchaseOrder @relation(fields: [purchaseOrderId], references: [id], onDelete: Cascade)

  @@index([purchaseOrderId])
  @@index([kind])
  @@index([workspaceId])
}

// PO.1 — post-SUBMITTED revisions. PO.8 lets the operator open a
// revision (qty change, price re-quote, ETA slip). The revision row
// freezes a JSON snapshot of items at the moment of creation so the
// diff UI can render side-by-side without resurrecting historical
// state. supplier re-ack is required → status flow:
//   PENDING            (revision drafted, not yet sent)
//   SUPPLIER_NOTIFIED  (PO.9 emailed the supplier the change order)
//   SUPPLIER_ACKED     (supplier confirmed via ack URL or operator manual)
//   SUPERSEDED         (a newer revision replaced this one)
//   CANCELLED          (operator abandoned the revision)
//
// snapshotJson shape (frozen at create time):
//   { items: [{ sku, qty, unitCostCents, note }], total, currency }
// Stored as Json so future fields can land without a migration.
model PurchaseOrderRevision {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                 String    @id @default(cuid())
  purchaseOrderId    String
  version            Int // monotonic per parent PO; starts at 2 (v1 = the original)
  reason             String?
  status             String    @default("PENDING") // see comment above
  snapshotJson       Json
  createdBy          String?
  createdAt          DateTime  @default(now())
  supplierNotifiedAt DateTime?
  supplierAckedAt    DateTime?
  cancelledAt        DateTime?

  purchaseOrder PurchaseOrder @relation(fields: [purchaseOrderId], references: [id], onDelete: Cascade)

  @@unique([workspaceId, purchaseOrderId, version], name: "purchaseOrderId_version", map: "PurchaseOrderRevision_purchaseOrderId_version_key")
  @@index([purchaseOrderId])
  @@index([status])
  @@index([workspaceId])
}

// PO.1 — threaded comments on a PO. Powers PO.7 approval routing
// ("Approve please" → @cfo) and PO.6/8 collaboration ("supplier
// quoted us 12 not 10 → opening revision"). mentions[] stores
// resolved user IDs / emails for the notification fan-out; the raw
// markdown body keeps the @-mention text for re-render.
model PoComment {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id              String    @id @default(cuid())
  purchaseOrderId String
  userId          String?
  body            String
  // Either userIds or email strings — whichever the @-picker resolved.
  mentions        String[]  @default([])
  createdAt       DateTime  @default(now())
  editedAt        DateTime?

  purchaseOrder PurchaseOrder @relation(fields: [purchaseOrderId], references: [id], onDelete: Cascade)

  @@index([purchaseOrderId, createdAt])
  @@index([workspaceId])
}

// PO-Plus.8 — Persisted audit log for PO lifecycle events. The in-
// process po-events.service bus fans out to SSE subscribers but
// doesn't survive process restarts; PoEventLog mirrors every emit
// so an operator can grep the full history for forensics, compliance,
// or "who acked this revision" questions long after the fact.
//
// type values match the runtime PoEvent union from po-events.service:
//   po.created | po.updated | po.transitioned | po.deleted |
//   po.restored | po.received
//
// payload snapshots the full event object as JSON so future fields
// land without a migration.
model PoEventLog {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id        String   @id @default(cuid())
  poId      String?
  poNumber  String?
  type      String
  reason    String?
  payload   Json
  createdAt DateTime @default(now())

  @@index([poId, createdAt])
  @@index([type, createdAt])
  @@index([createdAt])
  @@index([workspaceId])
}

// PO-Plus.6 — Reusable PO template. "Save as template" on an existing
