// F.3 — defer a Product mutation to a future timestamp.
//
// Use case: an operator wants to flip a SKU's status to ACTIVE at
// 09:00 CET on Black Friday, or drop a price by 15% at midnight.
// Today they have to set an alarm and click. With this row, they
// queue the change; a cron worker (`scheduled-changes.cron.ts`,
// runs every 60s) picks up rows whose scheduledFor <= now() and
// applies the same service-level mutation that PATCH /api/products
// uses, so cascades to ChannelListing + invalidations behave the
// same as a manual edit.
//
// Status state machine:
//   PENDING   → APPLIED (success path) | FAILED (error path) |
//                CANCELLED (operator cancels before scheduledFor)
//
// Concurrency: the cron picks rows with FOR UPDATE SKIP LOCKED so
// multiple worker replicas can't double-apply. appliedAt + error
// land in the same UPDATE that flips PENDING → APPLIED/FAILED.
//
// Payload shape: kind === 'STATUS'
//   { status: 'ACTIVE' | 'DRAFT' | 'INACTIVE' }
// kind === 'PRICE'
//   { basePrice: number }       — absolute new price
//   { adjustPercent: number }   — relative to current basePrice
//
// Future kinds (description, tag changes, channel publish) extend
// the JSON without a migration.
model ScheduledProductChange {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id        String  @id @default(cuid())
  productId String
  product   Product @relation(fields: [productId], references: [id], onDelete: Cascade)

  // What to apply.
  kind    String // 'STATUS' | 'PRICE' (extend without migration)
  payload Json

  // When.
  scheduledFor DateTime

  // Lifecycle.
  status    String    @default("PENDING") // 'PENDING' | 'APPLIED' | 'FAILED' | 'CANCELLED'
  appliedAt DateTime?
  error     String?

  // Who.
  createdBy String?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  // Cron picker — most selective filter is (status, scheduledFor)
  // so the worker scans PENDING in time order without a Seq Scan.
  @@index([status, scheduledFor])
  // Drawer / list view per product — one query for "what's queued".
  @@index([productId, status])
  @@index([workspaceId])
}

// W4.1 — AutomationRule + AutomationRuleExecution.
//
// The replenishment platform has hardcoded auto-PO logic (R.6) that
// fires nightly with env-var ceilings. The audit revealed this is
// the CORNERSTONE feature gap: operators want to compose their own
// rules (auto-approve below €500, emergency reorder on stockout,
// alert on demand spike, etc.) without a code change.
//
// Domain-tagged so the engine can extend beyond replenishment later
// (pricing, inbound, returns) without a migration.
//
// Defense-in-depth defaults:
//   - enabled=false   new rules don't fire until explicitly turned on
//   - dryRun=true     opt-in to write-side actions
//   - maxExecutionsPerDay=100   runaway-loop protection
//   - maxValueCentsEur=null     caller-set ceiling on actions that spend
//
// Conditions DSL (JSON):
//   [{ field: 'recommendation.totalCents', op: 'lt', value: 50000 },
//    { field: 'supplier.onTimeRate', op: 'gte', value: 0.95 }]
// Operators: eq | ne | lt | lte | gt | gte | in | contains | exists.
// All conditions AND together. For OR semantics, create multiple rules
// sharing the same trigger.
//
// Actions DSL (JSON):
//   [{ type: 'auto_approve_recommendation' },
//    { type: 'create_po' },
//    { type: 'notify', target: 'operator', message: '...' }]
// Action types are domain-specific and registered at the evaluator.
model AutomationRule {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String  @id @default(cuid())
  name        String
  description String?

  domain  String @default("replenishment")
  trigger String

  conditions Json @default("[]")
  actions    Json @default("[]")

  enabled Boolean @default(false)
  dryRun  Boolean @default(true)

  /// ADX N2 — the intensity dial. `dryRun` is a binary, and a binary is why 21 rules sat
  /// stuck asking permission: there was no way to move one a single notch and watch it.
  ///
  ///   OFF     — `enabled=false` handles this; kept in the vocabulary for completeness
  ///   OBSERVE — evaluates and records what it WOULD do. No proposal, no write. The quiet
  ///             mode for a rule you are not ready to hear from yet.
  ///   PROPOSE — evaluates and queues an AdsRuleSuggestion for approval. Today's default.
  ///   AUTO    — acts, within its own caps and whatever ads-write-gate.ts enforces.
  ///
  /// The ramp WITHIN auto is `maxExecutionsPerDay`, which already exists: "act, but at most
  /// five times today" is a real intensity control and needs no new machinery. Pacvue ships
  /// the same idea as a conservative→aggressive dial and their own research calls it the
  /// underrated leg of governance — it is how trust gets built incrementally rather than
  /// wagered all at once.
  ///
  /// `enabled` still gates evaluation, so the evaluator's queries are untouched. Backfilled
  /// from dryRun so behaviour is identical on the day this ships.
  autonomyLevel String @default("PROPOSE")

  /// EA7 (2026-08-20) — ORDER. Which rule wins when two of them write the same field on the same
  /// entity in one tick.
  ///
  /// 🔴 Before this there was no ordering of ANY kind: `evaluateAllRulesForTrigger` selected rules
  /// with no `orderBy` and ran them in whatever order Postgres returned, so the outcome of a
  /// collision was decided by row order. The conflict detector could SEE the collisions — every
  /// campaign has 12+ actors on its bids — and nothing could resolve one.
  ///
  /// Lower runs first. The default of 100 leaves room on both sides without renumbering anything,
  /// and every existing rule shares it, so the day this ships nothing reorders: ties fall back to
  /// `createdAt`, which is the order they already ran in.
  ///
  /// The convention this encodes, from every platform in the nine-platform study: cost control
  /// before growth. A rule that yields is NOT silent — it records `yielded`, which is a different
  /// fact from "did not match" and from "refused at the gate".
  priority Int @default(100)

  maxExecutionsPerDay     Int?    @default(100)
  /// CAP (2026-08-14) — the SECOND cap, in the unit damage is actually measured in.
  ///
  /// `maxExecutionsPerDay` counts EXECUTION ROWS, and a row is one (rule × context) match. One
  /// evaluator tick emits one context per active marketplace — 9 on this account — so a SCHEDULE
  /// rule doing one logical run per tick writes 9 rows and 864 in a day. That makes the row cap a
  /// churn bound: it governs engine load, notifications and proposal volume. It is a poor bound on
  /// harm, because rows and writes are not the same quantity and never were.
  ///
  /// Measured 2026-08-14: `Trim budget on weak ACOS` walked one campaign from €100.00 to €1.00 in
  /// 39 Amazon writes in a single day while carrying a row cap of 10, because its trigger produced
  /// roughly one matching context per tick — so its row count and its write count were different
  /// numbers the whole time.
  ///
  /// This counts rows in `AdvertisingActionLog` written by this rule's actor today
  /// (`userId = 'automation:<ruleId>'`). 🔴 NOT by `executionId`: `automation-action-handlers.ts`
  /// passes `executionId: null` on every rule write, so an executionId-keyed cap reads zero for
  /// every rule and never binds — the same shape of silent failure as the bare `NOT` clause.
  ///
  /// Reaching it DEMOTES the execution to dry-run rather than refusing it. A cap that also blocks
  /// the rule's `notify` hides itself: `Reduce bids on ACOS spike` carried `maxValueCentsEur = 0`
  /// and refused every action including the notification that would have said so, silently, for
  /// weeks. A demoted rule still evaluates, still proposes and still tells you.
  ///
  /// null = no write cap (today's behaviour for every rule that has one unset).
  maxWritesPerDay         Int?
  maxValueCentsEur        Int?
  // AD.3 — per-rule daily SUM cap across executions, complementary to
  // maxValueCentsEur (which is per-execution). Defense-in-depth for
  // advertising rules where a single trigger can fire many times in a
  // day (one execution per matched FbaStorageAge row, say) and each
  // execution can spend separately. Defaults to NULL = no cap.
  maxDailyAdSpendCentsEur Int?
  // AD.3 — when set, trigger context builders skip contexts whose
  // marketplace ≠ scopeMarketplace. Lets operators run "DE-only" rules
  // without conditions DSL boilerplate.
  scopeMarketplace        String?
  /// ACR.7 — drag-to-scope. A rule dropped on a portfolio or campaign is bound to it: the
  /// evaluator only lets it fire on contexts inside that scope. null = account-wide (today's
  /// behaviour, unchanged). scopePortfolioId holds the EXTERNAL portfolio id, matching
  /// Campaign.portfolioId; scopeCampaignId holds the local Campaign.id.
  scopePortfolioId        String?
  scopeCampaignId         String?
  /// RA.GRAIN — the fourth grain: a `Product.id`, either a PARENT (the whole product line) or one
  /// child variation. Not a FK on purpose: deleting a product must not cascade a rule away, and a
  /// dangling id resolves to zero campaigns, which the reach line states honestly.
  ///
  /// The line grain needed no new entity. `Product.parentId` (self-relation `ProductHierarchy`)
  /// already models it, and measured on prod 2026-08-10 all 223 advertised products are children
  /// of exactly 13 parents — GALE-JACKET 18 children / 77 campaigns / 4 markets, and so on. Do NOT
  /// reach for `ProductVariation` (0 rows) or `ProductFamily` (0 rows, and an Akeneo-style
  /// attribute template rather than a line).
  ///
  /// Scope stays an AND of dimensions. market × product is the pairing that earns its place:
  /// 106 of 250 advertised ASINs span more than one market, so "GALE in DE only" is a real scope.
  scopeProductId          String?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt
  createdBy String?

  evaluationCount Int       @default(0)
  matchCount      Int       @default(0)
  executionCount  Int       @default(0)
  lastEvaluatedAt DateTime?
  lastMatchedAt   DateTime?
  lastExecutedAt  DateTime?

  executions AutomationRuleExecution[]

  /// D1 (2026-08-20) — campaigns this rule is ASSIGNED to. See `CampaignRuleAssignment`.
  assignments CampaignRuleAssignment[]

  @@index([domain, enabled])
  @@index([trigger])
  @@index([workspaceId])
}

/// ── D1 (2026-08-20) — per-campaign rule assignment ────────────────────────────────────────────
///
/// Operator study of Helium 10's Budget Rule column: a campaign carries an assigned rule, chosen
/// from a dropdown, and a rule does nothing until it is assigned.
///
/// 🔴 **This is the INVERSE of the scope columns, which is why it needs its own table.**
/// `AutomationRule.scopeCampaignId` is a single nullable string pointing rule → campaign, so
/// assigning a rule to a second campaign MOVES it off the first. That is why "+ Assign Rule" was
/// withheld on 2026-08-18 rather than shipped on top of it. Assignment points campaign → rule and
/// is many-to-many; the two mechanisms coexist and `scopeCampaignId` is untouched.
///
/// ── The unique key is (campaignId, ruleId), NOT (campaignId, kind) — operator decision ─────────
/// H10's dropdown holds one rule per campaign, and a strict `(campaignId, kind)` would express
/// that. It is deliberately NOT used, because measured on prod 2026-08-20 **four enabled budget
/// rules act on every campaign** (two AUTO cuts at −15% and −20%, two PROPOSE raises), so a strict
/// key admits no faithful backfill: today's behaviour could not be reproduced and two live rules
/// would stop cutting. The permissive key preserves reach exactly; thinning to one rule per
/// campaign becomes an operator choice made through the column rather than a migration.
/// ⚠️ Do not "tidy" this into `(campaignId, kind)` later: Prisma emits `ON CONFLICT` from the
/// unique key, so narrowing it breaks every upsert caller at RUNTIME, not compile time.
///
/// `kind` groups assignments by what the rule governs ('budget' today) so the same table serves
/// Bid and Placement assignment later without a second migration.
model CampaignRuleAssignment {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id         String @id @default(cuid())
  campaignId String
  ruleId     String
  /// 'budget' today. 'bid' | 'placement' | 'dayparting' follow the same H10 Assign Rule dialog.
  kind       String @default("budget")

  createdAt DateTime @default(now())
  createdBy String?

  campaign Campaign       @relation(fields: [campaignId], references: [id], onDelete: Cascade)
  rule     AutomationRule @relation(fields: [ruleId], references: [id], onDelete: Cascade)

  @@unique([workspaceId, campaignId, ruleId], name: "campaignId_ruleId", map: "CampaignRuleAssignment_campaignId_ruleId_key")
  @@index([ruleId, kind])
  @@index([campaignId, kind])
  @@index([workspaceId])
}

// B3 (Budget rule builder): reusable rule templates — saved criteria + THEN action,
// reapplied to new rules. Additive; independent of AutomationRule.
model AutomationRuleTemplate {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id        String   @id @default(cuid())
  name      String
  domain    String   @default("advertising")
  type      String // rule-type slug: 'budget' (later 'bid', etc.)
  payload   Json     @default("{}")
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt
  createdBy String?

  @@index([domain, type])
  @@index([workspaceId])
}

model AutomationRuleExecution {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id     String         @id @default(cuid())
  ruleId String
  rule   AutomationRule @relation(fields: [ruleId], references: [id], onDelete: Cascade)

  // The trigger payload that the rule matched against. Frozen at
  // execution time so post-hoc audits show what the engine saw.
  triggerData Json

  // Per-action outcomes. Shape:
  //   [{ type: 'auto_approve', ok: true, output: {...} },
  //    { type: 'create_po',    ok: false, error: 'MOQ exceeded' }]
  actionResults Json

  dryRun       Boolean
  status       String // SUCCESS | PARTIAL | FAILED | DRY_RUN
  errorMessage String?

  startedAt  DateTime  @default(now())
  finishedAt DateTime?
  durationMs Int?

  @@index([ruleId, startedAt(sort: Desc)])
  @@index([status, startedAt(sort: Desc)])
  @@index([workspaceId])
}

// ES1 — Manual-control ads rules are propose-only: when one matches in dry-run it writes a
// suggestion here for the operator to Approve (apply live) or Dismiss on the Suggestions page.
// Dedup key (ruleId + entityId + proposedKey) keeps one pending row per rule×entity×change.
model AdsRuleSuggestion {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String  @id @default(cuid())
  ruleId      String
  ruleName    String?
  executionId String?
  trigger     String?
  marketplace String?

  entityType String // CAMPAIGN | AD_TARGET | SEARCH_TERM
  entityId   String
  entityName String?

  // The proposed change: { type, op?, value?, wouldChange?, placement?, ... } (the *_apply output).
  proposedAction Json
  // Stable dedup key for the change kind (e.g. 'budget_apply:decPct:20') — one pending row per.
  proposedKey    String

  status        String    @default("pending") // pending | applied | dismissed | expired (SG.0)
  createdAt     DateTime  @default(now())
  // SG.0 — the newest evaluation that still proposes this change. Stamped on every upsert
  // (create AND refresh); `createdAt` stays the FIRST sighting. The lifecycle sweep expires
  // pending rows the engine has stopped re-proposing and resurrects decided rows it still
  // proposes (see ads-suggestions.service.ts sweepSuggestionLifecycle).
  lastSeenAt    DateTime  @default(now())
  decidedAt     DateTime?
  decidedBy     String? // 'operator' | 'operator:paused' | 'system:stale'
  appliedResult Json?

  @@unique([workspaceId, ruleId, entityId, proposedKey], map: "AdsRuleSuggestion_dedupe_key", name: "ruleId_entityId_proposedKey")
  @@index([status, createdAt(sort: Desc)])
  @@index([status, lastSeenAt])
  @@index([ruleId, createdAt(sort: Desc)])
  @@index([workspaceId])
}

/// SG.9 — "stop suggesting for this one", H10's third verb.
///
/// Their KB (Helium 10 Ads Suggestions, "Pausing Suggestions"): *"Pausing a Suggestion means
/// you no longer wish to collect data on the keyword or target in the campaign and ad group
/// for suggestions"* — and, from their review guide, it *"ensur[es] that it remains active
/// regardless of performance"*. So this is a MUTE, not a pause: the entity keeps running at
/// Amazon and the producers stop proposing changes for it. (A real pause is a rule ACTION
/// that arrives as a suggestion row and is approved with ✓ — a different thing entirely.)
///
/// `scope` keeps the three producers honest about their own reach, because each consults this
/// table separately and a mute made on one surface must not silently gag another:
///   rules           → ads-suggestions.service.ts (the AdsRuleSuggestion writer)
///   ai              → ad-autopilot.job.ts (the conductor's SUGGEST branch)
///   recommendations → ads-recommendations.service.ts (the computed feed)
model AdsSuggestionMute {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  /// which producer this mute binds: rules | ai | recommendations
  scope       String  @default("rules")
  /// AD_TARGET | SEARCH_TERM | CAMPAIGN | MARKETPLACE | ACCOUNT | RECOMMENDATION
  entityType  String
  entityId    String
  /// denormalised so the Muted view can name what it silenced without a join back to a
  /// possibly-deleted entity — the label is the only record left for a removed target
  entityName  String?
  marketplace String?

  reason    String?
  createdBy String?
  createdAt DateTime @default(now())

  @@unique([workspaceId, scope, entityType, entityId], name: "scope_entityType_entityId", map: "AdsSuggestionMute_scope_entityType_entityId_key")
  @@index([scope])
  @@index([workspaceId])
}

// SK3 — keyword rank tracker. A time-series of organic / paid (sponsored) rank snapshots per
// keyword × marketplace, feeding the Keyword Tracker report + the KEYWORD_RANK_BID rule. Amazon's
// SP-API does NOT expose organic rank, so rows arrive via ingestion (manual / import / a future
// collector); `source` records provenance. The latest snapshot per (keyword, marketplace) is the
// authoritative current rank; the prior snapshot gives the rank delta.
model KeywordRank {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id            String   @id @default(cuid())
  keyword       String
  marketplace   String // EU market code (DE, IT, FR, …)
  asin          String? // the product whose rank this tracks (optional)
  organicRank   Int? // 1-based organic SERP position; null = outside tracked depth / unknown
  sponsoredRank Int? // 1-based sponsored position; null = not running / unknown
  searchVolume  Int? // est. monthly search volume from the source
  capturedAt    DateTime @default(now()) // when this rank was observed
  source        String   @default("manual") // manual | import | <collector-id>
  createdAt     DateTime @default(now())

  @@index([keyword, marketplace, capturedAt(sort: Desc)])
  @@index([marketplace, capturedAt(sort: Desc)])
  @@index([asin])
  @@index([workspaceId])
}

// W5.1 — Scenario + ScenarioRun for what-if planning.
//
// Scenario captures a hypothesis the operator wants to plan against:
// "Black Friday +200% velocity for 7 days", "Supplier ABC lead-time
// disrupted +14 days", "Switch to backup supplier for SKU class A".
//
// Each scenario can be re-run as inputs change (forecast updates,
// new POs, FX moves). ScenarioRun captures one execution: the
// recommendations it produced, the cash-flow impact, the service-
// level achievement.
//
// Pure-data schema; the planner service (W5.2) interprets `kind` +
// `params` JSON. Today's kinds: PROMOTIONAL_UPLIFT |
// LEAD_TIME_DISRUPTION | SUPPLIER_SWAP. Adding a kind = one branch
// in the planner + one entry in the routes whitelist. No migration.
model Scenario {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String  @id @default(cuid())
  name        String
  description String?

  // What kind of hypothesis does this scenario model? Drives which
  // branch of the planner runs. Examples:
  //   PROMOTIONAL_UPLIFT       multiplies forecasted demand for a
  //                            window by params.upliftPct
  //   LEAD_TIME_DISRUPTION     adds params.extraDays to every PO's
  //                            ETA in the window; recompute reorder
  //                            points
  //   SUPPLIER_SWAP            for SKUs in params.skuFilter, swap
  //                            preferredSupplierId to params.targetSupplierId
  kind String

  // Hypothesis params (kind-specific JSON). Shape examples:
  //   PROMOTIONAL_UPLIFT  { upliftPct: 200, fromDate, toDate, skuFilter? }
  //   LEAD_TIME_DISRUPTION { extraDays: 14, supplierId?, fromDate, toDate }
  //   SUPPLIER_SWAP       { skuFilter, targetSupplierId, fromDate, toDate }
  params Json @default("{}")

  // Optional baseline horizon. Default 90 days from createdAt.
  horizonDays Int @default(90)

  // Saved presets vs ad-hoc one-shots. Saved scenarios appear in
  // the "Compare scenarios" UI; ad-hoc don't.
  isSaved Boolean @default(false)

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt
  createdBy String?

  runs ScenarioRun[]

  @@index([kind])
  @@index([isSaved, updatedAt(sort: Desc)])
  @@index([workspaceId])
}

model ScenarioRun {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id         String   @id @default(cuid())
  scenarioId String
  scenario   Scenario @relation(fields: [scenarioId], references: [id], onDelete: Cascade)

  // The full input bag the planner used: scenario.params merged
  // with any per-run overrides (forecast snapshot, FX rates,
  // current stock). Frozen at run time so the audit trail survives
  // input drift.
  inputs Json

  // What the planner produced. Shape:
  //   {
  //     summary: { recsAffected, totalUnitsDelta, totalCostDelta },
  //     timeline: [{ week, baselineCents, scenarioCents, deltaCents }],
  //     recommendations: [{ sku, baselineQty, scenarioQty, deltaQty }],
  //     warnings: [...]
  //   }
  output Json

  // Surfaced counters so the UI doesn't parse output for the list.
  recsAffected        Int @default(0)
  totalUnitsDelta     Int @default(0)
  totalCostDeltaCents Int @default(0)

  status       String // RUNNING | SUCCESS | FAILED
  errorMessage String?

  startedAt  DateTime  @default(now())
  finishedAt DateTime?
  durationMs Int?

  @@index([scenarioId, startedAt(sort: Desc)])
  @@index([status, startedAt(sort: Desc)])
  @@index([workspaceId])
}

// ── Channel Listing Reconciliation (Phase RECON) ──────────────────────────
//
// Holds every Amazon/eBay listing discovered during a reconciliation run and
// its match status against Nexus products. Operator must CONFIRM every row
// before Nexus writes back externalListingId to ChannelListing.
//
// Lifecycle:
//   PENDING      — freshly ingested, awaiting operator review
//   CONFIRMED    — operator approved; externalListingId written to ChannelListing
//   CONFLICT     — operator flagged a match dispute for manual resolution
//   CREATE_NEW   — operator decided to create a new Nexus product for this listing
//   IGNORE       — listing exists on channel but Nexus should not manage it
//
// One row per (channel, marketplace, externalSku). Re-running a reconciliation
// upserts on this key so historical decisions are preserved.

model ListingReconciliation {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String @id @default(cuid())
  channel     String // 'AMAZON' | 'EBAY'
  marketplace String // 'IT' | 'DE' | 'FR' | 'ES' | 'UK' ...

  // ── Channel-side data ─────────────────────────────────────────────────
  externalSku       String // SKU on the channel (Amazon seller SKU / eBay custom label)
  externalListingId String? // ASIN for Amazon, offerId for eBay
  parentAsin        String? // Amazon parent ASIN (if variation)
  title             String?
  channelPrice      Decimal? @db.Decimal(10, 2)
  channelQuantity   Int?
  channelStatus     String? // e.g. 'Active', 'Inactive', 'Incomplete'

  // ── Match result ──────────────────────────────────────────────────────
  // null = unmatched. Set after auto-match runs.
  matchedProductId   String?
  matchedVariationId String?
  matchMethod        String? // 'SKU' | 'PARENT_SKU' | 'ASIN' | 'GTIN' | 'MANUAL' | 'UNMATCHED'
  matchConfidence    Float? // 0.0 – 1.0

  // ── Operator decision ─────────────────────────────────────────────────
  reconciliationStatus String    @default("PENDING")
  conflictNotes        String?
  reviewedBy           String?
  reviewedAt           DateTime?

  // ── Import tracking ───────────────────────────────────────────────────
  runId      String // Groups rows from one reconciliation run
  importedAt DateTime? // Set when CONFIRMED and ChannelListing updated
  createdAt  DateTime  @default(now())
  updatedAt  DateTime  @updatedAt

  @@unique([workspaceId, channel, marketplace, externalSku], name: "channel_marketplace_externalSku", map: "ListingReconciliation_channel_marketplace_externalSku_key")
  @@index([channel, marketplace, reconciliationStatus])
  @@index([runId])
  @@index([matchedProductId])
  @@index([workspaceId])
}

// ── Flat-File Pull Audit (PF series) ─────────────────────────────────
// One row per "Pull from Amazon/eBay" applied inside the flat-file
// editor. Records what was pulled and how much of it the operator
// chose to apply via the diff-preview modal. Lets us answer "who
// pulled what, when, and what did they keep?" — and back the
// pull-history drawer planned for Phase 5.
//
// No FK to Product: a pull is editor-scoped (productType + sku list),
// not product-scoped. SKUs are stored as a string[] so we can reconcile
// later without joining a deleted product row.

model FlatFilePullRecord {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String @id @default(cuid())
  channel     String // 'AMAZON' (Phase 2). 'EBAY' added in Phase 3.
  marketplace String // 'IT' | 'DE' | 'FR' | 'ES' | 'UK'
  productType String

  // Source job (in-memory only) so support can correlate logs.
  jobId String?

  // Scope summary — what the user asked the pull to cover.
  skusRequested String[] @default([])
  skusReturned  Int      @default(0)

  // Result summary — what they ultimately applied via the diff modal.
  // columnsApplied stores pull-group ids: 'content' | 'pricing' |
  // 'stock' | 'images' | 'variations' | 'other' | 'all'.
  columnsApplied String[] @default([])
  rowsApplied    Int      @default(0)
  fieldsApplied  Int      @default(0)

  // null = operator cancelled the diff modal without applying.
  appliedAt DateTime?

  // Free-form operator note (Phase 5 surfaces this in the history drawer).
  operatorNote String?

  pulledAt DateTime @default(now())

  @@index([channel, marketplace, pulledAt])
  @@index([productType, pulledAt])
  @@index([workspaceId])
}

// ── Flat-File Pull Jobs (P5 persistence) ─────────────────────────────
// Mirrors the in-memory job queues in
// apps/api/src/services/amazon/flat-file-pull-preview.service.ts and
// ebay-flat-file-pull-preview.service.ts. Dual-written: the in-memory
// map stays authoritative while the job is alive, the DB row is a
// recovery surface so a browser refresh (or a server restart) doesn't
// lose a long-running pull.
//
// `rows` holds the expanded flat-file rows at completion so the diff
// modal can be re-opened from the history drawer without re-hitting
// SP-API / Sell API.
//
// Retention is implicit (no FK cascades from anywhere); a cron in a
// later phase can prune rows older than 30 days.

model FlatFilePullJob {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String    @id // jobId, e.g. 'ffpreview-…' or 'ebpreview-…'
  channel     String // 'AMAZON' | 'EBAY'
  marketplace String // 'IT' | 'DE' | 'FR' | 'ES' | 'UK'
  productType String? // null on eBay (editor isn't scoped by type)
  skus        String[]  @default([]) // requested SKU list
  status      String    @default("running") // 'running' | 'done' | 'failed'
  progress    Int       @default(0)
  total       Int       @default(0)
  pulled      Int       @default(0)
  skipped     Int       @default(0)
  failed      Int       @default(0)
  errors      Json      @default("[]") // Array<{ sku, error }>
  rows        Json      @default("[]") // FlatFileRow[] at completion (empty while running)
  startedAt   DateTime  @default(now())
  doneAt      DateTime?
  fatalError  String?

  @@index([channel, marketplace, status])
  @@index([startedAt])
  @@index([workspaceId])
}

// ── Catalog Organize (CO series) ─────────────────────────────────────
// Session-based publish + undo for /catalog/organize drag-and-drop.
// CatalogOrganizeSession groups N changes into one undoable batch.
// CatalogOrganizeChange records the before/after snapshot per product
// so Phase 5 undo can restore the prior state.

model CatalogOrganizeSession {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id            String                  @id @default(cuid())
  // PUBLISHED → UNDONE once the operator reverts all changes.
  status        String                  @default("PUBLISHED")
  publishedAt   DateTime                @default(now())
  // Undo allowed up to 48 h after publish.
  undoExpiresAt DateTime
  undoneAt      DateTime?
  changes       CatalogOrganizeChange[]
  createdAt     DateTime                @default(now())
  updatedAt     DateTime                @updatedAt

  @@index([status, createdAt])
  @@index([workspaceId])
}

model CatalogOrganizeChange {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id        String                 @id @default(cuid())
  sessionId String
  session   CatalogOrganizeSession @relation(fields: [sessionId], references: [id], onDelete: Cascade)

  // productId is a plain String FK (no Prisma relation) so we avoid
  // touching the already-large Product model.
  productId  String
  toParentId String

  // Before-state snapshot for undo
  fromParentId          String?
  fromVariantAttributes Json?

  // Variation attributes applied on publish (axis → value)
  attributes Json?

  // APPLIED → UNDONE when the operator reverts this specific change.
  status   String    @default("APPLIED")
  // OutboundSyncQueue row IDs created for this change (used in undo).
  queueIds String[]
  undoneAt DateTime?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([sessionId])
  @@index([productId])
  @@index([workspaceId])
}

// ── ES.3 — Product Read Cache ─────────────────────────────────────────
//
// Denormalized, BullMQ-refreshed read model for the /products grid.
// One row per Product. Rebuilt by the read-cache worker whenever a
// ProductEvent fires for that aggregate. Eliminates the 6-table join
// (ProductFamily, WorkflowStage, Workflow, ProductImage, ChannelListing
// _count, ProductVariation _count) that runs on every grid page load.
//
// Route logic:
//   • Cache populated (count > 0) → query ProductReadCache directly.
//   • Cache empty (first boot) → fall back to full Prisma join query.
//   • ?marketplaces= / ?missingChannels= filters still hit Prisma
//     (require ChannelListing join not stored here).
//
// cacheRefreshedAt is updated on every upsert so an admin can see
// how fresh the cache is per row.

model ProductReadCache {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id // mirrors Product.id — no FK so parent deletes don't cascade here

  // ── Core Product fields ──────────────────────────────────────────
  sku               String
  name              String
  // APS.1 — mirrors Product.amazonAsin. The ads product picker rendered an
  // Amazon badge beside a SKU and called it an ASIN because the search
  // payload never carried one; product ads, SB creatives and product
  // targets all need the real ASIN.
  asin              String?
  brand             String?
  basePrice         Decimal? @db.Decimal(10, 2)
  totalStock        Int      @default(0)
  lowStockThreshold Int?
  status            String
  syncChannels      String[]
  productType       String?
  fulfillmentMethod String?
  isParent          Boolean  @default(false)
  parentId          String?
  version           Int      @default(0)

  // ── Denormalized relations (avoids joins on read) ─────────────────
  familyId          String?
  // Shape: { id, code, label }
  familyJson        Json?
  workflowStageId   String?
  // Shape: { id, code, label, isPublishable, isTerminal, workflow: { id, code, label } }
  workflowStageJson Json?

  // ── Media ─────────────────────────────────────────────────────────
  imageUrl String?

  // ── Computed counts (replaces _count joins) ───────────────────────
  photoCount   Int @default(0)
  channelCount Int @default(0)
  variantCount Int @default(0)
  childCount   Int @default(0)

  // ── Hygiene flags (for filter chips) ──────────────────────────────
  hasDescription Boolean @default(false)
  hasBrand       Boolean @default(false)
  hasGtin        Boolean @default(false)
  hasPhotos      Boolean @default(false)

  // ── Channel keys (for marketplace filter) ─────────────────────────
  // e.g. ["AMAZON_IT", "EBAY_DE", "SHOPIFY_MAIN"]
  //
  // channelKeys        = keys from THIS row's own ChannelListings only.
  // rollupChannelKeys  = channelKeys PLUS every child's channelKeys.
  //
  // APS.1 — the rollup exists because a variation PARENT often carries no
  // Amazon listing of its own while its children do. `normal-knee-slider`
  // has channelKeys=["EBAY_IT"] and 8 children live on Amazon; filtering
  // roots on channelKeys would have hidden a family with 8 advertisable
  // ASINs. Filter marketplace-scoped PICKERS on rollupChannelKeys; keep
  // using channelKeys wherever you mean "this exact row is listed there"
  // (the /products grid's marketplace facet does, and is untouched).
  channelKeys       String[]
  rollupChannelKeys String[]

  // ── Coverage summary (for includeCoverage) ────────────────────────
  // Shape: { "AMAZON": { live, draft, error, total }, "EBAY": { ... } }
  coverageJson Json?

  // ── Product timestamps (mirrors Product) ──────────────────────────
  createdAt DateTime
  updatedAt DateTime
  deletedAt DateTime?

  // ── PIM category facets (net-new) ─────────────────────────────────
  // primaryCategoryId      = the product's isPrimary ProductCategory.
  // categoryIds            = the product's direct categories PLUS all of
  //                          their ancestor ids (the closure rollup). A
  //                          parent-category filter (`hasSome`) therefore
  //                          matches every product anywhere in the subtree
  //                          without a join. Mirrors the Typesense doc's
  //                          `categoryIds[]` so the fallback path filters
  //                          identically.
  // categoryPathJson       = localized breadcrumb labels for the primary
  //                          category. Shape: [{ id, slug, name: {en,it} }]
  primaryCategoryId String?
  categoryIds       String[]
  categoryPathJson  Json?

  // ── Cache bookkeeping ──────────────────────────────────────────────
  cacheRefreshedAt DateTime @default(now())
  // IN.4 — count of ChannelListings where any followMaster*=false
  driftCount       Int      @default(0)

  @@index([status])
  @@index([brand])
  @@index([productType])
  @@index([familyId])
  @@index([workflowStageId])
  @@index([isParent])
  @@index([parentId])
  @@index([totalStock])
  @@index([updatedAt(sort: Desc)])
  @@index([deletedAt])
  @@index([photoCount])
  @@index([channelCount])
  @@index([variantCount])
  @@index([driftCount])
  @@index([primaryCategoryId])
  @@index([asin])
  // GIN index on categoryIds[] for fast subtree (`hasSome`) filtering;
  // Prisma emits the gin operator-class index for String[] @@index.
  @@index([categoryIds], type: Gin)
  // Same shape of query (`hasSome`) drives the marketplace-scoped picker.
  @@index([rollupChannelKeys], type: Gin)
  @@index([workspaceId])
}

// ── PIM Category taxonomy (net-new) ──────────────────────────────────
//
// An internal, infinite-depth product category tree, stored as a node
// table (Category) + a closure table (CategoryClosure) for O(1)-join
// ancestor/descendant queries. This is the operator's OWN merchandising
// taxonomy — deliberately separate from `CategorySchema` (line ~5568),
// which only caches Amazon/eBay marketplace product-type attribute
// schemas.
//
// Why a closure table (vs materialized path / ltree):
//   • "all descendants of X" and "all ancestors of X" are each a single
//     indexed join — needed for subtree facet rollups and breadcrumbs.
//   • No LIKE 'path%' scans; no Postgres ltree extension dependency on
//     Neon.
//   • Product↔Category join references a stable categoryId, never an
//     encoded path string that a re-parent would have to rewrite across
//     every member product.
model Category {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  // Self-relation for the human-readable adjacency view. The closure
  // table (below) is the query workhorse; parentId is the source of
  // truth that the closure is derived from. Restrict on delete so a
  // non-empty node cannot be removed out from under its children — the
  // service surfaces a 409 and forces an explicit move/empty first.
  parentId String?
  parent   Category?  @relation("CategoryTree", fields: [parentId], references: [id], onDelete: Restrict)
  children Category[] @relation("CategoryTree")

  // Identity / ordering.
  slug      String // URL-safe segment, unique among siblings
  code      String? // optional operator-facing external reference
  sortOrder Int     @default(0)
  isActive  Boolean @default(true)
  // Denormalized tree depth (root = 0). Cheap sorting + breadcrumb hint;
  // recomputed on create/move alongside the closure rows.
  depth     Int     @default(0)

  // Localized content — reuses the per-locale JSONB convention from
  // Product.localizedContent. Shape: { "en": { ... }, "it": { ... } }.
  name        Json  @default("{\"en\":{},\"it\":{}}")
  description Json?
  // Optional category-level attribute defaults (same JSONB-attrs approach
  // as Product.categoryAttributes); inherited/merged by member products
  // at resolve time if desired.
  attributes  Json?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  // Closure rows where this node is the ancestor / the descendant.
  ancestorLinks   CategoryClosure[] @relation("CategoryAncestor")
  descendantLinks CategoryClosure[] @relation("CategoryDescendant")

  // Member products.
  products ProductCategory[]

  // PES.6 — per channel x market mapping onto the channel's own taxonomy.
  channelMappings CategoryChannelMapping[]

  @@unique([workspaceId, parentId, slug], name: "parentId_slug", map: "Category_parentId_slug_key")
  @@index([parentId])
  @@index([isActive])
  @@index([slug])
  @@index([workspaceId])
}

// One row per (ancestor, descendant) reachable pair, INCLUDING the
// self-pair at depth 0. Example for A → B → C:
//   (A,A,0) (B,B,0) (C,C,0) (A,B,1) (B,C,1) (A,C,2)
// "descendants of A"  = rows WHERE ancestorId = A   (B, C, A)
// "ancestors of C"    = rows WHERE descendantId = C (A, B, C)
model CategoryClosure {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  ancestorId   String
  descendantId String
  depth        Int // hops from ancestor → descendant (self = 0)

  ancestor   Category @relation("CategoryAncestor", fields: [ancestorId], references: [id], onDelete: Cascade)
  descendant Category @relation("CategoryDescendant", fields: [descendantId], references: [id], onDelete: Cascade)

  @@id([ancestorId, descendantId])
  @@index([descendantId])
  @@index([ancestorId, depth])
  @@index([workspaceId])
}

// Product ↔ Category membership (M:N). A product may live in several
// categories; exactly one should be flagged isPrimary (enforced in the
// service, not the schema, so bulk re-assign stays cheap).
model ProductCategory {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  productId  String
  categoryId String
  isPrimary  Boolean  @default(false)
  assignedAt DateTime @default(now())

  product  Product  @relation(fields: [productId], references: [id], onDelete: Cascade)
  category Category @relation(fields: [categoryId], references: [id], onDelete: Cascade)

  @@id([productId, categoryId])
  @@index([categoryId])
  @@index([productId, isPrimary])
  @@index([workspaceId])
}

// ── ES.1 — Immutable Product Event Log ───────────────────────────────
//
// Append-only ledger for every tracked mutation across Product,
// ChannelListing, StockLevel, and Order aggregates.
//
// Design rules:
//   • Never UPDATE or DELETE a row — only INSERT.
//   • data holds the delta (changed fields only), NOT full snapshots.
//     Keep it slim to control table growth under bulk traffic.
//   • metadata.source identifies origin so the Timeline UI can group
//     and filter flat-file imports vs operator edits vs webhooks.
//
// eventType taxonomy (strings — extensible without schema migrations):
//   PRODUCT_CREATED | PRODUCT_UPDATED | PRODUCT_DELETED
//   PRICE_CHANGED | STOCK_ADJUSTED
//   TITLE_UPDATED | BULLETS_UPDATED | DESCRIPTION_UPDATED | IMAGES_UPDATED
//   CHANNEL_LISTING_CREATED | CHANNEL_LISTING_UPDATED
//   CHANNEL_LISTING_PUBLISHED | CHANNEL_LISTING_SUPPRESSED
//   SYNC_QUEUED | SYNC_SUCCEEDED | SYNC_FAILED
//   BULK_OP_APPLIED | AUTOMATION_RULE_FIRED
//   AI_CONTENT_GENERATED | AI_CONTENT_APPROVED
//   WORKFLOW_STAGE_CHANGED | FLAT_FILE_IMPORTED
//
// metadata shape:
//   {
//     userId?:          string,
//     ip?:              string,
//     source:           "OPERATOR" | "API" | "WEBHOOK" | "AUTOMATION"
//                     | "AI" | "FLAT_FILE_IMPORT" | "SYSTEM",
//     // flat-file context (when source = FLAT_FILE_IMPORT):
//     fileName?:        string,
//     flatFileType?:    string,   // "AMAZON_INVENTORY_LOADER" | "EBAY_FLAT_FILE" | ...
//     rowIndex?:        number,
//     importJobId?:     string,
//     // batch context:
//     bulkOperationId?: string,
//     automationRuleId?: string,
//   }

// ── FNSKU Label Templates ─────────────────────────────────────────────────
// Saved label designs for printing supplier FNSKU labels.
// config JSON shape: { labelSize, logoUrl, showLogo, showSizeBox,
//   showListingTitle, showCondition, condition, rows[] }
model FnskuLabelTemplate {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id        String   @id @default(cuid())
  name      String
  isDefault Boolean  @default(false)
  config    Json
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt
  @@index([workspaceId])
}

model ProductEvent {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default(cuid())

  // Aggregate identity — plain string FKs (no Prisma relation) so we
  // never block deletes on the parent and keep this table lean.
  aggregateId   String // Product.id | ChannelListing.id | StockLevel.id | Order.id
  aggregateType String // "Product" | "ChannelListing" | "StockLevel" | "Order"

  // Event classification — see taxonomy above.
  eventType String

  // Delta payload: only the fields that changed, never a full snapshot.
  data Json?

  // Actor + origin — see metadata shape above.
  metadata Json?

  createdAt DateTime @default(now())

  // Timeline query: all events for one aggregate, newest first.
  @@index([aggregateId, createdAt(sort: Desc)])
  // Cross-aggregate feed filtered by type + time.
  @@index([aggregateType, aggregateId])
  @@index([eventType, createdAt(sort: Desc)])
  // Admin event explorer sorted by time.
  @@index([createdAt(sort: Desc)])
  @@index([workspaceId])
}

// ── PA.2 — Listing Quality Snapshot ──────────────────────────────────────
//
// Persists quality score results from listingContentService.scoreListingQuality()
// so operators can track improvement trends over time. One row per
// product × channel × scoring event (manual | publish | weekly cron).
//
// Dimensions JSON shape mirrors the scorer output:
//   { title: 80, bullets: 60, keywords: 70, images: 90, pricing: 50 }
model ListingQualitySnapshot {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id           String   @id @default(cuid())
  productId    String
  product      Product  @relation(fields: [productId], references: [id], onDelete: Cascade)
  channel      String // 'AMAZON' | 'EBAY' | 'SHOPIFY'
  marketplace  String?
  overallScore Int // 0–100
  dimensions   Json // { title, bullets, keywords, images, pricing } all 0–100
  triggeredBy  String   @default("manual") // 'manual' | 'publish' | 'cron'
  createdAt    DateTime @default(now())

  @@index([productId, channel, createdAt(sort: Desc)])
  @@index([createdAt(sort: Desc)])
  @@index([workspaceId])
}

// ── CE.4 — Smart Order Routing: RoutingDecision audit log ────────────────
//
// One row per resolveWarehouseForOrder() call. Captures which routing
// method was used (rule-match / cost-scored / fallback) and the score
// breakdown so operators can see WHY an order went to a specific warehouse
// without replaying the routing engine state.
model RoutingDecision {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id           String   @id @default(cuid())
  orderId      String
  order        Order    @relation(fields: [orderId], references: [id], onDelete: Cascade)
  warehouseId  String?
  method       String // 'rule' | 'scored' | 'fallback' | 'none'
  ruleId       String?
  // Score breakdown for 'scored' method:
  //   { warehouseId: { proximity: N, stockScore: N, total: N } }
  scoreSummary Json?
  createdAt    DateTime @default(now())

  @@index([orderId])
  @@index([createdAt(sort: Desc)])
  @@index([workspaceId])
}

// ── CE.1 — Feed Transform Engine ─────────────────────────────────────────
//
// FeedTransformRule: IF/THEN field-level rules that turn the master
// Product record into a channel-correct attribute package.
//
// Condition DSL (same operators as AutomationRule):
//   { field: 'brand', op: 'eq', value: 'Xavia' }
//   field refers to a dot-path on the Product object (brand, productType,
//   name, etc.). null condition = unconditional (always applies).
//
// Action DSL:
//   { type: 'set',      value: 'Hardcoded string' }
//   { type: 'append',   value: ' - Premium Motorcycle Gear' }
//   { type: 'prepend',  value: 'XAVIA ' }
//   { type: 'template', template: '{name} - {brand} Premium Gear' }
//   template vars: any top-level product field wrapped in {braces}.
//
// Priority: lower number = evaluated first. Rules sharing the same
// (channel, field, priority) are ordered by createdAt ascending.
// Only the first matching rule per field is applied (first-match-wins).
model FeedTransformRule {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String   @id @default(cuid())
  name        String
  description String?
  channel     String // AMAZON | EBAY | SHOPIFY | ALL
  marketplace String? // IT | DE | FR | null = all marketplaces
  field       String // target field: title | description | bullets | price | brand | etc.
  priority    Int      @default(100)
  enabled     Boolean  @default(true)
  condition   Json? // { field, op, value } — null = unconditional
  action      Json     @default("{}") // { type, value/template }
  createdBy   String?
  createdAt   DateTime @default(now())
  updatedAt   DateTime @updatedAt

  @@unique([workspaceId, name, channel, marketplace], name: "name_channel_marketplace", map: "FeedTransformRule_name_channel_marketplace_key")
  @@index([channel, field, priority])
  @@index([workspaceId])
}

// ChannelSchema: per-channel field definitions used to validate the
// transform output and drive the rule builder's field selector UI.
// Seeded by POST /api/feed-transform/seed-schemas with built-in
// Amazon/eBay/Shopify definitions; operators can add custom fields.
model ChannelSchema {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id            String  @id @default(cuid())
  channel       String // AMAZON | EBAY | SHOPIFY
  marketplace   String? // null = applies to all marketplaces for this channel
  fieldKey      String // e.g. "title", "bullet_points", "browse_node_id"
  label         String // human-readable label shown in UI
  maxLength     Int?
  required      Boolean @default(false)
  allowedValues Json? // null = free text; array of strings = enum
  notes         String?

  @@unique([workspaceId, channel, marketplace, fieldKey], name: "channel_marketplace_fieldKey", map: "ChannelSchema_channel_marketplace_fieldKey_key")
  @@index([channel, marketplace])
  @@index([workspaceId])
}

// ── HB.5 — FBA cost detail ─────────────────────────────────────────────

/// Amazon credits the seller for lost / damaged / not-returned inventory.
/// Real positive P&L line item. Source: GET_FBA_REIMBURSEMENTS_DATA.
model FbaReimbursement {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                 String   @id @default(cuid())
  reimbursementId    String // Amazon's reimbursement-id, safe upsert key
  approvalDate       DateTime
  caseId             String?
  amazonOrderId      String?
  reason             String? // free-form reason text from Amazon
  sku                String
  fnsku              String?
  asin               String?
  quantityReimbursed Int      @default(0)
  amountPerUnitCents Int      @default(0)
  totalAmountCents   Int      @default(0)
  currencyCode       String   @default("EUR")
  marketplaceId      String? // SP-API marketplaceId (e.g. APJ6JRA9NG5V4)
  createdAt          DateTime @default(now())
  updatedAt          DateTime @updatedAt

  @@index([approvalDate])
  @@index([sku])
  @@index([marketplaceId])
  @@unique([workspaceId, reimbursementId], name: "workspace_reimbursementId", map: "FbaReimbursement_workspace_reimbursementId_key")
  @@index([workspaceId])
}

/// Per-FC inventory ledger events (transfers, removals, damages, corrections).
/// Source: GET_FBA_INVENTORY_ADJUSTMENTS_DATA.
model FbaInventoryAdjustment {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                  String   @id @default(cuid())
  adjustmentId        String
  adjustedDate        DateTime
  transactionType     String // CustomerReturn / Damaged / Misplaced / etc.
  fnsku               String?
  sku                 String
  asin                String?
  quantity            Int // signed — negative for removals
  fulfillmentCenterId String?
  reasonCode          String?
  disposition         String?
  marketplaceId       String?
  createdAt           DateTime @default(now())

  @@index([adjustedDate])
  @@index([sku])
  @@index([transactionType])
  @@unique([workspaceId, adjustmentId], name: "workspace_adjustmentId", map: "FbaInventoryAdjustment_workspace_adjustmentId_key")
  @@index([workspaceId])
}

// ════════════════════════════════════════════════════════════════════
// UNIFIED MARKETING OS (UM-series, P1)
//
// Channel-agnostic Campaign abstraction spanning paid ads + promotions/
// deals + content pushes + review/email outreach, across Amazon, eBay,
// Shopify, and external networks (Google/Meta/TikTok), over all EU
// markets. Polymorphism strategy: CORE + thin per-channel DETAIL tables.
// The core row (MarketingCampaign) carries the typed columns the cockpit
// grid / calendar / automation / budgeting all read; channel-specific
// shape lives in 1:1 detail tables; vendor blobs stay as Json quarantined
// on the detail row (never on the hot core row).
//
// These tables are ADDITIVE — legacy Campaign / EbayCampaign / RetailEvent
// / BudgetPool keep running untouched during the parallel-run migration.
// Legacy stays authoritative for Amazon writes until the P8 cutover.
// ════════════════════════════════════════════════════════════════════

// Where a campaign runs. INTERNAL = content push / outreach (no external
// ad platform — delegates to the MC publish path or RV outreach pipeline).
enum MktChannel {
  AMAZON
  EBAY
  SHOPIFY
  GOOGLE
  META
  TIKTOK
  INTERNAL
}

// The concrete campaign surface within a channel. One MarketingCampaign
// is exactly one surface; the cockpit renders capability-driven tabs from
// the channel+surface pair.
enum MktSurface {
  SP // Amazon Sponsored Products
  SB // Amazon Sponsored Brands
  SD // Amazon Sponsored Display
  PROMOTED_LISTINGS // eBay Promoted Listings (STANDARD % or ADVANCED CPC)
  DISCOUNT // Shopify / generic discount code or automatic discount
  MARKDOWN // eBay markdown / price reduction promotion
  DEAL // Amazon deal / RetailEvent-anchored price action
  SHOPPING_FEED // Google Shopping / Meta catalog feed campaign
  CONTENT_PUSH // A+ Content / Brand Story / listing-copy publish
  EMAIL_OUTREACH // marketing email blast to a CustomerSegment
  REVIEW_OUTREACH // review-request campaign (RV pipeline)
}

// Why the campaign exists. Drives default bid strategy + which budget
// rebalance weighting makes sense (e.g. LIQUIDATION → URGENCY_WEIGHTED).
enum MktObjective {
  SALES
  AWARENESS
  LIQUIDATION
  NTB // new-to-brand acquisition
  TRAFFIC
  RETENTION
}

// Channel-agnostic lifecycle. Per-market delivery can still diverge —
// MarketingCampaignLink carries the per-market status/deliveryStatus.
enum MktStatus {
  DRAFT
  SCHEDULED
  ACTIVE
  PAUSED
  ENDED
  SUSPENDED
  FAILED
}

// Core channel-agnostic campaign. Subsumes legacy Campaign (Amazon),
// EbayCampaign, EbayMarkdown, and RetailEvent price actions. Denormalized
// budget/spend columns exist for the 10k-row grid; authoritative budget
// pooling lives in CampaignBudget, authoritative metrics in CampaignMetric.
// AX-IE.1 — canonical for eBay/Shopify/external/content/outreach campaigns.
// For channel=AMAZON it is a SHADOW of the legacy `Campaign` model and stays
// non-authoritative until the UM P8 cutover: those rows are written solely by
// backfillAmazonShadow (delete-then-insert, scoped to channel=AMAZON) and are only
// as fresh as its last run. Anything Amazon-ads-facing reads `Campaign`.
// See docs/CANONICAL-ADS-MODELS.md.
model MarketingCampaign {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id        String       @id @default(cuid())
  channel   MktChannel
  surface   MktSurface
  // Null until the operator picks one (drafts). Informs default strategy.
  objective MktObjective @default(SALES)

  // ── Multi-market ───────────────────────────────────────────────────
  // The markets this one logical campaign serves. A single "Black Friday
  // Helmets" campaign over IT+DE+FR is ONE row here with three
  // MarketingCampaignLink children (one external object per market).
  marketplaces       String[] @default([]) // e.g. ['IT','DE','FR'] or ['EBAY_IT']
  // Tie-breaker for currency + single-market surfaces.
  primaryMarketplace String?
  // SINGLE_MARKET = one external object; MULTI_MARKET = native multi-market
  // budget (Amazon v1) collapsed to one link with many marketplaces.
  budgetScope        String   @default("SINGLE_MARKET")

  // ── Identity / lifecycle ───────────────────────────────────────────
  name      String
  status    MktStatus @default(DRAFT)
  startDate DateTime
  endDate   DateTime?

  // ── Scope binding ──────────────────────────────────────────────────
  // ChannelConnection / AmazonAdsConnection scope. Null for multi-market
  // (per-market connections live on the links) and for INTERNAL.
  connectionId String?

  // ── Money (denormalized for grid; authoritative rows in CampaignBudget) ─
  budgetCents Int?
  // DAILY | LIFETIME | BID_PCT (eBay STANDARD) | NONE (content / outreach)
  budgetKind  String?
  currency    String   @default("EUR")
  // Aggregated spend/sales for the grid (rolled up from CampaignMetric).
  spendCents  Int      @default(0)
  salesCents  Int      @default(0)
  acos        Decimal? @db.Decimal(8, 4)
  roas        Decimal? @db.Decimal(8, 4)

  // ── Delivery (mirrors legacy Campaign.deliveryStatus) ───────────────
  deliveryStatus  String? // DELIVERING | NOT_DELIVERING
  deliveryReasons String[] @default([])

  // ── Sync bookkeeping ───────────────────────────────────────────────
  lastSyncedAt   DateTime?
  lastSyncStatus String? // PENDING | IN_PROGRESS | SUCCESS | FAILED | SKIPPED
  lastSyncError  String?

  // Free-form cockpit annotations (NOT channel payloads — those live on
  // the detail tables). Kept off the hot path by being last + nullable.
  metadata Json?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt
  createdBy String?

  // ── Relations ──────────────────────────────────────────────────────
  links           MarketingCampaignLink[]
  targets         CampaignTarget[]
  metrics         CampaignMetric[]
  actions         CampaignAction[]
  allocations     CampaignBudgetAllocation[]
  calendarEntries CalendarEntry[]

  // 1:1 per-channel detail (exactly one populated per row).
  amazonAds    AmazonAdsCampaignDetail?
  ebayPromoted EbayPromotedDetail?
  discount     DiscountDetail?
  externalAds  ExternalAdsDetail?
  contentPush  ContentPushDetail?
  outreach     OutreachDetail?

  @@index([channel, status])
  @@index([surface, status])
  @@index([primaryMarketplace, status])
  @@index([startDate, endDate])
  @@index([lastSyncStatus])
  @@index([workspaceId])
}

// Per-market external binding — the multi-market keystone. One logical
// MarketingCampaign fans out to N links; the adapter writes one external
// object per link. Per-market status/delivery/currency can diverge.
model MarketingCampaignLink {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id         String            @id @default(cuid())
  campaignId String
  campaign   MarketingCampaign @relation(fields: [campaignId], references: [id], onDelete: Cascade)

  marketplace      String // 'IT' | 'DE' | 'EBAY_IT' | 'GB' ...
  // Which ChannelConnection / AmazonAdsConnection / ad-account / profile.
  connectionId     String
  // Amazon campaignId / eBay campaign id / Shopify priceRuleId / Google
  // campaign id. Null until the create mutation succeeds.
  externalId       String?
  // Amazon portfolioId / Google campaign-group / Meta ad-set parent.
  externalParentId String?

  status         String    @default("DRAFT")
  currency       String    @default("EUR")
  deliveryStatus String?
  lastSyncedAt   DateTime?
  lastSyncStatus String?
  lastSyncError  String?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@unique([workspaceId, campaignId, marketplace], name: "campaignId_marketplace", map: "MarketingCampaignLink_campaignId_marketplace_key")
  @@unique([workspaceId, externalId, marketplace], name: "externalId_marketplace", map: "MarketingCampaignLink_externalId_marketplace_key")
  @@index([marketplace, status])
  @@index([workspaceId])
}

// ── Per-channel 1:1 detail tables ─────────────────────────────────────

// Amazon SP/SB/SD specifics. Migration target for everything on legacy
// Campaign that isn't core. Legacy AdGroup/AdTarget/AdProductAd remain the
// Amazon-only sub-tree (no cross-channel analog) and re-parent here in P2.
// ⚠️ AX-IE.1 — SHADOW, not authoritative. See docs/CANONICAL-ADS-MODELS.md.
// Canonical Amazon campaign state is the legacy `Campaign` model (196 live rows,
// read by all 276 advertising routes and the entire write path). This table has
// ZERO code references anywhere in apps/api, apps/web or packages — it is populated
// only by backfillAmazonShadow as part of the UM cross-channel migration and stays
// non-authoritative until the UM P8 cutover. Do not read it for Amazon facts and
// never hand-write it: the backfill is delete-then-insert scoped to channel=AMAZON.
model AmazonAdsCampaignDetail {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id         String            @id @default(cuid())
  campaignId String            @unique
  campaign   MarketingCampaign @relation(fields: [campaignId], references: [id], onDelete: Cascade)

  // SPONSORED_PRODUCTS | SPONSORED_BRANDS | SPONSORED_DISPLAY | SPONSORED_TELEVISION
  adProduct             String
  profileId             String?
  portfolioId           String?
  bidStrategyJson       Json? // SP: { strategy, adjustments[] }
  dynamicBidding        Json? // SP placement bid adjustments
  tactic                String? // SD: T00020 (product) | T00030 (audience)
  costType              String? // SD: cpc | vcpm
  deliveryProfileNative String? // SD pacing profile
  creativeAssetJson     Json? // SB creative envelope
  brandEntityId         String? // SB brand registry binding

  @@index([adProduct])
  @@index([profileId])

  @@index([workspaceId])
}

// eBay Promoted Listings specifics. Migration target for EbayCampaign.
model EbayPromotedDetail {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id         String            @id @default(cuid())
  campaignId String            @unique
  campaign   MarketingCampaign @relation(fields: [campaignId], references: [id], onDelete: Cascade)

  // STANDARD = bid % of sale; ADVANCED = daily CPC budget.
  fundingStrategy     String   @default("STANDARD")
  bidPercentage       Decimal? @db.Decimal(5, 2)
  channelConnectionId String?

  @@index([fundingStrategy])

  @@index([workspaceId])
}

// Discount / deal / markdown specifics — serves Shopify discounts, eBay
// markdowns, and Amazon DEAL price actions. Migration target for
// EbayMarkdown + RetailEventPriceAction.
model DiscountDetail {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id         String            @id @default(cuid())
  campaignId String            @unique
  campaign   MarketingCampaign @relation(fields: [campaignId], references: [id], onDelete: Cascade)

  discountType       String // PERCENTAGE | FIXED | BXGY | SHIPPING
  discountValueCents Int?
  discountPercent    Decimal? @db.Decimal(5, 2)
  // ALL | COLLECTION | PRODUCT | LISTING
  appliesTo          String   @default("ALL")
  appliesToRefs      String[] @default([]) // collection/product/listing ids
  combinesWith       String[] @default([]) // Shopify combine rules
  usageLimit         Int?
  // External binding for the platform-native object (Shopify priceRuleId,
  // discountCodeId; eBay externalPromotionId).
  priceRuleId        String?
  discountCodeId     String?

  @@index([discountType])

  @@index([workspaceId])
}

// External ad-network specifics (Google Ads / Meta / TikTok). Creative
// refs point at DAM assets (APlusContent / BrandStory / ProductImage).
model ExternalAdsDetail {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id         String            @id @default(cuid())
  campaignId String            @unique
  campaign   MarketingCampaign @relation(fields: [campaignId], references: [id], onDelete: Cascade)

  platform           String // GOOGLE | META | TIKTOK
  accountId          String?
  objectiveNative    String? // platform-native objective string
  optimizationGoal   String?
  creativeRefs       String[] @default([])
  platformConfigJson Json? // raw platform request/response envelope

  @@index([platform])

  @@index([workspaceId])
}

// Content-push specifics — A+ Content / Brand Story / listing-copy publish.
// Delegates to the MC publish path at apply time (InternalAdapter, P10).
model ContentPushDetail {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id         String            @id @default(cuid())
  campaignId String            @unique
  campaign   MarketingCampaign @relation(fields: [campaignId], references: [id], onDelete: Cascade)

  contentType    String // APLUS | BRAND_STORY | LISTING_COPY
  aPlusContentId String?
  brandStoryId   String?
  // Target ASIN / listing set this push applies to.
  targetRefs     String[] @default([])

  @@index([contentType])

  @@index([workspaceId])
}

// Outreach specifics — marketing email / review-request blast to a
// CustomerSegment audience. Honors EmailSuppression at send time (P10).
model OutreachDetail {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id         String            @id @default(cuid())
  campaignId String            @unique
  campaign   MarketingCampaign @relation(fields: [campaignId], references: [id], onDelete: Cascade)

  mode       String // EMAIL | REVIEW
  segmentId  String? // → CustomerSegment
  templateId String?

  @@index([mode])

  @@index([workspaceId])
}

/// AX-ZD.1 — a typed record of one intended field change on one ad entity.
///
/// Ad writes ride OutboundSyncQueue, a product/listing model with no campaign,
/// ad-group or target FK — the entity and the changed fields sit inside a JSON
/// payload. That is why the drift check's pending-write lookup is a
/// campaign-wide JSON scan: one queued mutation marks EVERY drifting field on
/// that campaign as WRITE_PENDING, hiding a real Seller Central edit.
///
/// ADDITIVE for now. OutboundSyncQueue remains the dispatch path with its
/// grace period, dead-lettering and write gate untouched; this is written
/// alongside it so the typed record exists to be READ from. Moving dispatch is
/// a separate, verifiable step.
model AdMutation {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id               String    @id @default(cuid())
  /// CAMPAIGN | AD_GROUP | AD_TARGET | PRODUCT_AD
  entityType       String
  entityId         String
  externalEntityId String?
  profileId        String?
  marketplace      String?
  /// The single field this row intends to change. The point of the model.
  field            String
  intendedValue    String?
  previousValue    String?
  /// PENDING | IN_FLIGHT | APPLIED | FAILED | CANCELLED | SUPERSEDED
  state            String    @default("PENDING")
  attempts         Int       @default(0)
  lastError        String?
  changeSetId      String?
  importJobId      String?
  ruleId           String?
  actor            String
  idempotencyKey   String?
  holdUntil        DateTime?
  /// The OutboundSyncQueue row that actually dispatches this, while it still does.
  outboundQueueId  String?
  createdAt        DateTime  @default(now())
  updatedAt        DateTime  @updatedAt
  settledAt        DateTime?

  @@index([entityType, entityId, field, state])
  @@index([entityType, entityId, state])
  @@index([changeSetId])
  @@index([state, holdUntil])
  @@index([workspaceId])
}

/// AX2.5 — one replication run: applying a blueprint to one product. Recorded
/// so the run can be rolled back as a single unit instead of hunting orphaned
/// entities, and so a PARTIAL outcome stays legible (`notOnAmazon` lists
/// campaigns that landed locally but never reached Amazon).
model AdBlueprintApplication {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                 String    @id @default(cuid())
  /// AX3.4 — null when the run replicated a LIVE source (a portfolio, some
  /// campaigns, or single ad groups) rather than a saved blueprint. Saving a
  /// blueprint is an optional action at the end of the builder, not a
  /// precondition for replicating.
  blueprintId        String?
  productToken       String
  marketplace        String
  asins              String[]  @default([])
  /// PLANNED | APPLIED | PARTIAL | FAILED | ROLLED_BACK
  status             String    @default("PLANNED")
  plan               Json
  acceptedConflicts  String[]  @default([])
  skippedTargets     String[]  @default([])
  createdCampaignIds String[]  @default([])
  notOnAmazon        String[]  @default([])
  errors             String[]  @default([])
  actor              String?
  createdAt          DateTime  @default(now())
  appliedAt          DateTime?
  rolledBackAt       DateTime?

  /// AX3.4 — what was replicated: { portfolioId | campaignIds | adGroupIds |
  /// namePrefix, marketplace }. Lets a run be explained and repeated later.
  sourceSelector Json?
  /// AX3.4 — the naming rules, copy scope and bid/budget policies chosen.
  /// Without these, "why is this campaign called that" is unanswerable later.
  options        Json?
  /// AX3.4 — the step-2 edit set that was applied on top of the plan.
  edits          Json?
  /// AX3.5 — 'live' | 'floor'. Whether the run went out at its planned bids or
  /// landed at Amazon's 2c floor. A money fact; it belongs on the record.
  launchMode     String?

  /// AX3.8 — live progress while the run is executing: { step, done, total,
  /// campaign, created:{...} }.
  ///
  /// A replication is hundreds of sequential Amazon calls and takes minutes. It
  /// used to run inside the HTTP request, so the edge proxy cut the connection
  /// and the browser said "Failed to fetch" while the server carried on and
  /// created ten live campaigns nobody could see. The run is now detached and
  /// this column is how it is watched — and how a reconnecting browser finds a
  /// run already in flight instead of starting a second one.
  progress  Json?
  /// AX3.8 — set when execution begins, so a RUNNING row that stops advancing
  /// can be told apart from one that never started.
  startedAt DateTime?

  @@index([blueprintId])
  @@index([status])
  /// AX3.8 — "is a run already in flight for this product?" on every launch.
  @@index([marketplace, productToken, status])
  @@index([workspaceId])
}

/// AX2.4 — a named, product-agnostic campaign structure extracted from live
/// campaigns, with ASINs, brand keywords and name tokens parameterised out.
/// `doc` holds the BlueprintDoc from ads-core/ads-blueprint.ts, including the
/// `sharedTargets` list — the exact keywords that would make two of our own
/// products bid against each other if the structure were replicated verbatim.
/// Read side only: nothing here creates anything on Amazon.
/// ADX A1 — keyword protection. The counterpart to the bid bounds on Campaign:
/// bounds protect the money, this protects the targeting.
///
/// WHITELIST = never negate this term. Harvest-and-negate automation without a
/// whitelist is dangerous, and ours ran enabled with nothing protecting a brand
/// term from being negated by it. Scale Insights ships Whitelist and Blacklist as
/// two of its eleven named algorithms for exactly this reason.
///
/// BLACKLIST = always negate this term, everywhere, regardless of performance.
///
/// Matching is on the lowercased, whitespace-collapsed term. `isPrefix` widens it
/// to a prefix match so "xavia" can protect every branded variant without listing
/// them. Scope narrows by marketplace and/or campaign; both null = account-wide.
///
/// Enforced in ads-write-gate.ts, the single chokepoint every write passes through,
/// so no engine can bypass it by forgetting to check.
model AdKeywordProtection {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String   @id @default(cuid())
  /// WHITELIST | BLACKLIST
  mode        String
  /// Lowercased, whitespace-collapsed match text.
  term        String
  /// Legacy flag, kept so existing rows keep working. `matchType` supersedes it.
  isPrefix    Boolean  @default(false)
  /// EXACT | PREFIX | CONTAINS.
  ///
  /// CONTAINS exists because brand protection needs it and the other two cannot do it:
  /// Amazon hands back search terms like "giacca moto xavia", which neither equals
  /// "xavia" nor starts with it. A prefix-only whitelist would have looked like it was
  /// protecting the brand while silently missing every term where the brand is not the
  /// first word — the majority of them.
  ///
  /// Null falls back to isPrefix, so rows written before this column behave unchanged.
  matchType   String?
  /// null = every marketplace.
  marketplace String?
  /// null = every campaign.
  campaignId  String?
  reason      String?
  createdBy   String?
  createdAt   DateTime @default(now())
  updatedAt   DateTime @updatedAt

  @@index([mode, term])
  @@index([marketplace])
  @@index([campaignId])
  @@index([workspaceId])
}

/// NEG.5 — the operator's "this contradiction is deliberate" mark.
///
/// 🔴 A SEPARATE TABLE ON PURPOSE. The obvious place for this is a campaign-scoped row on
/// `AdKeywordProtection`, and that would be wrong in a way nothing would report. That table has
/// seven production readers and two of them — `share-of-voice.service.ts:347` and
/// `keyword-watchlist.service.ts:66` — treat a WHITELIST row as *the account's definition of a
/// brand term*, selecting only `term/matchType/isPrefix/marketplace` and **never `campaignId`**.
/// An exemption filed there would be silently read account-wide as "this is one of our brands".
/// Worse, `ads-write-gate.ts:308-313` ANDs `campaignId IS NULL OR campaignId = ctx.campaignId`,
/// which NARROWS a protection to one campaign rather than exempting that campaign from it — the
/// exact inverse of the mark's meaning.
///
/// Grain: **(protected term × campaign)**, not one row per negation. The operator's decision is
/// architectural — "brand traffic belongs out of the AIRMESH catch-all and in the house campaign"
/// — not a judgement about one negation row. Per-row marking would need 132 decisions and would
/// re-alarm every time a new negation of the same term landed in the same campaign.
///
/// The cost of that grain, which the UI must state rather than hide: one decision covers every
/// current AND FUTURE negation of that term in that campaign. So the audit surfaces "N new since
/// this decision" instead of silently absorbing them — a mark that quietly swallows new rows is
/// how an audit stops being one.
model AdNegativeReview {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id            String   @id @default(cuid())
  /// The whitelisted term this decision concerns, normalised the way the gate normalises
  /// (`ads-write-gate.ts:normaliseTerm`) so the audit and the enforcement cannot disagree.
  protectedTerm String
  /// Local `Campaign.id`. Not nullable: an account-wide "always fine" is not a decision an
  /// operator can defend, and it would blank the audit in one click.
  campaignId    String
  /// INTENDED_FUNNEL is the only value today. A string rather than an enum because the second
  /// value is not yet known and an enum migration is a schema change, not a data one.
  decision      String
  reason        String?
  reviewedBy    String?
  reviewedAt    DateTime @default(now())

  @@unique([workspaceId, protectedTerm, campaignId], name: "protectedTerm_campaignId", map: "AdNegativeReview_protectedTerm_campaignId_key")
  @@index([campaignId])
  @@index([workspaceId])
}

model AdBlueprint {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                String   @id @default(cuid())
  name              String
  description       String?
  marketplace       String
  adProduct         String   @default("SPONSORED_PRODUCTS")
  productToken      String
  competitorTokens  String[] @default([])
  sourceCampaignIds String[] @default([])
  doc               Json
  createdBy         String?
  createdAt         DateTime @default(now())
  updatedAt         DateTime @updatedAt

  @@index([marketplace])
  @@unique([workspaceId, name], name: "workspace_name", map: "AdBlueprint_workspace_name_key")
  @@index([workspaceId])
}

// Channel-agnostic targeting/audience row. Generalizes legacy AdTarget +
// CustomerSegment audience binding. Amazon ad-groups/product-ads stay as
// an Amazon-only sub-tree (legacy AdGroup/AdProductAd), NOT here.
//
// ⚠️ AX2.2 — DEAD MODEL. Verified 2026-07-28: 0 rows, and ZERO code references
// (`prisma.campaignTarget.` appears nowhere in apps/api or apps/web — the
// `CampaignTargeting` hits are an unrelated self-competition interface).
// Amazon targeting lives entirely in AdTarget (4,415 rows). Do NOT write here;
// a second target model read by one path and written by another is exactly the
// two-of-everything hazard. Dropping the table is a destructive migration and
// is deliberately left for a separate gate.
model CampaignTarget {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id         String            @id @default(cuid())
  campaignId String
  campaign   MarketingCampaign @relation(fields: [campaignId], references: [id], onDelete: Cascade)

  // KEYWORD | PRODUCT | CATEGORY | AUDIENCE | SEGMENT | COLLECTION | ASIN_SET | LOOKALIKE
  kind             String
  expressionType   String? // EXACT | PHRASE | BROAD | ASIN | CATEGORY_REFINEMENT | native
  expressionValue  String
  isNegative       Boolean @default(false)
  negativeLevel    String? // CAMPAIGN | AD_GROUP
  // → CustomerSegment for outreach / Meta custom-audience targets.
  segmentId        String?
  bidCents         Int?
  marketplace      String? // a target can be market-scoped
  externalTargetId String?

  // Metrics roll up here for the per-target grid (Amazon reports at this grain).
  impressions Int @default(0)
  clicks      Int @default(0)
  spendCents  Int @default(0)
  salesCents  Int @default(0)
  ordersCount Int @default(0)

  status    String   @default("ENABLED")
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([campaignId, kind])
  @@index([campaignId, isNegative])
  @@index([externalTargetId])
  @@index([workspaceId])
}

// Cross-channel budget pool. Generalizes legacy BudgetPool (which was
// intra-Amazon only) so a pool can span Amazon SP + eBay Promoted +
// Google. Guardrails (cooldown, max-shift %, dry-run) lifted verbatim.
//
// AX-IE.1 — deliberately NOT resolved against BudgetPool*. Both pairs are EMPTY
// (0 rows) with live code paths: BudgetPool* serves the Amazon ads routes and the
// rebalance cron, CampaignBudget* serves marketing-os. With no data on either side
// there is nothing to disagree and nothing to migrate, so picking a winner today
// would be pure risk. Amazon-scoped pooling stays on BudgetPool*; this is the
// cross-channel successor to adopt at UM P8. See docs/CANONICAL-ADS-MODELS.md.
model CampaignBudget {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id              String  @id @default(cuid())
  name            String
  description     String?
  // CAMPAIGN = a single campaign's budget; POOL = shared across many.
  scope           String  @default("POOL")
  currency        String  @default("EUR")
  totalDailyCents Int
  // STATIC | PROFIT_WEIGHTED | URGENCY_WEIGHTED | ROAS_WEIGHTED
  strategy        String  @default("STATIC")

  // Guardrails (proven model from BudgetPool).
  coolDownMinutes         Int       @default(60)
  maxShiftPerRebalancePct Int       @default(20)
  enabled                 Boolean   @default(false)
  dryRun                  Boolean   @default(true)
  lastRebalancedAt        DateTime?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt
  createdBy String?

  allocations CampaignBudgetAllocation[]
  rebalances  CampaignBudgetRebalance[]

  @@index([enabled, lastRebalancedAt])
  @@index([workspaceId])
}

// One campaign membership in a cross-channel budget pool. campaignId is
// DB-unique across ALL allocations so two pools can't fight over the same
// campaign's budget.
model CampaignBudgetAllocation {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id          String            @id @default(cuid())
  budgetId    String
  budget      CampaignBudget    @relation(fields: [budgetId], references: [id], onDelete: Cascade)
  campaignId  String
  campaign    MarketingCampaign @relation(fields: [campaignId], references: [id], onDelete: Cascade)
  // Channel + marketplace denormalized from the linked campaign for query speed.
  channel     MktChannel
  marketplace String?

  targetSharePct      Decimal @default(0) @db.Decimal(5, 2)
  minDailyBudgetCents Int     @default(100)
  maxDailyBudgetCents Int?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@unique([campaignId])
  @@index([budgetId])
  @@index([channel, marketplace])
  @@index([workspaceId])
}

// Append-only rebalance audit. Mirrors BudgetPoolRebalance.
model CampaignBudgetRebalance {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id              String         @id @default(cuid())
  budgetId        String
  budget          CampaignBudget @relation(fields: [budgetId], references: [id], onDelete: Cascade)
  triggeredBy     String // 'cron' | 'rule:<id>' | 'user:<id>'
  inputs          Json
  outputs         Json
  dryRun          Boolean
  appliedAt       DateTime?
  totalShiftCents Int            @default(0)
  createdAt       DateTime       @default(now())

  @@index([budgetId, createdAt(sort: Desc)])
  @@index([workspaceId])
}

// Unified daily performance time-series across ALL channels. Modeled on
// AmazonAdsDailyPerformance (costMicros BigInt + currencyCode + windowed
// sales) PLUS costEurCents — an FX-normalized (frozen-rate-at-ingest)
// column so cross-channel rollups sum a single currency. Cross-channel
// ROAS is labeled "channel-reported" in the UI — attribution differs.
//
// ⚠️ AX-IE.1 — MIXED authority, read docs/CANONICAL-ADS-MODELS.md before using.
//   • eBay rows: CANONICAL. Real writers (ebay-ads-reports, ebay-backfill).
//   • AMAZON rows: SHADOW of AmazonAdsDailyPerformance, written only by
//     backfillAmazonShadow. Never source an Amazon ads number from here — the
//     ads cockpit, exports and rules all read AmazonAdsDailyPerformance.
model CampaignMetric {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id         String             @id @default(cuid())
  // Null when only the external entity is known (pre-link metrics).
  campaignId String?
  campaign   MarketingCampaign? @relation(fields: [campaignId], references: [id], onDelete: SetNull)
  linkId     String? // → MarketingCampaignLink (per-market grain)

  channel       MktChannel
  marketplace   String
  date          DateTime   @db.Date
  // CAMPAIGN | TARGET | AD_GROUP | PRODUCT | SEARCH_TERM | DISCOUNT_CODE | EMAIL_SEND
  entityType    String
  entityId      String // external id
  localEntityId String?

  // Universal
  impressions  Int     @default(0)
  clicks       Int     @default(0)
  costMicros   BigInt  @default(0)
  currencyCode String
  // FX-normalized cost (frozen FxRate at ingest) — the column cross-channel
  // analytics sums. Native costMicros+currencyCode stays audit-faithful.
  costEurCents BigInt?

  // Conversion (windowed where the channel supports it; single-value otherwise)
  sales7dCents        Int?  @default(0)
  sales14dCents       Int?  @default(0)
  sales30dCents       Int?  @default(0)
  orders7d            Int?  @default(0)
  units7d             Int?  @default(0)
  // Channel extras (SB/SD new-to-brand, viewability, content/outreach opens).
  ntbOrders14d        Int?
  viewableImpressions Int?
  detailPageViews7d   Int?
  extra               Json?

  // How sales are attributed for this channel — labels cross-channel ROAS.
  attributionModel String?
  acos7d           Decimal? @db.Decimal(8, 4)
  roas7d           Decimal? @db.Decimal(8, 4)

  reportRunId String?
  reportedAt  DateTime
  createdAt   DateTime @default(now())

  @@unique([workspaceId, channel, entityType, entityId, date], name: "channel_entityType_entityId_date", map: "CampaignMetric_channel_entityType_entityId_date_key")
  @@index([campaignId, date])
  @@index([marketplace, date, channel])
  @@index([linkId, date])
  @@index([workspaceId])
}

// Unified write audit + rollback log. Generalizes AdvertisingActionLog
// across channels. Append-only. executionId links to an automation rule
// run; outboundQueueId links to the OutboundSyncQueue row the action
// enqueued. rollback.service reverses by replaying payloadBefore.
model CampaignAction {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                    String             @id @default(cuid())
  campaignId            String?
  campaign              MarketingCampaign? @relation(fields: [campaignId], references: [id], onDelete: SetNull)
  // Set when triggered by an automation rule (SetNull on rule delete).
  executionId           String?
  userId                String? // operator id when human-triggered
  channel               MktChannel
  actionType            String // set_campaign_budget | pause_campaign | create_deal | launch_content_push | ...
  // CAMPAIGN | TARGET | BUDGET | DISCOUNT | EXTERNAL_AD | CONTENT | OUTREACH
  entityType            String
  entityId              String
  payloadBefore         Json
  payloadAfter          Json
  outboundQueueId       String?
  channelResponseId     String?
  channelResponseStatus String? // SUCCESS | FAILED | PENDING
  rolledBackAt          DateTime?
  rollbackReason        String?
  createdAt             DateTime           @default(now())

  @@index([executionId, createdAt(sort: Desc)])
  @@index([entityType, entityId, createdAt(sort: Desc)])
  @@index([campaignId, createdAt(sort: Desc)])
  @@index([createdAt(sort: Desc)])
  @@index([workspaceId])
}

// Shared marketing calendar view-model. Scheduling a campaign auto-creates
// an entry; operators can also drop free-floating notes/milestones.
// retailEventId anchors an entry to a known RetailEvent (Black Friday),
// which renders as a background band with its expectedLift nudge.
model CalendarEntry {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id            String             @id @default(cuid())
  campaignId    String?
  campaign      MarketingCampaign? @relation(fields: [campaignId], references: [id], onDelete: Cascade)
  retailEventId String?

  kind         String // CAMPAIGN | DEAL | CONTENT_DROP | OUTREACH | MILESTONE | NOTE
  title        String
  channel      MktChannel?
  marketplaces String[]    @default([])
  startsAt     DateTime
  endsAt       DateTime?
  status       String      @default("PLANNED")
  color        String? // operator-set band color (AG-series palette convention)
  notes        String?

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt
  createdBy String?

  @@index([startsAt, endsAt])
  @@index([campaignId])
  @@index([retailEventId])
  @@index([workspaceId])
}

// ════════════════════════════════════════════════════════════════════
// AX.9 — Dayparting / ad scheduling. A campaign runs (ENABLED) only
// during its active day×hour windows; the ad-dayparting cron pauses it
// outside them and re-enables inside — "bid/run when likely to convert".
// References Campaign by id (no Prisma relation, to keep this additive).
// ════════════════════════════════════════════════════════════════════
model AdSchedule {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id               String             @id @default(cuid())
  campaignId       String // local Campaign.id
  name             String
  // Active windows the campaign SHOULD deliver in. JSON:
  // [{ days:[0-6], startHour:0-23, endHour:0-23, bidMultiplierPct?:number, targetKey?:string }]
  // bidMultiplierPct: +30 raises bids 30% on window-enter, restores on exit (legacy intensity mode).
  // RS.1 — targetKey: references a RankTarget.key (goal mode); the engine holds that
  // target's impression-share during the window. A window may carry either form.
  // Empty = always on (no-op schedule).
  windows          Json               @default("[]")
  timezone         String             @default("Europe/Rome")
  enabled          Boolean            @default(true)
  // RS.1 — baseline RankTarget.key for time OUTSIDE every window ("for the rest, hold Y").
  // null = legacy behaviour (no baseline; gaps mean paused).
  defaultTargetKey String?
  // Last status the cron applied, to avoid redundant writes/churn.
  // TWO writers, and they mean different things — read it alongside the row's mode:
  //  · ad-dayparting (classic bidMultiplierPct mode) writes 'ENABLED' | 'PAUSED'.
  //  · ad-rank-defend (goal mode) writes the resolved RankTarget.key it is holding
  //    ('own-top', 'defend-top', …), or null when nothing was due that tick — RDX/A1.
  // Every live row is goal mode, so in practice this holds a target key. Treat it as an
  // opaque label; never branch on it without checking isGoalMode(windows, defaultTargetKey).
  lastApplied      String?
  lastEvaluatedAt  DateTime?
  // AU.3 — bid snapshot taken when entering a bid-multiplier window.
  // JSON: { [adTargetId]: originalBidCents }. Cleared when exiting/restoring.
  originalBids     Json?
  // RTC — per-campaign target overrides: { targetKey: { biasPct?, targetISPct?, acosCapPct?, maxCpcCents? } }
  targetOverrides  Json               @default("{}")
  createdAt        DateTime           @default(now())
  updatedAt        DateTime           @updatedAt
  createdBy        String?
  // Phase 2 (rank-schedule groups) — binds this execution row to a named RankScheduleGroup so one
  // named schedule can span many campaigns. The rank-defend cron still reads per-campaign rows;
  // groupId is metadata for the management/authoring layer only (cron untouched).
  groupId          String?
  group            RankScheduleGroup? @relation(fields: [groupId], references: [id], onDelete: SetNull)

  // C2b — ONE CAMPAIGN, ONE SCHEDULE, enforced by the database rather than by convention.
  // saveRankScheduleGroup already assumes it: it does findFirst({ where: { campaignId } }) and
  // rebinds whatever it finds, so a second row for the same campaign would be silently hijacked
  // and two crons could hold the same campaign to different ranks. The integrity check detects
  // that; this makes it impossible.
  // Also means one campaign cannot hold BOTH a classic dayparting row and a rank row — which the
  // save path could not have handled correctly anyway.
  @@unique([workspaceId, campaignId], name: "workspace_campaignId", map: "AdSchedule_campaignId_key")
  @@index([enabled])
  @@index([groupId])
  @@index([workspaceId])
}

// Phase 2 — named rank-schedule group: the management/authoring layer over a set of campaigns.
// One group = one row in the Dayparting Schedules list; its member AdSchedule rows (via groupId)
// remain the per-campaign execution layer the rank-defend cron already runs (engine untouched).
model RankScheduleGroup {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id               String                @id @default(cuid())
  name             String // compulsory (validated at the API/UI layer, Phase 3)
  marketplace      String?
  timezone         String                @default("Europe/Rome")
  windows          Json                  @default("[]") // canonical windows (authoring source of truth)
  defaultTargetKey String? // canonical baseline RankTarget.key
  targetOverrides  Json                  @default("{}") // per-campaign overrides { campaignId: { targetKey: {...} } }
  portfolioId      String? // Phase 5 — portfolio-scoped group (auto-includes the portfolio's campaigns)
  enabled          Boolean               @default(true)
  createdAt        DateTime              @default(now())
  updatedAt        DateTime              @updatedAt
  createdBy        String?
  schedules        AdSchedule[]
  versions         RankScheduleVersion[]
  events           RankScheduleEvent[]

  @@index([marketplace])
  @@index([workspaceId])
}

// G1 — a DATED override on a rank schedule: Black Friday, Prime Day, a launch week.
//
// The weekly plan answers "what do we do every Tuesday". This answers "what do we do on THESE
// dates instead", which the weekly grid cannot express at all — today the only way to run an event
// is to hand-edit the plan and remember to hand-revert it, and forgetting the revert is how an
// all-out Black Friday plan quietly runs through December.
//
// Lead-in / event / lead-out is expressed as SEPARATE rows rather than one object with three
// phases: the phases have different plans and different lengths, they are frequently adjusted
// independently, and modelling them as one row would force every edit to touch all three.
model RankScheduleEvent {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id               String            @id @default(cuid())
  groupId          String
  group            RankScheduleGroup @relation(fields: [groupId], references: [id], onDelete: Cascade)
  name             String
  // Absolute instants. The schedule's own timezone decides which local hours these cover, so an
  // event authored for Rome does not silently shift when read from another zone.
  startsAt         DateTime
  endsAt           DateTime
  // Same shape as the weekly plan, so the engine's window resolution is reused unchanged rather
  // than reimplemented for events.
  windows          Json              @default("[]")
  defaultTargetKey String?
  // Off by default is deliberate: an event is authored ahead of time, and arming it early is
  // exactly the mistake this feature exists to prevent.
  enabled          Boolean           @default(false)
  createdBy        String?
  createdAt        DateTime          @default(now())
  updatedAt        DateTime          @updatedAt

  @@index([groupId, startsAt])
  @@index([enabled, startsAt, endsAt])
  @@index([workspaceId])
}

// HX.8 — plan-edit history for a rank schedule.
//
// Distinct from the ACTIVITY trail (CampaignBidHistory / AdvertisingActionLog), which records what
// the ENGINE did to Amazon. This records what the OPERATOR did to the plan: which windows moved,
// when, and by whom. Without it `saveRankScheduleGroup` overwrites `windows` in place and the
// question "what changed, and when did this schedule start behaving differently" is unanswerable.
//
// Append-only snapshot, written on save only when something meaningful actually differs from the
// latest version — a re-save that changes nothing must not manufacture a version.
model RankScheduleVersion {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id               String            @id @default(cuid())
  groupId          String
  group            RankScheduleGroup @relation(fields: [groupId], references: [id], onDelete: Cascade)
  // The plan as it stood AFTER this save. Diffing is done against the previous row.
  name             String
  windows          Json              @default("[]")
  defaultTargetKey String?
  // Member count at the time, so "went from 11 campaigns to 1" is visible without storing the ids.
  campaignCount    Int               @default(0)
  enabled          Boolean           @default(true)
  changedBy        String?
  createdAt        DateTime          @default(now())

  @@index([groupId, createdAt(sort: Desc)])
  @@index([workspaceId])
}

// BS — Budget Schedule (Helium 10 "Budget Schedules" tab). An hourly/daily schedule that
// adjusts the daily budget (CAMPAIGN_BUDGET) or a budget multiplier (BUDGET_MULTIPLIER) of the
// selected campaigns. `kind` is reserved so the sibling Dayparting builder can share this table.
model BudgetSchedule {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id              String    @id @default(cuid())
  name            String
  kind            String    @default("BUDGET") // BUDGET | DAYPARTING (future)
  type            String    @default("CAMPAIGN_BUDGET") // CAMPAIGN_BUDGET (hourly €) | BUDGET_MULTIPLIER (daily ×)
  // Campaigns this schedule applies to: [{ id, name, marketplace?, adProduct?, dailyBudget? }]
  campaigns       Json      @default("[]")
  // Per-day windows + adjustment: [{ day:0-6, start:"HH:MM", end:"HH:MM", adj, value }]
  windows         Json      @default("[]")
  timezone        String    @default("Europe/Rome")
  // Chart prefs: { metric1, metric2, groupBy, daysFilter }
  chartPrefs      Json      @default("{}")
  startDate       DateTime?
  endDate         DateTime?
  neverExpire     Boolean   @default(true)
  excludeDates    Json      @default("[]") // [{ start, end }] blackout ranges
  autoRefill      Boolean   @default(false)
  enabled         Boolean   @default(true)
  // Apply-engine churn guard: { [campaignId]: { budgetCents | multiplier, at } }
  lastApplied     Json?
  lastEvaluatedAt DateTime?
  createdAt       DateTime  @default(now())
  updatedAt       DateTime  @updatedAt
  createdBy       String?

  @@index([enabled])
  @@index([kind])
  @@index([workspaceId])
}

// AC — AI Control / Autopilot. One plan governs a set of campaigns from a single GOAL +
// guardrails; the Conductor (ad-autopilot.job) drives the existing control arsenal (bid,
// budget, placement, rank, dayparting) within those guardrails, and COORDINATES the parallel
// Rule-Setting session's harvest/negate engine (configures + reads it, never reimplements).
// See docs/ai-control-autopilot-spec.md.
model AutopilotPlan {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id               String    @id @default(cuid())
  name             String
  marketplace      String
  productGroupName String? // ties back to the SP Super Wizard launch
  campaignIds      Json      @default("[]") // local Campaign.id[] under control
  goal             String    @default("BALANCED") // LAUNCH | PROFIT | BALANCED | LIQUIDATE | DEFEND_RANK
  autonomy         String    @default("SUGGEST") // OFF | SUGGEST | AUTO
  // {targetAcosPct,bidMinCents,bidMaxCents,budgetMinCents,budgetMaxCents,maxDailySpendCents,rampPct,neverPause}
  guardrails       Json      @default("{}")
  // per-module {on, params}: bid/budget/dayparting/rank/placement (ours) + harvest/negate (delegated)
  modules          Json      @default("{}")
  graph            Json      @default("{}") // React Flow {nodes,edges} canvas persistence
  // links to the Rule-Setting session's harvest/negate AutomationRule ids we provisioned
  linkedRuleIds    Json      @default("[]")
  stage            String    @default("launch") // life-stage for auto-transitions
  enabled          Boolean   @default(true)
  lastEvaluatedAt  DateTime?
  lastDecisionAt   DateTime?
  createdAt        DateTime  @default(now())
  updatedAt        DateTime  @updatedAt
  createdBy        String?

  decisions AutopilotDecision[]

  @@index([enabled])
  @@index([marketplace])
  @@index([workspaceId])
}

// One row per conductor decision — the live (SSE) feed AND the reversible audit trail.
model AutopilotDecision {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id              String        @id @default(cuid())
  planId          String
  plan            AutopilotPlan @relation(fields: [planId], references: [id], onDelete: Cascade)
  at              DateTime      @default(now())
  cycle           String // fast | slow | event | backtest
  module          String // bid|budget|dayparting|rank|placement|harvest|negate|safety
  campaignId      String?
  action          String // BID_RAISE|BID_LOWER|BUDGET_UP|BUDGET_DOWN|PLACEMENT|RANK|HARVEST|NEGATE|SUPPRESS|RESUME|NOOP
  before          Json?
  after           Json?
  reason          String
  status          String        @default("PROPOSED") // PROPOSED|APPLIED|SKIPPED|DENIED|ROLLED_BACK
  executionId     String? // → existing audit/sync row for one-click rollback
  /// SG.9 — the delivery handle. `updateCampaignWithSync` returns at ENQUEUE: `ok:true` means
  /// the row is queued, NOT that Amazon took it — the write gate runs later in ads-sync.worker
  /// and can stamp SKIPPED/WRITE_GATE_DENIED (measured on this account: 298 of 398 budget
  /// writes in one week). So a decision keeps its queue id and the A.I. tab reads the queue's
  /// `syncStatus` for the truth, exactly as attachDeliveryData does for suggestions (SG.3).
  outboundQueueId String?
  source          String        @default("autopilot") // autopilot | rule-setting (coordinated/linked)

  @@index([planId, at])
  @@index([status])
  @@index([workspaceId])
}

// RS.1 — a named, reusable rank GOAL ("Own Top of Search", "Defend", "Rest of
// Search", "Pause"). Dropped onto AdSchedule windows (by key) and used as a
// schedule baseline. "Rank" on Amazon = a Top-of-Search impression-share target
// held by bid-to-win, so a target is {placement + targetIS + ACOS/CPC guardrails};
// the RS closed loop (RS.5) converges bids toward targetISPct within the caps.
model RankTarget {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id              String   @id @default(cuid())
  key             String // slug: own-top | defend-top | rest-of-search | pause | custom-…
  name            String
  // PLACEMENT_TOP | PLACEMENT_REST_OF_SEARCH | PLACEMENT_PRODUCT_PAGE
  placement       String   @default("PLACEMENT_TOP")
  targetISPct     Int? // target Top-of-Search impression share % (0-100); null = no IS target
  acosCapPct      Int? // ACOS ceiling % the loop must respect; null = use campaign/global default
  maxCpcCents     Int? // hard bid ceiling the loop may set; null = use CPC-ceiling guardrail
  biasPct         Int? // starting placement-bias % (0-900) applied on entry
  // MP — motion profile: HOW the loop moves the bias (all null/false = today's behaviour).
  jumpStartPct    Int? // opening bid: on entry, SNAP straight to this % in one cycle; null = gradual ramp to biasPct
  stepUpPct       Int? // gradual climb step %/cycle; null = 15 (25 all-out)
  stepDownPct     Int? // ease step %/cycle; null = SNAP down to floor on a plan change (today); a number = gradual, never snap
  maxBiasPct      Int? // ceiling the climb won't exceed; null = 900
  keepClimbing    Boolean  @default(false) // after the jump, keep stepping to the ceiling even with NO signal (bounded by ceiling + ACOS cap)
  pause           Boolean  @default(false) // this target = pause delivery in the window
  // MB.1 — the floor a `pause` (Min bid) target holds bids at, in cents. null = the
  // engine's legacy 2¢ constant, so every existing Min-bid window behaves exactly as
  // before until an operator sets a number. Amazon's own SP minimum is 2¢, so values
  // below that are clamped up rather than rejected. Ignored unless `pause` is true.
  floorBidCents   Int?
  // RS.1.1 — "all-out": the defend loop IGNORES acosCapPct and holds the slot at
  // any cost up to maxCpcCents (null maxCpc = truly unbounded). For windows where
  // winning the rank matters more than margin. maxCpcCents stays a runaway guard.
  allOut          Boolean  @default(false)
  // BL — blended multi-placement strategy. When set (non-empty), the engine drives
  // EACH lane's placement simultaneously in one combined write (Top + Rest of Search +
  // Product pages), instead of the single `placement` above (which zeros the other
  // search placement). null/[] => legacy single-placement behaviour (unchanged).
  // Shape: [{ placement, biasPct, maxBiasPct?, targetISPct?, acosCapPct?, stepUpPct?,
  //   stepDownPct?, keepClimbing?, allOut? }]. Per-lane signal: Top=Amazon Top-IS,
  //   Rest=SQP brand share, Product=open-loop (set-and-hold, no chase).
  lanes           Json? // BL — per-placement lane specs; null = single-placement (legacy)
  // BL — base-bid directive (the campaign's base bid the placement multipliers stack on).
  // mode: null/'hold' = don't touch (today); 'absolute' = set ad-group default to
  // bidValueCents; 'suppress' = floor to ~2¢ (placements still set). 'deltaPct' is
  // reserved (needs baseline memory — wired in a follow-up).
  bidMode         String? // null|'hold'|'absolute'|'suppress'|'deltaPct'
  bidValueCents   Int? // for 'absolute' — set ad-group default bid to this
  bidDeltaPct     Int? // reserved for 'deltaPct' (±% on base bid)
  color           String? // UI swatch (hex)
  builtIn         Boolean  @default(false) // seeded preset — not user-deletable
  sortOrder       Int      @default(0)
  // RTC — scope: both null = global library swatch (the default); set = a custom
  // swatch visible only on that product family / campaign. Built-ins stay global.
  scopeProductId  String?
  scopeCampaignId String?
  createdBy       String?
  createdAt       DateTime @default(now())
  updatedAt       DateTime @updatedAt
  @@unique([workspaceId, key], name: "workspace_key", map: "RankTarget_workspace_key_key")
  @@index([workspaceId])
}

// RTPL — a named, reusable rank SCHEDULE template (account-global). Saves the painted
