  windows          Json     @default("[]") // [{ days:[0-6], startHour, endHour, targetKey }] (RankWin shape)
  defaultTargetKey String? // baseline that loads alongside the windows
  createdBy        String?
  createdAt        DateTime @default(now())
  updatedAt        DateTime @updatedAt

