// ── Trading Desk automation safety spine (TD.0) ─────────────────────────────
// Single-row runtime state for the ad-automation engine: the global autonomy
// dial + the circuit-breaker halt. The env kill-switch (NEXUS_ADS_AUTOMATION_KILL)
// stays as a deploy-level backstop; THIS row lets an operator (or the anomaly
// guard) halt/resume + change posture at runtime without a deploy.
model AdsAutomationState {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id String @id @default("singleton")

  // Global posture override. OFF = nothing runs; SUGGEST = force every rule to
  // dry-run (propose only); AUTO = respect each rule's own enabled/dryRun.
  //
  // ACR.0.3: defaults to SUGGEST, not AUTO. This row is created by an upsert on
  // first read, so the default is what an environment nobody has configured
  // runs at — and a safety dial whose unconfigured state is "full autonomy" is
  // not a safety dial. Existing rows keep whatever the operator set.
  autonomy String @default("SUGGEST") // OFF | SUGGEST | AUTO

  // Circuit-breaker. When halted, the evaluator + write-gate refuse automation
  // writes until an operator (or auto-cooldown) resumes.
  halted     Boolean   @default(false)
  haltedAt   DateTime?
  haltReason String?
  haltedBy   String? // 'operator:<id>' | 'auto:anomaly-guard'

  // Anomaly-guard thresholds (null = use service defaults). Trips a halt when
  // account ad spend in the trailing hour, or automation actions/hour, exceed.
  maxHourlySpendCentsEur Int?
  maxActionsPerHour      Int?

  // SG.5 — the account default ACoS target, INTEGER percent (30 = 30% — never a
  // fraction; the 0.3-vs-30 encoding trap is live in this codebase). ONE reader:
  // bid_apply's targetAcos/curBidTargetAcos ops fall back to it when the rule
  // itself carries no target. Null = no default; those ops refuse as before.
  defaultTargetAcosPct Int?

  // Last anomaly-guard evaluation, for observability.
  lastCheckedAt DateTime?
  updatedAt     DateTime  @updatedAt
  @@index([workspaceId])
}

// R0.1 — Amazon Data & Reports strategy (docs/AMAZON_DATA_STRATEGY.md).
// The generic "every report pull, stamped with its freshness" registry:
// one row per report request (Reports API / Data Kiosk / data-API pull),
// regardless of where the parsed rows land (SettlementReport, etc. stay).
// The freshness + audit spine the Reports hub + reconciliation cockpit
// read from. Additive + empty on deploy; non-destructive.
model AmazonReportRun {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id               String    @id @default(cuid())
  reportType       String // SP-API report type (GET_*) / Data Kiosk query / data-API label
  marketplace      String? // marketplace id or short code; null = account-wide
  source           String    @default("REPORTS_API") // REPORTS_API | DATA_KIOSK | DATA_API
  status           String    @default("REQUESTED") // REQUESTED | IN_PROGRESS | DONE | FATAL | CANCELLED | SKIPPED
  reportId         String? // Amazon report id (null while pending/failed)
  reportDocumentId String?
  dataStartTime    DateTime? // window covered by this report
  dataEndTime      DateTime?
  rowCount         Int? // parsed rows, when known
  rawStored        Boolean   @default(false) // did we keep the raw file?
  rawRef           String? // pointer to raw storage (e.g. SettlementReport.id, S3 key)
  freshAsOf        DateTime? // "Amazon data current as of …" (drives the freshness surface)
  errorMessage     String?
  triggeredBy      String? // 'cron' | 'manual' | userId
  requestedAt      DateTime  @default(now())
  completedAt      DateTime?
  createdAt        DateTime  @default(now())
  updatedAt        DateTime  @updatedAt

  @@index([reportType, requestedAt(sort: Desc)])
  @@index([marketplace, reportType])
  @@index([status, requestedAt(sort: Desc)])
  @@unique([workspaceId, reportId], name: "workspace_reportId", map: "AmazonReportRun_workspace_reportId_key")
  @@index([workspaceId])
}

/// Maps one shared variant SKU to every eBay listing (ItemID) that contains it,
/// so a stock change can fan out to all of them. See docs/superpowers/specs/2026-06-27-ebay-shared-variant-sku-sync-design.md
model SharedListingMembership {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                 String    @id @default(cuid())
  marketplace        String // 'IT' | 'DE' | 'FR' | 'ES' | 'UK'
  sku                String // shared variant SKU (eBay Custom Label)
  itemId             String // eBay ItemID of the listing containing this variant
  parentSku          String // parent listing grouping (operator-facing)
  productId          String? // Nexus product whose StockLevel feeds this SKU
  variationSpecifics Json // { "Size": "M", "Color": "Nero" }
  price              Decimal?  @db.Decimal(10, 2) // per-listing price; null → fall back to child Product price
  status             String    @default("ACTIVE") // ACTIVE | ENDED
  // SC.0 — per-variant control on shared (multi-listing) eBay: followPool=false
  // excludes exactly this variant of this listing from the pool fan-out
  // ("everything real-time except one variant"). stockBuffer mirrors the
  // ChannelListing concept for the shared lane (field now, UI later — D3).
  followPool         Boolean   @default(true)
  stockBuffer        Int       @default(0)
  lastQtyPushed      Int?
  lastPushedAt       DateTime?
  lastError          String?
  // Round-trip integrity (2026-07-17): the FULL flat-file row as the operator
  // saved it (minus _internal keys) — the Lane-B twin of
  // ChannelListing.flatFileSnapshot. Row synthesis overlays this verbatim so a
  // save→reload reproduces exactly what the operator left; live fields
  // (item id, fan-out quantity) still come from live data on read.
  flatFileSnapshot   Json?
  createdAt          DateTime  @default(now())
  updatedAt          DateTime  @updatedAt

  // MAP.2a — which connected account this row belongs to.
  channelConnection   ChannelConnection? @relation(fields: [channelConnectionId], references: [id], onDelete: SetNull)
  channelConnectionId String?

  @@unique([workspaceId, marketplace, itemId, sku], name: "marketplace_itemId_sku", map: "SharedListingMembership_marketplace_itemId_sku_key")
  @@index([channelConnectionId])
  @@index([sku, marketplace])
  @@index([productId])
  @@index([workspaceId])
}

// ── SC.0 — Sync Control (2026-07-21) ─────────────────────────────────────
// Layer C: per channel-market master policy. pushesPaused is the operator
// kill-switch (mutes ALL outbound quantity pushes for that channel+market);
// newListingDefaultMode decides how listings are born there
// ('FOLLOW' | 'PAUSED'). Absent row = FOLLOW + not paused (today's behavior).
model SyncChannelPolicy {
  // Business ownership comes from verified database context.
  workspaceId String @default(dbgenerated("NULLIF(current_setting('nexus.workspace_id', true), '')"))
  id                    String    @id @default(cuid())
  channel               String // 'AMAZON' | 'EBAY' | 'SHOPIFY' | ...
  marketplace           String // 'IT', 'DE', ... or '*' for channel-wide
  pushesPaused          Boolean   @default(false)
  newListingDefaultMode String    @default("FOLLOW") // FOLLOW | PAUSED
  // SC.5 — cutoff for the PAUSED default: only listings created AFTER this
  // moment are auto-paused (kill-switch toggles never move the cutoff).
  newListingModeSetAt   DateTime?
  updatedAt             DateTime  @updatedAt
  createdAt             DateTime  @default(now())

  // MAP.2a — which connected account this row belongs to.
  channelConnection   ChannelConnection? @relation(fields: [channelConnectionId], references: [id], onDelete: SetNull)
  channelConnectionId String?

  // MAP.2b — without the account dimension an account-level sync pause is
  // impossible: pausing eBay would pause every eBay account at once.
  @@unique([workspaceId, channel, marketplace, channelConnectionId], name: "channel_marketplace", map: "SyncChannelPolicy_channel_marketplace_conn_key")
  @@index([channelConnectionId])
  @@index([workspaceId])
}

