}
function readCaps() {
  let text
  try { text = readFileSync(CAPS_SOURCE, 'utf8') } catch { return null }
  const block = text.match(/export const EDITOR_CAPS = \{([\s\S]*?)\n\} as const/)
  if (!block) return null
