  for (const m of block[1].matchAll(/(\w+):\s*\{\s*width:\s*(\d+),\s*height:\s*(\d+)/g)) {
    caps[m[1]] = { width: Number(m[2]), height: Number(m[3]) }
  }
  return Object.keys(caps).length ? caps : null
}

